INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21204, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "拆毁", "is_correct": true, "explanation": "正确：“拆毁”与“构建”相反，指把建成的东西拆掉。"}, {"text": "检查", "is_correct": false, "explanation": "与“构建”没有反义关系，“检查”指仔细查看是否有问题。"}, {"text": "记录", "is_correct": false, "explanation": "与“构建”没有反义关系，“记录”指把信息写下来。"}, {"text": "研究", "is_correct": false, "explanation": "与“构建”没有反义关系，“研究”指深入探讨。"}], "correct_answer": "拆毁", "explanations": {"拆毁": "正确：“拆毁”与“构建”相反，指把建成的东西拆掉。", "检查": "与“构建”没有反义关系，“检查”指仔细查看是否有问题。", "记录": "与“构建”没有反义关系，“记录”指把信息写下来。", "研究": "与“构建”没有反义关系，“研究”指深入探讨。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26accaa6-266c-48d1-a7a2-07e94e88f0e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21204, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把东西搭在一起做出一个新的。", "primary_collocate": null, "pronunciation": "gòu jiàn", "ipa": "kou˥˩ tɕjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "公司想构建一个新网站。", "target_word": "构建", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们正在构建新的学习平台。", "target_word": "构建", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们一起构建了一个小木屋。", "target_word": "构建", "complexity_tier": "T3", "furigana": "wǒ men yì qǐ gòu jiàn le yí gè xiǎo mù wū.", "sentence_source": "generated"}, {"text": "孩子用积木构建了一座城堡。", "target_word": "构建", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师帮我们构建知识体系。", "target_word": "构建", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司花了三年构建新系统。", "target_word": "构建", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友之间的信任要慢慢构建。", "target_word": "构建", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市政府计划构建一个新的交通网。", "target_word": "构建", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工程师先构建了这个软件的框架。", "target_word": "构建", "complexity_tier": "T3", "furigana": "gōng chéng shī xiān gòu jiàn le zhè ge ruǎn jiàn de kuàng jià.", "sentence_source": "generated"}, {"text": "他在游戏里构建了一座城市。", "target_word": "构建", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "构建了", "label": "体标"}, {"form": "构建着", "label": "体标"}, {"form": "構建", "label": "繁体"}], "register": "书面", "sense_fingerprint": "把各部分组合起来，建成新的整体", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be5ee50c-f9af-43f9-b71d-60fc13a41298') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21204, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "吃", "is_correct": false, "explanation": "语义：网站是无形的，不能被“吃”。"}, {"text": "驾驶", "is_correct": false, "explanation": "搭配：“驾驶”的对象是车辆等交通工具，不说“驾驶网站”。"}, {"text": "喂养", "is_correct": false, "explanation": "搭配：“喂养”用于动物，不说“喂养网站”。"}, {"text": "构建", "is_correct": true, "explanation": "正确：“构建一个新网站”指搭建，与语境相符。"}], "explanations": {"吃": "语义：网站是无形的，不能被“吃”。", "驾驶": "搭配：“驾驶”的对象是车辆等交通工具，不说“驾驶网站”。", "喂养": "搭配：“喂养”用于动物，不说“喂养网站”。", "构建": "正确：“构建一个新网站”指搭建，与语境相符。"}, "sentence_index": 0, "correct_answer": "构建"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "服务员构建了一杯咖啡。", "explanation": "这里应该用〈冲〉或〈泡〉。咖啡是冲泡出来的，不说“构建”。"}, {"text": "妈妈构建了一个蛋糕。", "explanation": "这里应该用〈制作〉。蛋糕是做出来的食物，不说“构建”。"}, {"text": "他构建了一首诗。", "explanation": "这里应该用〈写〉。诗是写出来的，不说“构建”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26accaa6-266c-48d1-a7a2-07e94e88f0e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21204, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "烤", "is_correct": false, "explanation": "语义：信任是抽象的感情，不能被“烤”。"}, {"text": "扛", "is_correct": false, "explanation": "搭配：“扛”多用于重物，不与“信任”搭配。"}, {"text": "冻", "is_correct": false, "explanation": "语义：“冻”指温度降低使物体变硬，不用于抽象的信任。"}, {"text": "构建", "is_correct": true, "explanation": "正确：“慢慢构建信任”指逐步建立，与语境相符。"}], "explanations": {"烤": "语义：信任是抽象的感情，不能被“烤”。", "扛": "搭配：“扛”多用于重物，不与“信任”搭配。", "冻": "语义：“冻”指温度降低使物体变硬，不用于抽象的信任。", "构建": "正确：“慢慢构建信任”指逐步建立，与语境相符。"}, "sentence_index": 6, "correct_answer": "构建"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "农民构建了一片小麦。", "explanation": "这里应该用〈种植〉。农作物要说“种植”，不说“构建”。"}, {"text": "陶工构建了一个花瓶。", "explanation": "这里应该用〈烧制〉。陶瓷器皿是烧制出来的，不说“构建”。"}, {"text": "画家构建了一幅画。", "explanation": "这里应该用〈画〉。画是画出来的，“构建”多用于较大的系统或整体结构。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26accaa6-266c-48d1-a7a2-07e94e88f0e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21204, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们把新系统构建了好。", "corrected_sentence": "他们把新系统构建好了。", "error_description": "补语位置错误：结果补语“好”应紧接动词“构建”，句末再用“了”，应说“构建好了”，不能说“构建了好”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26accaa6-266c-48d1-a7a2-07e94e88f0e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21204, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们明天构建了一个小网站。", "corrected_sentence": "他们明天构建一个小网站。", "error_description": "体标错误：“了”表示已经完成，不能与表示将来的“明天”同用，应说“明天构建一个小网站”，去掉“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26accaa6-266c-48d1-a7a2-07e94e88f0e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
