INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21210, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把人或东西分开，不让它们在一起。", "primary_collocate": null, "pronunciation": "gé lí", "ipa": "kɤ˧˥ li˧˥", "syllable_count": 2, "sentences": [{"text": "老师把吵闹的两个孩子隔离开。", "target_word": "隔离", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不小心接触了病人，需要隔离。", "target_word": "隔离", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗生病了，要和别的狗隔离。", "target_word": "隔离", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请先把新买的鱼隔离几天。", "target_word": "隔离", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "为了安全，工人把危险的区域隔离出来。", "target_word": "隔离", "complexity_tier": "T3", "furigana": "wèi le ān quán, gōng rén bǎ wēi xiǎn de qū yù gé lí chū lái.", "sentence_source": "generated"}, {"text": "他发烧了，医生让他隔离。", "target_word": "隔离", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈让他在房间里隔离，不许出门。", "target_word": "隔离", "complexity_tier": "T3", "furigana": "mā ma ràng tā zài fáng jiān lǐ gé lí, bù xǔ chū mén.", "sentence_source": "generated"}, {"text": "这些学生已经隔离三天了。", "target_word": "隔离", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们要把好水果和坏水果隔离开。", "target_word": "隔离", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈把感冒的我隔离在小房间里。", "target_word": "隔离", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "隔离了", "label": "完成体"}, {"form": "隔离过", "label": "经历体"}, {"form": "隔离开", "label": "复合词"}, {"form": "隔离期", "label": "复合词"}, {"form": "隔离室", "label": "复合词"}], "register": "中性", "sense_fingerprint": "隔离：动词，把人或东西分开放，不让它们待在一起", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69d1a7d1-3aee-412f-b2bc-3fd1c3340546') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21210, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "隔离", "is_correct": true, "explanation": "正确：把吵闹的两个孩子分开，要用“隔离开”。"}, {"text": "煮", "is_correct": false, "explanation": "语义：“煮”指加热至沸腾，用于两个孩子不合常理，与老师管理的情境不合。"}, {"text": "掀", "is_correct": false, "explanation": "搭配：“掀”用于盖子、被子等，不说“掀开孩子”。"}, {"text": "切", "is_correct": false, "explanation": "语义：“切”指切割成块，用于人既不合常理，也与句意不符。"}], "explanations": {"隔离": "正确：把吵闹的两个孩子分开，要用“隔离开”。", "煮": "语义：“煮”指加热至沸腾，用于两个孩子不合常理，与老师管理的情境不合。", "掀": "搭配：“掀”用于盖子、被子等，不说“掀开孩子”。", "切": "语义：“切”指切割成块，用于人既不合常理，也与句意不符。"}, "sentence_index": 0, "correct_answer": "隔离"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "两家公司隔离成了一家。", "explanation": "这里应该用〈合并〉。隔离是把东西分开，不让它们在一起，与“合并成一家”相反。"}, {"text": "我们热情地隔离新同学。", "explanation": "这里应该用〈欢迎〉。隔离是使分开、不让接触，与“热情”迎接新同学的意思相反。"}, {"text": "请把这些书隔离在一起。", "explanation": "这里应该用〈放在一起〉。隔离表示分开，与“在一起”矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5be34bbc-9336-40b1-bf28-c1b2e30ae0c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21210, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "隔离", "is_correct": true, "explanation": "正确：妈妈不许他出门，要把他隔离在房间里，“隔离”与“不许出门”相合。"}, {"text": "拥抱", "is_correct": false, "explanation": "语义：拥抱是亲近的动作，与“不许出门”的管束情境相反。"}, {"text": "陪", "is_correct": false, "explanation": "语义：“陪”是陪伴，与“让他在房间里，不许出门”的意思相反。"}, {"text": "照顾", "is_correct": false, "explanation": "搭配：“照顾”后面接的是人，但句中的“房间里”不能与“照顾”搭配成“照顾在房间里”。"}], "explanations": {"隔离": "正确：妈妈不许他出门，要把他隔离在房间里，“隔离”与“不许出门”相合。", "拥抱": "语义：拥抱是亲近的动作，与“不许出门”的管束情境相反。", "陪": "语义：“陪”是陪伴，与“让他在房间里，不许出门”的意思相反。", "照顾": "搭配：“照顾”后面接的是人，但句中的“房间里”不能与“照顾”搭配成“照顾在房间里”。"}, "sentence_index": 6, "correct_answer": "隔离"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这两块布料可以隔离缝在一起。", "explanation": "这里应该用〈缝〉。隔离是使分开，不能把布料缝在一起。"}, {"text": "这几个零件可以隔离成一台机器。", "explanation": "这里应该用〈组合〉。隔离是把东西分开，不能把零件合成一台机器。"}, {"text": "两条河在这里隔离，形成一条大河。", "explanation": "这里应该用〈汇合〉。隔离是使分开，与两条河汇合成一条大河的意思相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5be34bbc-9336-40b1-bf28-c1b2e30ae0c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21210, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈把他隔离了在房间里。", "corrected_sentence": "妈妈把他隔离在房间里。", "error_description": "错误：“隔离了在房间里”。正确：“隔离在房间里”。“了”不能插在动词和表示处所的“在”之间；要表示完成，应放在句末，如“隔离在房间里了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5be34bbc-9336-40b1-bf28-c1b2e30ae0c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21210, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "把小狗隔离笼子里。", "corrected_sentence": "把小狗隔离在笼子里。", "error_description": "错误：“隔离笼子里”缺少表示处所的介词“在”。正确：“把小狗隔离在笼子里。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5be34bbc-9336-40b1-bf28-c1b2e30ae0c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
