INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21214, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "最下面的一层，比如楼房的下面。", "primary_collocate": null, "pronunciation": "dǐ céng", "ipa": "ti˨˩˦ tsʰɤŋ˧˥", "syllable_count": 2, "sentences": [{"text": "我家住在这栋楼的底层。", "target_word": "底层", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "底层有一家小超市。", "target_word": "底层", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人腿不好，想住底层。", "target_word": "底层", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电梯坏了，我们从底层走上去。", "target_word": "底层", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "商店在大楼的底层，很好找。", "target_word": "底层", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨时，底层的房间有点儿湿。", "target_word": "底层", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个书架的底层放着旧书。", "target_word": "底层", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "底层的窗户外面是一个小花园。", "target_word": "底层", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们在楼房底层玩球。", "target_word": "底层", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把自行车放在底层的车库里。", "target_word": "底层", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "底層", "label": "繁体"}], "register": "中性", "sense_fingerprint": "楼房或物体最下面的一层", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cfbd5d03-db38-4b5a-b66d-53264770e077') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21214, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "底层", "is_correct": true, "explanation": "底层：dǐ céng，指楼房最下面的一层。"}, {"text": "地层", "is_correct": false, "explanation": "dì（第四声）与 dǐ（第三声）声调不同，意思是地层（地质的岩层）。"}, {"text": "顶层", "is_correct": false, "explanation": "dǐng（第三声）与 dǐ 韵母不同（多一个 -ng），意思是顶部的一层，与底层相反。"}, {"text": "里层", "is_correct": false, "explanation": "lǐ 与 dǐ 声母不同，意思是里面的一层。"}], "explanations": {"底层": "底层：dǐ céng，指楼房最下面的一层。", "地层": "dì（第四声）与 dǐ（第三声）声调不同，意思是地层（地质的岩层）。", "顶层": "dǐng（第三声）与 dǐ 韵母不同（多一个 -ng），意思是顶部的一层，与底层相反。", "里层": "lǐ 与 dǐ 声母不同，意思是里面的一层。"}, "sentence_index": null, "correct_answer": "底层"}, "level_3": {"options": [{"text": "底层", "is_correct": true, "explanation": "底层指楼房最下面的一层，这里指住所所在的楼层。"}, {"text": "钥匙", "is_correct": false, "explanation": "语义：钥匙是开锁的工具，不是住所所在的位置，句意说不通。"}, {"text": "雨伞", "is_correct": false, "explanation": "语义：雨伞是用具，不能作为住的地方。"}, {"text": "地毯", "is_correct": false, "explanation": "搭配：“住在……的”要接楼层或房间，“地毯”不能作为住所。"}], "explanations": {"底层": "底层指楼房最下面的一层，这里指住所所在的楼层。", "钥匙": "语义：钥匙是开锁的工具，不是住所所在的位置，句意说不通。", "雨伞": "语义：雨伞是用具，不能作为住的地方。", "地毯": "搭配：“住在……的”要接楼层或房间，“地毯”不能作为住所。"}, "sentence_index": 0, "correct_answer": "底层"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他爬上底层，看了一眼日出，风很大。", "explanation": "这里应该用〈楼顶〉。楼顶位置最高，爬上去才能看日出；底层在最下面，不能说“爬上底层”。"}, {"text": "这座塔的底层有十二层。", "explanation": "这里应该用〈塔身〉。塔身指整座塔的主体，可以有很多层；底层指最下面一层，不能有十二层。"}, {"text": "这栋大楼的底层很会跳舞。", "explanation": "这里应该用〈居民〉。居民是人，会跳舞；底层是楼层的一层，不会跳舞。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '286cee17-2cf1-4c71-9582-97def2f7a317') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21214, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "底层", "is_correct": true, "explanation": "底层指书架最下面的一层，与“放着旧书”相合。"}, {"text": "白云", "is_correct": false, "explanation": "语义：白云是天上的水汽凝结物，不能作为书架的部分。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户是房屋的开口，不能在上面“放着旧书”。"}, {"text": "把手", "is_correct": false, "explanation": "搭配：“放着旧书”要求容器或空间，“把手”不能放东西。"}], "explanations": {"底层": "底层指书架最下面的一层，与“放着旧书”相合。", "白云": "语义：白云是天上的水汽凝结物，不能作为书架的部分。", "窗户": "语义：窗户是房屋的开口，不能在上面“放着旧书”。", "把手": "搭配：“放着旧书”要求容器或空间，“把手”不能放东西。"}, "sentence_index": 6, "correct_answer": "底层"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他沿着底层走上去。", "explanation": "这里应该用〈楼梯〉。楼梯是可以沿着走上去的结构；底层指最下面一层，不是可以沿着走的路线。"}, {"text": "他打开了底层。", "explanation": "这里应该用〈门〉。门可以打开；底层是楼层，不是能打开的东西。"}, {"text": "他把底层拉上了。", "explanation": "这里应该用〈窗帘〉。窗帘可以拉上；底层是楼层，不能拉上。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '286cee17-2cf1-4c71-9582-97def2f7a317') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21214, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们把车停底层。", "corrected_sentence": "我们把车停在底层。", "error_description": "介词漏用：表示处所的“停”后要加“在”，应说“停在底层”，不能说“停底层”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '286cee17-2cf1-4c71-9582-97def2f7a317') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21214, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他曾经住底层。", "corrected_sentence": "他曾经住过底层。", "error_description": "助词漏用：“曾经”表示经历，要与“过”搭配，应说“住过底层”，不能省去“过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '286cee17-2cf1-4c71-9582-97def2f7a317') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
