INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21216, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "盖是放在东西上面的一个东西，比如锅盖。", "primary_collocate": null, "pronunciation": "gài", "ipa": "kai˥˩", "syllable_count": 1, "sentences": [{"text": "这个锅有一个大盖。", "target_word": "盖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "汤好了，请把锅的盖打开。", "target_word": "盖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "杯子的盖掉在地上了。", "target_word": "盖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个饭盒的盖坏了。", "target_word": "盖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个红色的盖是我的。", "target_word": "盖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个塑料箱的盖很大。", "target_word": "盖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "盖太小，所以放不上去。", "target_word": "盖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把汤锅的盖拿开了。", "target_word": "盖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想给锅配一个新盖。", "target_word": "盖", "complexity_tier": "T3", "furigana": "wǒ xiǎng gěi guō pèi yí gè xīn gài", "sentence_source": "generated"}, {"text": "水壶的盖是塑料做的。", "target_word": "盖", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个盖", "label": "量词"}, {"form": "盖子", "label": "复合"}, {"form": "蓋", "label": "繁体"}], "register": "中性", "sense_fingerprint": "盖：放在锅、杯等东西上面的盖子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c5c45db-5c3c-48d5-93a0-704ede77efae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21216, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "盖", "is_correct": true, "explanation": "正确：盖 gài，指锅、杯等东西上面的盖子。"}, {"text": "怪", "is_correct": false, "explanation": "guài（第四声）比 gài 多一个介音 u，意思是奇怪。"}, {"text": "害", "is_correct": false, "explanation": "hài（第四声）与 gài 声母不同（h 与 g），意思是伤害。"}, {"text": "干", "is_correct": false, "explanation": "gàn（第四声）与 gài 韵母不同（an 与 ai），意思是做、干。"}], "explanations": {"盖": "正确：盖 gài，指锅、杯等东西上面的盖子。", "怪": "guài（第四声）比 gài 多一个介音 u，意思是奇怪。", "害": "hài（第四声）与 gài 声母不同（h 与 g），意思是伤害。", "干": "gàn（第四声）与 gài 韵母不同（an 与 ai），意思是做、干。"}, "sentence_index": null, "correct_answer": "盖"}, "level_3": {"options": [{"text": "盖", "is_correct": true, "explanation": "正确：“盖”指锅的盖子，“大盖”即较大的锅盖，符合语境。"}, {"text": "门", "is_correct": false, "explanation": "语义：锅上没有“门”这一部件，“大门”不能用来说锅的部件。"}, {"text": "窗", "is_correct": false, "explanation": "语义：锅身上没有“窗”，“有一个大窗”这种说法不成立。"}, {"text": "膝", "is_correct": false, "explanation": "体貌：“膝”是人体部位，不能用来描述锅的部件。"}], "explanations": {"盖": "正确：“盖”指锅的盖子，“大盖”即较大的锅盖，符合语境。", "门": "语义：锅上没有“门”这一部件，“大门”不能用来说锅的部件。", "窗": "语义：锅身上没有“窗”，“有一个大窗”这种说法不成立。", "膝": "体貌：“膝”是人体部位，不能用来描述锅的部件。"}, "sentence_index": 0, "correct_answer": "盖"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我家的饭盒有一根盖，坏了。", "explanation": "量词错误：盖子应用量词“个”，“根”用于细长的东西，不能用来数饭盒的盖子。"}, {"text": "那个饭盒有一座盖，坏了。", "explanation": "量词错误：盖子应用量词“个”，“座”用于房屋、山等大型的东西，不能用来数饭盒的盖子。"}, {"text": "这个饭盒有一只盖，坏了。", "explanation": "量词错误：盖子应用量词“个”，“只”一般用于动物或成对物品中的一个，不能用来数饭盒的盖子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8df80060-e335-49eb-bdcd-ad2ec8bd1e8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21216, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "盖", "is_correct": true, "explanation": "正确：盖 gài，指锅、杯等东西上面的盖子。"}, {"text": "改", "is_correct": false, "explanation": "gǎi（第三声）与 gài（第四声）声调不同，意思是改变。"}, {"text": "带", "is_correct": false, "explanation": "dài（第四声）与 gài 声母不同（d 与 g），意思是带领或带子。"}, {"text": "告", "is_correct": false, "explanation": "gào（第四声）与 gài 韵母不同（ao 与 ai），意思是告诉。"}, {"text": "该", "is_correct": false, "explanation": "gāi（第一声）与 gài 只差声调，意思是应该。"}], "explanations": {"盖": "正确：盖 gài，指锅、杯等东西上面的盖子。", "改": "gǎi（第三声）与 gài（第四声）声调不同，意思是改变。", "带": "dài（第四声）与 gài 声母不同（d 与 g），意思是带领或带子。", "告": "gào（第四声）与 gài 韵母不同（ao 与 ai），意思是告诉。", "该": "gāi（第一声）与 gài 只差声调，意思是应该。"}, "sentence_index": null, "correct_answer": "盖"}, "level_3": {"options": [{"text": "盖", "is_correct": true, "explanation": "正确：“盖太小”指锅盖太小，所以放不到锅上，符合语境。"}, {"text": "山", "is_correct": false, "explanation": "语义：山本身很大，说“山太小”与常识矛盾，句子不通。"}, {"text": "天", "is_correct": false, "explanation": "语义：“天太小，所以放不上去”不符合常识，句子不通。"}, {"text": "嘴", "is_correct": false, "explanation": "体貌：“嘴”是人体器官，不能用来说明物件的大小与放置。"}], "explanations": {"盖": "正确：“盖太小”指锅盖太小，所以放不到锅上，符合语境。", "山": "语义：山本身很大，说“山太小”与常识矛盾，句子不通。", "天": "语义：“天太小，所以放不上去”不符合常识，句子不通。", "嘴": "体貌：“嘴”是人体器官，不能用来说明物件的大小与放置。"}, "sentence_index": 6, "correct_answer": "盖"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我家的水壶有一颗盖，很小。", "explanation": "量词错误：盖子应用量词“个”，“颗”用于小而圆的颗粒状东西，不能用来数水壶的盖子。"}, {"text": "我买的篮子有一棵盖，很大。", "explanation": "量词错误：盖子应用量词“个”，“棵”用于树木、植物，不能用来数篮子的盖子。"}, {"text": "这个水壶有一扇盖，是塑料做的。", "explanation": "量词错误：盖子应用量词“个”，“扇”用于门、窗，不能用来数水壶的盖子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8df80060-e335-49eb-bdcd-ad2ec8bd1e8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21216, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那口大锅有两只盖。", "corrected_sentence": "那口大锅有两个盖。", "error_description": "量词错误：“盖”应用量词“个”，说“两个盖”；“只”不能用来数锅盖。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8df80060-e335-49eb-bdcd-ad2ec8bd1e8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21216, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我找到了两个杯子的盖们。", "corrected_sentence": "我找到了两个杯子的盖。", "error_description": "复数错误：“盖”是物件，不能加“们”，应为“两个杯子的盖”，不能说“盖们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8df80060-e335-49eb-bdcd-ad2ec8bd1e8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21220, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "间断", "is_correct": true, "explanation": "“间断”与“连续”意义相反，指中间有停顿、不连贯。"}, {"text": "灿烂", "is_correct": false, "explanation": "与“连续”无关：“灿烂”形容光彩耀眼，不涉及是否中断。"}, {"text": "柔软", "is_correct": false, "explanation": "与“连续”无关：“柔软”形容质地松软，不是“连续”的反义。"}, {"text": "稳定", "is_correct": false, "explanation": "与“连续”无关：“稳定”指不动荡、不变化，不是“连续”的反义。"}], "correct_answer": "间断", "explanations": {"间断": "“间断”与“连续”意义相反，指中间有停顿、不连贯。", "灿烂": "与“连续”无关：“灿烂”形容光彩耀眼，不涉及是否中断。", "柔软": "与“连续”无关：“柔软”形容质地松软，不是“连续”的反义。", "稳定": "与“连续”无关：“稳定”指不动荡、不变化，不是“连续”的反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0fcc3fe-1208-4d94-900c-0cca69d3dfe5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21220, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "间断", "is_correct": true, "explanation": "“间断”与“连续”意义相反，指中间有停顿、不连贯。"}, {"text": "严格", "is_correct": false, "explanation": "与“连续”无关：“严格”形容要求高、不宽松，不涉及是否中断。"}, {"text": "陡峭", "is_correct": false, "explanation": "与“连续”无关：“陡峭”形容坡度大，不是“连续”的反义。"}, {"text": "悠闲", "is_correct": false, "explanation": "与“连续”无关：“悠闲”形容从容不忙，不表示有无中断。"}], "correct_answer": "间断", "explanations": {"间断": "“间断”与“连续”意义相反，指中间有停顿、不连贯。", "严格": "与“连续”无关：“严格”形容要求高、不宽松，不涉及是否中断。", "陡峭": "与“连续”无关：“陡峭”形容坡度大，不是“连续”的反义。", "悠闲": "与“连续”无关：“悠闲”形容从容不忙，不表示有无中断。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0fcc3fe-1208-4d94-900c-0cca69d3dfe5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21220, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "一个东西接着另一个东西，中间没有停。", "primary_collocate": null, "pronunciation": "lián xù", "ipa": "ljɛn˧˥ ɕy˥˩", "syllable_count": 2, "sentences": [{"text": "山路上连续有好几个大弯。", "target_word": "连续", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "车窗外连续闪过一排路灯。", "target_word": "连续", "complexity_tier": "T3", "furigana": "chē chuāng wài lián xù shǎn guò yī pái lù dēng", "sentence_source": "generated"}, {"text": "这部电视剧连续播了二十集。", "target_word": "连续", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "火车连续经过三个小站。", "target_word": "连续", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "路边连续出现了几家饭馆。", "target_word": "连续", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他连续说了十分钟，一直没停。", "target_word": "连续", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "电话连续响了五次，没人接。", "target_word": "连续", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "天空中连续飞过几架飞机。", "target_word": "连续", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她连续吃了三个包子，还想吃。", "target_word": "连续", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "鼓声连续响了很久。", "target_word": "连续", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "连续性", "label": "复合"}, {"form": "连续剧", "label": "复合"}, {"form": "連續", "label": "繁体"}], "register": "中性", "sense_fingerprint": "一个接着一个、中间不停", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e21b19a8-b860-4241-bf4a-a935fa36fc43') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21220, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "连续", "is_correct": true, "explanation": "“连续”在此表示弯道一个接一个地出现，中间没有间断，与“好几个大弯”相符。"}, {"text": "笔直", "is_correct": false, "explanation": "语义：“笔直”指没有弯曲，与“好几个大弯”直接矛盾。"}, {"text": "平坦", "is_correct": false, "explanation": "语义：“平坦”指路面没有起伏，与“大弯”的描述矛盾。"}, {"text": "宽阔", "is_correct": false, "explanation": "搭配：“宽阔”多修饰路面或场地的宽度，不用来说明弯道的数量和出现方式。"}], "explanations": {"连续": "“连续”在此表示弯道一个接一个地出现，中间没有间断，与“好几个大弯”相符。", "笔直": "语义：“笔直”指没有弯曲，与“好几个大弯”直接矛盾。", "平坦": "语义：“平坦”指路面没有起伏，与“大弯”的描述矛盾。", "宽阔": "搭配：“宽阔”多修饰路面或场地的宽度，不用来说明弯道的数量和出现方式。"}, "sentence_index": 0, "correct_answer": "连续"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这条铁路把两个站点连续起来了。", "explanation": "这里应该用〈连接〉。连续只说事物接续、不中断，不能用来说把两处接在一起。"}, {"text": "两根电线杆之间连续着十米的距离。", "explanation": "这里应该用〈间隔〉。连续说事物接着出现、中间不停，不能用来说两物之间相隔的距离；两物之间相隔多远要用〈间隔〉。"}, {"text": "铁路在这里连续着，一条通往北京，一条通往上海。", "explanation": "这里应该用〈分岔〉。连续说事物接着出现、中间不停，铁路在此分成两条要用〈分岔〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0fcc3fe-1208-4d94-900c-0cca69d3dfe5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21220, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "连续", "is_correct": true, "explanation": "“连续”在此表示电话一次接一次地响，中间没有停，与“响了五次”相符。"}, {"text": "静默", "is_correct": false, "explanation": "语义：“静默”指没有声音，与“响了五次”直接矛盾。"}, {"text": "懒散", "is_correct": false, "explanation": "搭配：“懒散”形容人的做事态度，不能修饰电话的响声。"}, {"text": "迟缓", "is_correct": false, "explanation": "搭配：“迟缓”形容动作或反应慢，不用来说电话响的方式。"}], "explanations": {"连续": "“连续”在此表示电话一次接一次地响，中间没有停，与“响了五次”相符。", "静默": "语义：“静默”指没有声音，与“响了五次”直接矛盾。", "懒散": "搭配：“懒散”形容人的做事态度，不能修饰电话的响声。", "迟缓": "搭配：“迟缓”形容动作或反应慢，不用来说电话响的方式。"}, "sentence_index": 6, "correct_answer": "连续"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "鼓声连续响了一下，很快就停了。", "explanation": "这里应该用〈短暂〉。连续表示中间不停地接着出现，只响一下就停要用〈短暂〉。"}, {"text": "鼓声和舞步很连续，大家都跟着跳。", "explanation": "这里应该用〈联系〉。连续不能表示事物之间有关系；鼓声与舞步相关要用〈联系〉。"}, {"text": "这面鼓很连续，很好听。", "explanation": "这里应该用〈悦耳〉。连续说的是不中断的次序，不能用来评价鼓声好听与否；评价声音要用〈悦耳〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0fcc3fe-1208-4d94-900c-0cca69d3dfe5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21220, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "车队连续了三个收费站。", "corrected_sentence": "车队连续经过了三个收费站。", "error_description": "错误在“连续”之后漏了动词“经过”。连续是形容词，不能直接带宾语，应说“连续经过”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0fcc3fe-1208-4d94-900c-0cca69d3dfe5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21220, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "连续了三个晚上排练都很辛苦。", "corrected_sentence": "连续三个晚上排练都很辛苦。", "error_description": "体标错误：“连续”作状语修饰“排练”，不能直接带体标“了”，应删去“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0fcc3fe-1208-4d94-900c-0cca69d3dfe5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
