INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21230, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "东西一点一点地变多。", "primary_collocate": null, "pronunciation": "lěi jī", "ipa": "leɪ˨˩˦ tɕi˥", "syllable_count": 2, "sentences": [{"text": "这笔钱是他每个月一点一点累积起来的。", "target_word": "累积", "complexity_tier": "T3", "furigana": "zhè bǐ qián shì tā měi gè yuè yì diǎn yì diǎn lěi jī qǐ lái de.", "sentence_source": "generated"}, {"text": "书房的柜子久没开，灰尘慢慢累积了一层。", "target_word": "累积", "complexity_tier": "T3", "furigana": "shū fáng de guì zi jiǔ méi kāi, huī chén màn màn lěi jī le yì céng.", "sentence_source": "generated"}, {"text": "他每个月都累积一些零钱。", "target_word": "累积", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "知识要靠每天一点点累积。", "target_word": "累积", "complexity_tier": "T3", "furigana": "zhī shí yào kào měi tiān yì diǎn diǎn lěi jī.", "sentence_source": "generated"}, {"text": "雪在路边累积了十几厘米。", "target_word": "累积", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "多读书，知识就会慢慢累积。", "target_word": "累积", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些年，研究所累积了大量的实验数据。", "target_word": "累积", "complexity_tier": "T3", "furigana": "zhè xiē nián, yán jiū suǒ lěi jī le dà liàng de shí yàn shù jù.", "sentence_source": "generated"}, {"text": "小问题不处理，时间长了就累积成大问题。", "target_word": "累积", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的手机里累积了很多旅行照片。", "target_word": "累积", "complexity_tier": "T3", "furigana": "tā de shǒu jī lǐ lěi jī le hěn duō lǚ xíng zhào piàn.", "sentence_source": "generated"}, {"text": "我把每天的零花钱累积起来买书。", "target_word": "累积", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "累积了", "label": "体标"}, {"form": "累积着", "label": "体标"}, {"form": "累积过", "label": "体标"}, {"form": "累积效应", "label": "复合"}], "register": "中性", "sense_fingerprint": "东西一点一点积攒、变多", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77d97711-45c9-40d1-a540-071631f184cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21230, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "累积", "is_correct": true, "explanation": "正确：“累积”指东西一点一点变多，与“每个月一点一点”相合，可以接“起来”。"}, {"text": "消耗", "is_correct": false, "explanation": "语义：“消耗”是用掉、耗尽，与句中钱是逐月攒下来的意思相反。"}, {"text": "支出", "is_correct": false, "explanation": "语义：“支出”指付出去的钱，句子说的是存下来的钱，意思不对。"}, {"text": "购买", "is_correct": false, "explanation": "搭配：“购买”后面要接所买的东西，不能说“购买起来”的钱。"}], "explanations": {"累积": "正确：“累积”指东西一点一点变多，与“每个月一点一点”相合，可以接“起来”。", "消耗": "语义：“消耗”是用掉、耗尽，与句中钱是逐月攒下来的意思相反。", "支出": "语义：“支出”指付出去的钱，句子说的是存下来的钱，意思不对。", "购买": "搭配：“购买”后面要接所买的东西，不能说“购买起来”的钱。"}, "sentence_index": 0, "correct_answer": "累积"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他这一年身高累积了五厘米。", "explanation": "这里应该用〈增长〉。身高这类个人的变化用“增长”，“累积”强调东西逐渐积聚变多。"}, {"text": "这所学校一下子累积了五个新班级。", "explanation": "这里应该用〈新增〉。「累积」指逐渐积聚，「一下子」多出的班级应说「新增」，不能用「累积」。"}, {"text": "他这次考试一下子累积了三十分。", "explanation": "这里应该用〈得〉。「累积」指逐渐积聚，一次考试的得分是一次获得，与「一下子」矛盾，应说「得了三十分」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc650faf-eef1-4b87-8649-678eec955448') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21230, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "累积", "is_correct": true, "explanation": "正确：句子说研究所多年积累了大量数据，“累积”指逐渐积聚变多，符合“这些年”。"}, {"text": "冲洗", "is_correct": false, "explanation": "搭配：“冲洗”用于照片、胶卷，不能用于实验数据。"}, {"text": "销毁", "is_correct": false, "explanation": "语义：“销毁”是毁掉，与“这些年一点一点积累”的意思相反。"}, {"text": "放映", "is_correct": false, "explanation": "搭配：“放映”的对象是电影、影片，不能用于实验数据。"}], "explanations": {"累积": "正确：句子说研究所多年积累了大量数据，“累积”指逐渐积聚变多，符合“这些年”。", "冲洗": "搭配：“冲洗”用于照片、胶卷，不能用于实验数据。", "销毁": "语义：“销毁”是毁掉，与“这些年一点一点积累”的意思相反。", "放映": "搭配：“放映”的对象是电影、影片，不能用于实验数据。"}, "sentence_index": 6, "correct_answer": "累积"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这套房子这几年累积了不少。", "explanation": "这里应该用〈增值〉。房产的价值上升用“增值”，“累积”指东西的数量逐渐积聚。"}, {"text": "客厅里累积了一台新电视。", "explanation": "这里应该用〈增添〉。一次添进一件物品用“增添”，“累积”强调逐渐积聚，不能一次得到一台。"}, {"text": "很多人累积在广场上。", "explanation": "这里应该用〈聚集〉。人群在一处集合用“聚集”，“累积”指东西逐渐积聚。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc650faf-eef1-4b87-8649-678eec955448') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21230, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这些经验是她这几年一下子累积起来的。", "corrected_sentence": "这些经验是她这几年一点一点累积起来的。", "error_description": "搭配错误：「累积」表示逐渐积聚，不能与「一下子」连用，应改为「一点一点累积起来」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc650faf-eef1-4b87-8649-678eec955448') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21230, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他的存款这几年累积在一万元。", "corrected_sentence": "他的存款这几年累积到一万元。", "error_description": "介词错误：存款累积到某个数额，应用“到”，写成“在”不通顺，应改为“累积到一万元”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc650faf-eef1-4b87-8649-678eec955448') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
