INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21232, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "发酵就是让面粉或食物里的小东西帮忙，让面团变大、变软。", "primary_collocate": null, "pronunciation": "fā jiào", "ipa": "fa˥ tɕiɑʊ˥˩", "syllable_count": 2, "sentences": [{"text": "面团要放在暖和的地方发酵。", "target_word": "发酵", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "面团发酵以后，会变大一倍。", "target_word": "发酵", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈把面团盖好，让它发酵一个小时。", "target_word": "发酵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做馒头的时候，面团要先发酵。", "target_word": "发酵", "complexity_tier": "T3", "furigana": "zuò mán tou de shí hou, miàn tuán yào xiān fā jiào.", "sentence_source": "generated"}, {"text": "发酵好的面团又软又大。", "target_word": "发酵", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "天冷的时候，面团发酵得很慢。", "target_word": "发酵", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "面包师傅说，面团已经发酵好了，可以烤了。", "target_word": "发酵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在面粉里加了酵母，等着它发酵。", "target_word": "发酵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天，包子的面皮发酵得特别快。", "target_word": "发酵", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "面团没有发酵，蒸出来的馒头又小又硬。", "target_word": "发酵", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "发酵了", "label": "体标（了）"}, {"form": "发酵粉", "label": "复合"}], "register": "口语", "sense_fingerprint": "面团因酵母等作用而变大、变软", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '026057aa-5864-49c0-96de-f25d5ea2ff13') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21232, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "发酵", "is_correct": true, "explanation": "正确：面团放在暖和的地方，正好促进酵母作用，使面团变大变软。"}, {"text": "冷藏", "is_correct": false, "explanation": "语义：冷藏要求低温，与「暖和的地方」矛盾。"}, {"text": "冷冻", "is_correct": false, "explanation": "语义：冷冻会使面团结冰，与「暖和的地方」相反。"}, {"text": "冰镇", "is_correct": false, "explanation": "搭配：「冰镇」多用于饮料、瓜果，不用于面团。"}], "explanations": {"发酵": "正确：面团放在暖和的地方，正好促进酵母作用，使面团变大变软。", "冷藏": "语义：冷藏要求低温，与「暖和的地方」矛盾。", "冷冻": "语义：冷冻会使面团结冰，与「暖和的地方」相反。", "冰镇": "搭配：「冰镇」多用于饮料、瓜果，不用于面团。"}, "sentence_index": 0, "correct_answer": "发酵"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "包饺子时要先把面团发酵成皮。", "explanation": "这里应该用〈擀〉。发酵使面团变大变软，不能把面团压成面皮。"}, {"text": "冰块放在碗里发酵。", "explanation": "这里应该用〈融化〉。发酵不指冰块遇热变成水，冰块变化要说融化。"}, {"text": "包子要用手发酵出褶子。", "explanation": "这里应该用〈捏〉。发酵不是塑形动作，用手做出褶子要说捏。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e87727d-c657-433b-85fc-ed850eeffff2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21232, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "发酵", "is_correct": true, "explanation": "正确：面团已经发酵好，所以可以烤了。"}, {"text": "切碎", "is_correct": false, "explanation": "搭配：「切碎」多用于蔬菜、肉类，不用于面团，且与「可以烤」不衔接。"}, {"text": "烧制", "is_correct": false, "explanation": "语义：烧制指用高温烧成器物，与面团发酵后烤制的过程不符。"}, {"text": "煮", "is_correct": false, "explanation": "语义：面团煮过就已经熟了，不能再拿去烤，与「可以烤了」矛盾。"}], "explanations": {"发酵": "正确：面团已经发酵好，所以可以烤了。", "切碎": "搭配：「切碎」多用于蔬菜、肉类，不用于面团，且与「可以烤」不衔接。", "烧制": "语义：烧制指用高温烧成器物，与面团发酵后烤制的过程不符。", "煮": "语义：面团煮过就已经熟了，不能再拿去烤，与「可以烤了」矛盾。"}, "sentence_index": 6, "correct_answer": "发酵"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "湿衣服要用烘干机发酵。", "explanation": "这里应该用〈烘干〉。衣物弄干要说烘干，发酵指面团因酵母变大变软，与烘干衣物无关。"}, {"text": "煤在炉子里发酵，屋子很暖和。", "explanation": "这里应该用〈燃烧〉。煤产生热量要说燃烧，发酵不指这种变化。"}, {"text": "湖面发酵了，人们可以在上面滑冰。", "explanation": "这里应该用〈结冰〉。发酵不能指水变成冰，湖面变硬要说结冰。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e87727d-c657-433b-85fc-ed850eeffff2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21232, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这批面团发酵的很好，又软又大。", "corrected_sentence": "这批面团发酵得很好，又软又大。", "error_description": "错误：「发酵」后的补语要用「得」，不能用「的」。正确形式：发酵得很好。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e87727d-c657-433b-85fc-ed850eeffff2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21232, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "面团在暖和的地方发酵得一晚上。", "corrected_sentence": "面团在暖和的地方发酵了一晚上。", "error_description": "错误：「发酵」后表示完成的时量要用「了」，不能用「得」。正确形式：发酵了一晚上。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e87727d-c657-433b-85fc-ed850eeffff2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
