INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21236, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc650faf-eef1-4b87-8649-678eec955448') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21236, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "还是和以前一样，没有变化。", "primary_collocate": null, "pronunciation": "réng", "ipa": "ɻɤŋ˧˥", "syllable_count": 1, "sentences": [{"text": "雨下了一夜，早上仍在下。", "target_word": "仍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他已经八十岁，仍每天跑步。", "target_word": "仍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过了很多年，这里仍和以前一样。", "target_word": "仍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都走了，他仍坐在教室里。", "target_word": "仍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "虽然很累，她仍坚持完成了工作。", "target_word": "仍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天已经黑了，街上仍有很多人。", "target_word": "仍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说了几次，他仍不肯休息。", "target_word": "仍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "搬家以后，我仍常去那家小店。", "target_word": "仍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师讲了两遍，我仍不太明白。", "target_word": "仍", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座城市虽然变大了，仍很安静。", "target_word": "仍", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "仍然", "label": "复合"}, {"form": "仍旧", "label": "复合"}], "register": "书面", "sense_fingerprint": "情况照旧，仍然没有改变", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77d97711-45c9-40d1-a540-071631f184cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21236, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "仍", "is_correct": true, "explanation": "正确答案：仍（réng），表示情况照旧，没有改变。"}, {"text": "扔", "is_correct": false, "explanation": "扔（rēng）与仍（réng）只是声调不同，意思是丢弃、投掷。"}, {"text": "人", "is_correct": false, "explanation": "人（rén）与仍（réng）韵尾不同：人是 n，仍是 ng，意思是人类。"}, {"text": "认", "is_correct": false, "explanation": "认（rèn）与仍（réng）韵尾和声调都不同，意思是辨认、承认。"}], "explanations": {"仍": "正确答案：仍（réng），表示情况照旧，没有改变。", "扔": "扔（rēng）与仍（réng）只是声调不同，意思是丢弃、投掷。", "人": "人（rén）与仍（réng）韵尾不同：人是 n，仍是 ng，意思是人类。", "认": "认（rèn）与仍（réng）韵尾和声调都不同，意思是辨认、承认。"}, "sentence_index": null, "correct_answer": "仍"}, "level_3": {"options": [{"text": "仍", "is_correct": true, "explanation": "正确答案：仍，表示雨还在下，情况没有改变。"}, {"text": "曾经", "is_correct": false, "explanation": "体貌：「曾经」表示过去发生过的事，与「在下」表示正在进行的状态矛盾。"}, {"text": "总是", "is_correct": false, "explanation": "语义：「总是」表示一直如此，与「下了一夜」这一次的雨不符。"}, {"text": "偶尔", "is_correct": false, "explanation": "语义：「偶尔」表示不常发生，与「下了一夜」的持续状态相反。"}], "explanations": {"仍": "正确答案：仍，表示雨还在下，情况没有改变。", "曾经": "体貌：「曾经」表示过去发生过的事，与「在下」表示正在进行的状态矛盾。", "总是": "语义：「总是」表示一直如此，与「下了一夜」这一次的雨不符。", "偶尔": "语义：「偶尔」表示不常发生，与「下了一夜」的持续状态相反。"}, "sentence_index": 0, "correct_answer": "仍"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他一年里仍长高了十厘米。", "explanation": "这里应该用〈又〉。「仍」表示情况没有变化，不能用来说长高这种变化。"}, {"text": "他第一次来北京，仍很熟悉这里的路。", "explanation": "这个词不这么用。这里误把「仍」当作〈已经〉来用；「仍」表示之前的状态延续，第一次来北京没有可以延续的熟悉感，前后矛盾。"}, {"text": "他很高兴，仍很生气。", "explanation": "这个词不这么用。这里应该用〈却〉。「仍」表示状态没有改变，「高兴」与「生气」不能同时延续，前后矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc650faf-eef1-4b87-8649-678eec955448') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21236, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "仍", "is_correct": true, "explanation": "正确答案：仍（réng），表示情况照旧，没有改变。"}, {"text": "仁", "is_correct": false, "explanation": "仁（rén）与仍（réng）韵尾不同：仁是 n，仍是 ng，意思是仁爱、善良。"}, {"text": "忍", "is_correct": false, "explanation": "忍（rěn）与仍（réng）韵尾不同，声调也不同，意思是忍耐。"}, {"text": "任", "is_correct": false, "explanation": "任（rèn）与仍（réng）韵尾和声调都不同，意思是任务、担任。"}], "explanations": {"仍": "正确答案：仍（réng），表示情况照旧，没有改变。", "仁": "仁（rén）与仍（réng）韵尾不同：仁是 n，仍是 ng，意思是仁爱、善良。", "忍": "忍（rěn）与仍（réng）韵尾不同，声调也不同，意思是忍耐。", "任": "任（rèn）与仍（réng）韵尾和声调都不同，意思是任务、担任。"}, "sentence_index": null, "correct_answer": "仍"}, "level_3": {"options": [{"text": "仍", "is_correct": true, "explanation": "正确答案：仍，表示医生说了几次，他还是不肯休息，情况没有改变。"}, {"text": "赶紧", "is_correct": false, "explanation": "语义：「赶紧」表示急着去做某事，与「不肯休息」的态度相矛盾。"}, {"text": "只好", "is_correct": false, "explanation": "语义：「只好」表示无可奈何地去做，与「他不肯休息」的主动态度不合。"}, {"text": "立刻", "is_correct": false, "explanation": "搭配：「立刻」后面一般接马上发生的动作，与「说了几次」的持续劝说不搭。"}], "explanations": {"仍": "正确答案：仍，表示医生说了几次，他还是不肯休息，情况没有改变。", "赶紧": "语义：「赶紧」表示急着去做某事，与「不肯休息」的态度相矛盾。", "只好": "语义：「只好」表示无可奈何地去做，与「他不肯休息」的主动态度不合。", "立刻": "搭配：「立刻」后面一般接马上发生的动作，与「说了几次」的持续劝说不搭。"}, "sentence_index": 6, "correct_answer": "仍"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他刚搬到这里，仍很熟悉这条街。", "explanation": "这个词不这么用。这里误把「仍」当作〈已经〉来用；刚搬来的人对这条街还不熟悉，「仍很熟悉」说明之前就熟悉，前后矛盾。"}, {"text": "我这次第一次登山，仍爬上了山顶。", "explanation": "这个词不这么用。这里误把「仍」当作〈终于〉来用；「仍」表示状态延续，第一次登山没有之前的状态可延续，应说「终于爬上了山顶」。"}, {"text": "天气突然变热了，仍很凉快。", "explanation": "这个词不这么用。「仍」表示状态没有变化，而「突然变热了」说明已经变化，两者矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc650faf-eef1-4b87-8649-678eec955448') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21236, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他一直很忙，仍他在努力工作。", "corrected_sentence": "他一直很忙，他仍在努力工作。", "error_description": "位置错误：「仍」是副词，要放在主语后面、动词前面，应说「他仍在努力工作」，不能放在主语前面。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc650faf-eef1-4b87-8649-678eec955448') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21236, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "大家都走了，在仍下棋。", "corrected_sentence": "大家都走了，仍在下棋。", "error_description": "词序错误：副词「仍」要放在「在」前面，应说「仍在下棋」，不能说「在仍下棋」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc650faf-eef1-4b87-8649-678eec955448') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
