INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21238, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "不好的、奇怪的气味。", "primary_collocate": null, "pronunciation": "yì wèi", "ipa": "i˥˩ weɪ˥˩", "syllable_count": 2, "sentences": [{"text": "我一进门，就闻到一股异味。", "target_word": "异味", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这瓶牛奶有异味，别喝了。", "target_word": "异味", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "教室里有一股奇怪的异味。", "target_word": "异味", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的包里传出一股异味。", "target_word": "异味", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "洗衣机很久不用，里面有异味。", "target_word": "异味", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "空气中有异味，大家都捂住了鼻子。", "target_word": "异味", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种异味是从下水道来的。", "target_word": "异味", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他皱着眉头说：“这里有异味。”", "target_word": "异味", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开了空气净化器，异味少多了。", "target_word": "异味", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "新买的鞋子有点异味，要放一放。", "target_word": "异味", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "異味", "label": "繁体"}, {"form": "股", "label": "量词"}], "register": "中性", "sense_fingerprint": "不好的、奇怪的气味", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f49f6dc-9e85-4217-b5c9-16c1472b39b4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21238, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "异味", "is_correct": true, "explanation": "正确。句意是进门时就闻到一股难闻的气味。"}, {"text": "声音", "is_correct": false, "explanation": "语义：“闻到”的对象是气味，不能闻到声音。"}, {"text": "光线", "is_correct": false, "explanation": "语义：光线属于视觉对象，不能被“闻到”。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“一股”计量的是气味，“颜色”不能用“一股”计量，也不能被“闻到”。"}], "explanations": {"异味": "正确。句意是进门时就闻到一股难闻的气味。", "声音": "语义：“闻到”的对象是气味，不能闻到声音。", "光线": "语义：光线属于视觉对象，不能被“闻到”。", "颜色": "搭配：“一股”计量的是气味，“颜色”不能用“一股”计量，也不能被“闻到”。"}, "sentence_index": 0, "correct_answer": "异味"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他听到包里传出一阵异味。", "explanation": "这里应该用〈歌声〉。“听到”的对象是声音，异味是气味，应说“闻到”。"}, {"text": "这件衣服的异味很鲜艳。", "explanation": "这里应该用〈颜色〉。“鲜艳”形容颜色，异味是难闻的气味，二者不搭配。"}, {"text": "他的包里传出一张异味。", "explanation": "这里应该用〈股〉。“异味”是气味，量词应用“股”；“张”用于纸张、桌子等平面的东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c9280f3-74a5-4573-a58b-972036d0ba44') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21238, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "异味", "is_correct": true, "explanation": "正确。句意是这种难闻的气味是从下水道来的。"}, {"text": "阳光", "is_correct": false, "explanation": "语义：阳光不会从下水道来，句中要说明的是难闻气味的来源。"}, {"text": "温度", "is_correct": false, "explanation": "语义：温度不是能“从下水道来”的东西，与气味无关。"}, {"text": "花香", "is_correct": false, "explanation": "搭配：下水道散发的是难闻的气味，“花香”是好闻的，与“从下水道来”不搭配。"}], "explanations": {"异味": "正确。句意是这种难闻的气味是从下水道来的。", "阳光": "语义：阳光不会从下水道来，句中要说明的是难闻气味的来源。", "温度": "语义：温度不是能“从下水道来”的东西，与气味无关。", "花香": "搭配：下水道散发的是难闻的气味，“花香”是好闻的，与“从下水道来”不搭配。"}, "sentence_index": 6, "correct_answer": "异味"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这杯咖啡的异味很香。", "explanation": "这里应该用〈味道〉。“很香”形容好闻的气味，异味是难闻的，不能说“很香”。"}, {"text": "这盏灯的异味很高。", "explanation": "这里应该用〈亮度〉。“高”可以形容亮度，但不能形容气味。"}, {"text": "鼓声响起，他听到了一阵异味。", "explanation": "这里应该用〈鼓声〉。“听到”的对象是声音，异味是气味，应说“闻到”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c9280f3-74a5-4573-a58b-972036d0ba44') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21238, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "一进教室，我就闻到一个异味。", "corrected_sentence": "一进教室，我就闻到一股异味。", "error_description": "量词错误：“异味”是气味，应用“股”，不能用“个”。正确说法是“一股异味”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c9280f3-74a5-4573-a58b-972036d0ba44') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21238, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "走廊里飘来一股很异味，有点刺鼻。", "corrected_sentence": "走廊里飘来一股异味，有点刺鼻。", "error_description": "语序错误：程度副词“很”应修饰形容词或心理动词，不能插在名词“异味”前。正确说法是“飘来一股异味”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c9280f3-74a5-4573-a58b-972036d0ba44') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
