INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21240, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "咖啡豆是咖啡树结的种子，可以做成咖啡。", "primary_collocate": null, "pronunciation": "kā fēi dòu", "ipa": "kʰa˥ fei˥ tou˥˩", "syllable_count": 3, "sentences": [{"text": "这家店的咖啡豆是从巴西来的。", "target_word": "咖啡豆", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我每天早上先磨咖啡豆，再煮咖啡。", "target_word": "咖啡豆", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他买了一袋新的咖啡豆。", "target_word": "咖啡豆", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "咖啡豆太老了，煮出来的咖啡不香。", "target_word": "咖啡豆", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种咖啡豆又香又不太苦，很多人喜欢。", "target_word": "咖啡豆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把咖啡豆放进磨豆机里，然后按一下开关。", "target_word": "咖啡豆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "咖啡豆要放在干燥的地方，不然会坏。", "target_word": "咖啡豆", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她在店里试过很多种咖啡豆。", "target_word": "咖啡豆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "咖啡豆一般要烤过以后才能磨成粉。", "target_word": "咖啡豆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农民把咖啡豆晒干后，卖给工厂。", "target_word": "咖啡豆", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一颗咖啡豆", "label": "量词"}, {"form": "一袋咖啡豆", "label": "量词"}, {"form": "一包咖啡豆", "label": "量词"}], "register": "中性", "sense_fingerprint": "咖啡树结的种子，烤过磨碎后用来煮咖啡", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc80c1b1-8ff1-4e63-afc6-b13565b16d8d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21240, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "价格", "is_correct": false, "explanation": "搭配：“从巴西来的”说的是实物的产地，“价格”不能从某地来。"}, {"text": "咖啡豆", "is_correct": true, "explanation": "正确：咖啡豆是咖啡树的种子，这家店的咖啡豆可以产自巴西，符合句意。"}, {"text": "时间", "is_correct": false, "explanation": "语义：时间是抽象概念，没有产地，不能说“从巴西来”。"}, {"text": "工资", "is_correct": false, "explanation": "搭配：工资不是能从外地运来的实物，不能说“从巴西来的”。"}], "explanations": {"价格": "搭配：“从巴西来的”说的是实物的产地，“价格”不能从某地来。", "咖啡豆": "正确：咖啡豆是咖啡树的种子，这家店的咖啡豆可以产自巴西，符合句意。", "时间": "语义：时间是抽象概念，没有产地，不能说“从巴西来”。", "工资": "搭配：工资不是能从外地运来的实物，不能说“从巴西来的”。"}, "sentence_index": 0, "correct_answer": "咖啡豆"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我在超市买了一只咖啡豆。", "explanation": "这里应该用〈颗〉。“只”一般用于动物或成对器物中的一个，咖啡豆是颗粒状，要用“颗”。"}, {"text": "我每天早上先切咖啡豆，再喝咖啡。", "explanation": "这里应该用〈磨〉。咖啡豆要先磨成粉再冲煮，“切”不是制作咖啡的步骤，不能用于咖啡豆。"}, {"text": "我一口气把咖啡豆喝了下去。", "explanation": "这里应该用〈吃〉。咖啡豆是固体的豆子，要吃下去；“喝”用于饮料，喝的是冲泡好的咖啡，不能直接喝豆子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17d3722b-bb89-4944-aabc-00c10b84bc2b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21240, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "冰块", "is_correct": false, "explanation": "搭配：冰块要保存在低温处，“放在干燥的地方”与冰块的保存要求不搭配。"}, {"text": "咖啡豆", "is_correct": true, "explanation": "正确：咖啡豆是要干燥保存的食材，放在干燥处才不容易变质，符合句意。"}, {"text": "节日", "is_correct": false, "explanation": "语义：节日是时间概念，不能被放在某个地方保存。"}, {"text": "心情", "is_correct": false, "explanation": "语义：心情是抽象的感受，不能放进地方里，也谈不上“坏”。"}], "explanations": {"冰块": "搭配：冰块要保存在低温处，“放在干燥的地方”与冰块的保存要求不搭配。", "咖啡豆": "正确：咖啡豆是要干燥保存的食材，放在干燥处才不容易变质，符合句意。", "节日": "语义：节日是时间概念，不能被放在某个地方保存。", "心情": "语义：心情是抽象的感受，不能放进地方里，也谈不上“坏”。"}, "sentence_index": 6, "correct_answer": "咖啡豆"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "农民把一张咖啡豆晒干后，卖给工厂。", "explanation": "这里应该用〈袋〉。“张”用于纸张、桌子等平面的东西，咖啡豆成批计量要用“袋”。"}, {"text": "农民把一座咖啡豆晒干后，卖给工厂。", "explanation": "这里应该用〈袋〉。“座”用于山、桥、建筑等大型固定的东西，咖啡豆不能用“座”。"}, {"text": "农民把一条咖啡豆晒干后，卖给工厂。", "explanation": "这里应该用〈袋〉。“条”用于细长的东西，咖啡豆成批计量要用“袋”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17d3722b-bb89-4944-aabc-00c10b84bc2b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21240, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他买了一个咖啡豆。", "corrected_sentence": "他买了一包咖啡豆。", "error_description": "错误形式：“一个咖啡豆”；正确形式：“一包咖啡豆”。咖啡豆按包装计量，应用量词“包”，不能用通用量词“个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17d3722b-bb89-4944-aabc-00c10b84bc2b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21240, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们以前从没试过一块咖啡豆。", "corrected_sentence": "我们以前从没试过一种咖啡豆。", "error_description": "错误形式：“一块咖啡豆”；正确形式：“一种咖啡豆”。“块”用于块状或片状的东西，咖啡豆按品种计量，应用“种”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17d3722b-bb89-4944-aabc-00c10b84bc2b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
