INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21246, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用手把东西从上面拿下来。", "primary_collocate": null, "pronunciation": "zhāi xià lai", "ipa": "ʈʂai̯˥ ɕja˥˩ lai̯", "syllable_count": 3, "sentences": [{"text": "墙上的旧画太脏了，我想把它摘下来。", "target_word": "摘下来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "门上的牌子歪了，请你把它摘下来。", "target_word": "摘下来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过年后，爸爸把门口的灯笼摘下来了。", "target_word": "摘下来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "风筝挂在树上了，他用竹竿把它摘下来。", "target_word": "摘下来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天花板上的气球，弟弟踩着椅子摘下来了。", "target_word": "摘下来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "墙上的镜子松了，爷爷站在凳子上把它摘下来。", "target_word": "摘下来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "圣诞节过后，我们把树上的彩灯摘下来。", "target_word": "摘下来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新年到了，爸爸把墙上的旧日历摘下来。", "target_word": "摘下来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "高处的相框落满了灰，你踩着凳子摘下来擦一擦。", "target_word": "摘下来", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "帽子挂在高高的钩子上，请帮我摘下来。", "target_word": "摘下来", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "摘下来了", "label": "体标"}, {"form": "摘不下来", "label": "可能补语"}], "register": "中性", "sense_fingerprint": "摘下来：用手把挂着的东西从上面取下", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e5e0e04-19d0-4826-8ae8-48040290f7a9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21246, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "摘下来", "is_correct": true, "explanation": "正确。摘下来读 zhāi xià lai（“来”轻声），指用手把东西从上面拿下来。"}, {"text": "拆下来", "is_correct": false, "explanation": "chāi（拆）与 zhāi（摘）声母不同（ch 与 zh），意思是把连着的东西拆下来。"}, {"text": "筛下来", "is_correct": false, "explanation": "shāi（筛）与 zhāi（摘）声母不同（sh 与 zh），意思是筛出来。"}, {"text": "栽下来", "is_correct": false, "explanation": "zāi（栽）与 zhāi（摘）声母不同（z 与 zh），意思是栽倒、摔下来。"}], "explanations": {"摘下来": "正确。摘下来读 zhāi xià lai（“来”轻声），指用手把东西从上面拿下来。", "拆下来": "chāi（拆）与 zhāi（摘）声母不同（ch 与 zh），意思是把连着的东西拆下来。", "筛下来": "shāi（筛）与 zhāi（摘）声母不同（sh 与 zh），意思是筛出来。", "栽下来": "zāi（栽）与 zhāi（摘）声母不同（z 与 zh），意思是栽倒、摔下来。"}, "sentence_index": null, "correct_answer": "摘下来"}, "level_3": {"options": [{"text": "摘下来", "is_correct": true, "explanation": "正确。“我想把它摘下来”说的是把挂在墙上的旧画取下，与语境相符。"}, {"text": "吃掉", "is_correct": false, "explanation": "搭配：“吃掉”只用于食物，不能用于墙上的画。"}, {"text": "拉长", "is_correct": false, "explanation": "语义：“拉长”指使变长，与“太脏了想取下”的语境不符。"}, {"text": "吹跑", "is_correct": false, "explanation": "语义：“吹跑”指被风刮走，不是把挂着的画取下。"}], "explanations": {"摘下来": "正确。“我想把它摘下来”说的是把挂在墙上的旧画取下，与语境相符。", "吃掉": "搭配：“吃掉”只用于食物，不能用于墙上的画。", "拉长": "语义：“拉长”指使变长，与“太脏了想取下”的语境不符。", "吹跑": "语义：“吹跑”指被风刮走，不是把挂着的画取下。"}, "sentence_index": 0, "correct_answer": "摘下来"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈把汤从锅里摘下来。", "explanation": "这里应该用〈盛出来〉。摘用于取下挂着或附着的东西，汤要盛出来。"}, {"text": "司机把车上的货摘下来了。", "explanation": "这里应该用〈卸下来〉。摘用于取下挂着的东西，把货物从车上搬下要说卸下来。"}, {"text": "他把掉在地上的苹果摘下来，放进篮子里。", "explanation": "这里应该用〈捡起来〉。摘用于从枝头或挂着的东西上取下，掉在地上的苹果要捡起来。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a6ce99f-2bd7-452c-a342-bb9bcb78d1ce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21246, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "摘下来", "is_correct": true, "explanation": "正确。“请帮我摘下来”的语境是圣诞节后收起挂在树上的彩灯，与摘下来相符。"}, {"text": "浇水", "is_correct": false, "explanation": "语义：彩灯不需要浇水，与圣诞节后收起彩灯的语境矛盾。"}, {"text": "戴上", "is_correct": false, "explanation": "搭配：“戴”多用于帽子、眼镜等，不说戴彩灯。"}, {"text": "咬断", "is_correct": false, "explanation": "语义：“咬断”指用牙齿弄断，与取下彩灯的动作不符。"}], "explanations": {"摘下来": "正确。“请帮我摘下来”的语境是圣诞节后收起挂在树上的彩灯，与摘下来相符。", "浇水": "语义：彩灯不需要浇水，与圣诞节后收起彩灯的语境矛盾。", "戴上": "搭配：“戴”多用于帽子、眼镜等，不说戴彩灯。", "咬断": "语义：“咬断”指用牙齿弄断，与取下彩灯的动作不符。"}, "sentence_index": 6, "correct_answer": "摘下来"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈把一大块面包摘下来，切成片。", "explanation": "这里应该用〈切下来〉。摘用于从挂着的东西上取下，把面包切开要说切下来。"}, {"text": "她从杂志上摘下来一张照片，贴在墙上。", "explanation": "这里应该用〈剪下来〉。摘用于取下挂着的东西，从杂志上剪下照片要说剪下来。"}, {"text": "他用手把窗户摘下来，搬到了车上。", "explanation": "这里应该用〈拆下来〉。窗户是装在墙上的整体，要拆下来；摘用于取下挂着的东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a6ce99f-2bd7-452c-a342-bb9bcb78d1ce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21246, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把墙上的铃铛了摘下来了。", "corrected_sentence": "他把墙上的铃铛摘下来了。", "error_description": "错误：“了”插在“把”字宾语与动词“摘”之间，动词前不能用“了”；应删去，正确为“摘下来了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a6ce99f-2bd7-452c-a342-bb9bcb78d1ce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21246, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "窗口的风铃挂得太高，妹妹踩着凳子它摘下来。", "corrected_sentence": "窗口的风铃挂得太高，妹妹踩着凳子把它摘下来。", "error_description": "错误：“它”是被摘的东西，应作宾语，放在“摘”前面（如“把它摘下来”）；直接说“它摘下来”，“它”会被当成施事，不通。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a6ce99f-2bd7-452c-a342-bb9bcb78d1ce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21248, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "出口", "is_correct": true, "explanation": "出口与进口相对，指把本国商品卖到国外，是词典收录的反义词。"}, {"text": "跳", "is_correct": false, "explanation": "跳与“进口”没有反义关系，不能构成一对反义词。"}, {"text": "读", "is_correct": false, "explanation": "读与“进口”没有反义关系，不能构成一对反义词。"}, {"text": "跑", "is_correct": false, "explanation": "跑与“进口”没有反义关系，不能构成一对反义词。"}], "correct_answer": "出口", "explanations": {"出口": "出口与进口相对，指把本国商品卖到国外，是词典收录的反义词。", "跳": "跳与“进口”没有反义关系，不能构成一对反义词。", "读": "读与“进口”没有反义关系，不能构成一对反义词。", "跑": "跑与“进口”没有反义关系，不能构成一对反义词。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7465aff9-30bb-41b6-b4c7-ea4ded5614a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
