INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21248, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "从别的国家买东西进来。", "primary_collocate": null, "pronunciation": "jìn kǒu", "ipa": "tɕin˥˩ kʰoʊ̯˨˩˦", "syllable_count": 2, "sentences": [{"text": "这个国家进口很多水果。", "target_word": "进口", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们的牛奶是从外国进口的。", "target_word": "进口", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的公司专门进口红酒。", "target_word": "进口", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中国每年进口很多石油。", "target_word": "进口", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "因为太贵，他们不进口这种车了。", "target_word": "进口", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店的咖啡豆都是进口的。", "target_word": "进口", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "日本从国外进口大米。", "target_word": "进口", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天本地不产菜，只能进口。", "target_word": "进口", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们从法国进口了一批葡萄酒。", "target_word": "进口", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些玩具是进口的，价钱很高。", "target_word": "进口", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "进口了", "label": "完成体"}, {"form": "进口过", "label": "经历体"}], "register": "中性", "sense_fingerprint": "进口：从外国买入商品", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '20eaa319-c57d-469c-b2b7-b9adb94399fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21248, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "进口", "is_correct": true, "explanation": "进口（jìn kǒu）：从国外买入商品，本句的正确答案。"}, {"text": "紧扣", "is_correct": false, "explanation": "紧扣（jǐn kòu）与进口（jìn kǒu）两个音节的声调都不同，意思是紧紧扣住。"}, {"text": "亲口", "is_correct": false, "explanation": "亲口（qīn kǒu）与进口（jìn kǒu）声母不同（q 与 j），意思是亲自开口。"}, {"text": "心口", "is_correct": false, "explanation": "心口（xīn kǒu）与进口（jìn kǒu）声母不同（x 与 j），意思是胸口。"}, {"text": "信口", "is_correct": false, "explanation": "信口（xìn kǒu）与进口（jìn kǒu）声母不同（x 与 j），意思是随口说。"}], "explanations": {"进口": "进口（jìn kǒu）：从国外买入商品，本句的正确答案。", "紧扣": "紧扣（jǐn kòu）与进口（jìn kǒu）两个音节的声调都不同，意思是紧紧扣住。", "亲口": "亲口（qīn kǒu）与进口（jìn kǒu）声母不同（q 与 j），意思是亲自开口。", "心口": "心口（xīn kǒu）与进口（jìn kǒu）声母不同（x 与 j），意思是胸口。", "信口": "信口（xìn kǒu）与进口（jìn kǒu）声母不同（x 与 j），意思是随口说。"}, "sentence_index": null, "correct_answer": "进口"}, "level_3": {"options": [{"text": "进口", "is_correct": true, "explanation": "进口：从国外买入商品，与“这个国家”和“水果”搭配，句意通顺。"}, {"text": "喝", "is_correct": false, "explanation": "语义：“喝”的对象是饮料，不能说“喝水果”，句子不通。"}, {"text": "鼓励", "is_correct": false, "explanation": "搭配：“鼓励”的宾语应是人，不能说“鼓励水果”。"}, {"text": "讨论", "is_correct": false, "explanation": "搭配：“讨论”的宾语应是问题或话题，不能说“讨论水果”。"}], "explanations": {"进口": "进口：从国外买入商品，与“这个国家”和“水果”搭配，句意通顺。", "喝": "语义：“喝”的对象是饮料，不能说“喝水果”，句子不通。", "鼓励": "搭配：“鼓励”的宾语应是人，不能说“鼓励水果”。", "讨论": "搭配：“讨论”的宾语应是问题或话题，不能说“讨论水果”。"}, "sentence_index": 0, "correct_answer": "进口"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每个周末都去批发市场进口蔬菜。", "explanation": "这里应该用〈进货〉。进口指从国外买入商品，从国内批发市场买要说进货。"}, {"text": "商店每个月从本市的仓库进口一批新鲜水果。", "explanation": "这里应该用〈购进〉。进口指从国外买入货物，从本市仓库买入要说购进。"}, {"text": "学校每学期都去书店进口教材。", "explanation": "这里应该用〈采购〉。进口的货物来自国外，去国内书店买教材要说采购。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7465aff9-30bb-41b6-b4c7-ea4ded5614a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21248, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "进口", "is_correct": true, "explanation": "进口：从国外买入商品，与“从国外”搭配，句意通顺。"}, {"text": "赚", "is_correct": false, "explanation": "搭配：“赚”的宾语应是钱或利润，不能说“赚大米”。"}, {"text": "种植", "is_correct": false, "explanation": "语义：“种植”指在土地里栽培，与“从国外”矛盾，句子不通。"}, {"text": "洗", "is_correct": false, "explanation": "语义：“洗”是清洗的动作，与“从国外”矛盾，句意不通。"}], "explanations": {"进口": "进口：从国外买入商品，与“从国外”搭配，句意通顺。", "赚": "搭配：“赚”的宾语应是钱或利润，不能说“赚大米”。", "种植": "语义：“种植”指在土地里栽培，与“从国外”矛盾，句子不通。", "洗": "语义：“洗”是清洗的动作，与“从国外”矛盾，句意不通。"}, "sentence_index": 6, "correct_answer": "进口"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们公司把大量茶叶进口到国外。", "explanation": "这里应该用〈出口〉。进口指从国外买入，把国内茶叶卖到国外要说出口。"}, {"text": "电脑需要先进口数据才能运行。", "explanation": "这里应该用〈输入〉。进口只用于从国外买进的货物，把数据送进电脑要说输入。"}, {"text": "学生们进口教室，开始上课。", "explanation": "这里应该用〈进入〉。进口只表示从国外买入货物，不能表示走进房间。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7465aff9-30bb-41b6-b4c7-ea4ded5614a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21248, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家工厂从德国进口了很多只机器。", "corrected_sentence": "这家工厂从德国进口了很多台机器。", "error_description": "量词错误：机器要用“台”计量，“只”用于动物或成对的东西，应说“很多台机器”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7465aff9-30bb-41b6-b4c7-ea4ded5614a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21248, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们去年从意大利进口了过一批橄榄油。", "corrected_sentence": "我们去年从意大利进口过一批橄榄油。", "error_description": "错误：“进口”后面不能同时用“了”和“过”。正确的是“进口过”，表示经历过，应去掉“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7465aff9-30bb-41b6-b4c7-ea4ded5614a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
