INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21250, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "果子可以吃了，或者人长大了。", "primary_collocate": null, "pronunciation": "chéng shú", "ipa": "ʈʂʰɤŋ˧˥ ʂu˧˥", "syllable_count": 2, "sentences": [{"text": "树上的桃子成熟了，我们去摘吧。", "target_word": "成熟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "葡萄成熟以后，味道又甜又好。", "target_word": "成熟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哥哥比以前成熟多了。", "target_word": "成熟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些西红柿还不成熟，是绿色的。", "target_word": "成熟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她看起来很成熟，不像十八岁。", "target_word": "成熟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "成熟的水果放不了太久。", "target_word": "成熟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经过这件事，他变得更成熟了。", "target_word": "成熟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "柿子成熟后，农民们一起去收。", "target_word": "成熟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "十岁的孩子能这样想，真成熟。", "target_word": "成熟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "稻谷成熟了，田里一片金黄。", "target_word": "成熟", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "成熟了", "label": "体标"}, {"form": "不成熟", "label": "否定"}, {"form": "更成熟", "label": "比较"}, {"form": "成熟期", "label": "复合"}], "register": "中性", "sense_fingerprint": "水果可以吃了；人长大懂事了", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e5e0e04-19d0-4826-8ae8-48040290f7a9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21250, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "成熟", "is_correct": true, "explanation": "正确。成熟读 chéng shú，指果子可以吃了或人长大了。"}, {"text": "诚实", "is_correct": false, "explanation": "shí（实）与 shú（熟）韵母不同（i 与 u），意思是诚实。"}, {"text": "乘数", "is_correct": false, "explanation": "shù（数）与 shú（熟）声调不同（第四声与第二声），意思是乘数。"}, {"text": "成书", "is_correct": false, "explanation": "shū（书）与 shú（熟）声调不同（第一声与第二声），意思是写成的书。"}], "explanations": {"成熟": "正确。成熟读 chéng shú，指果子可以吃了或人长大了。", "诚实": "shí（实）与 shú（熟）韵母不同（i 与 u），意思是诚实。", "乘数": "shù（数）与 shú（熟）声调不同（第四声与第二声），意思是乘数。", "成书": "shū（书）与 shú（熟）声调不同（第一声与第二声），意思是写成的书。"}, "sentence_index": null, "correct_answer": "成熟"}, "level_3": {"options": [{"text": "成熟", "is_correct": true, "explanation": "正确。成熟说果子可以吃了，与“我们去摘吧”的语境相符。"}, {"text": "幼稚", "is_correct": false, "explanation": "搭配：“幼稚”形容人的想法，不能用来说桃子。"}, {"text": "辛辣", "is_correct": false, "explanation": "搭配：“辛辣”形容味道，不能用来形容桃子。"}, {"text": "发霉", "is_correct": false, "explanation": "语义：“发霉”指长出霉菌，与“我们去摘吧”的采收语境相悖。"}], "explanations": {"成熟": "正确。成熟说果子可以吃了，与“我们去摘吧”的语境相符。", "幼稚": "搭配：“幼稚”形容人的想法，不能用来说桃子。", "辛辣": "搭配：“辛辣”形容味道，不能用来形容桃子。", "发霉": "语义：“发霉”指长出霉菌，与“我们去摘吧”的采收语境相悖。"}, "sentence_index": 0, "correct_answer": "成熟"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这块石头已经成熟了，可以拿去盖房子。", "explanation": "这里应该用〈加工〉。成熟只用于果实和人，石头要经过加工才能盖房子。"}, {"text": "鸡蛋已经成熟了，可以剥壳吃了。", "explanation": "这里应该用〈煮熟〉。成熟用于果实和人的心智，鸡蛋煮好了要说煮熟。"}, {"text": "我对这条路很成熟，闭着眼睛也能走。", "explanation": "这里应该用〈熟悉〉。成熟不指对地方的了解，对路熟悉要说熟悉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a6ce99f-2bd7-452c-a342-bb9bcb78d1ce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21250, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "成熟", "is_correct": true, "explanation": "正确。成熟读 chéng shú，指果子可以吃了或人长大了。"}, {"text": "乘势", "is_correct": false, "explanation": "shì（势）与 shú（熟）韵母和声调都不同，意思是趁着形势。"}, {"text": "成束", "is_correct": false, "explanation": "shù（束）与 shú（熟）声调不同，意思是捆成一束。"}, {"text": "程式", "is_correct": false, "explanation": "shì（式）与 shú（熟）韵母和声调都不同，意思是程序或格式。"}], "explanations": {"成熟": "正确。成熟读 chéng shú，指果子可以吃了或人长大了。", "乘势": "shì（势）与 shú（熟）韵母和声调都不同，意思是趁着形势。", "成束": "shù（束）与 shú（熟）声调不同，意思是捆成一束。", "程式": "shì（式）与 shú（熟）韵母和声调都不同，意思是程序或格式。"}, "sentence_index": null, "correct_answer": "成熟"}, "level_3": {"options": [{"text": "成熟", "is_correct": true, "explanation": "正确。“变得更成熟了”说他经过事情后懂事了，与语境相符。"}, {"text": "透明", "is_correct": false, "explanation": "语义：“透明”指物体能透光，不用来形容人的心理变化。"}, {"text": "矮小", "is_correct": false, "explanation": "体貌：“矮小”描写身材，与“经过这件事”的心理变化不符。"}, {"text": "碧绿", "is_correct": false, "explanation": "搭配：“碧绿”形容颜色，不能用来形容人的变化。"}], "explanations": {"成熟": "正确。“变得更成熟了”说他经过事情后懂事了，与语境相符。", "透明": "语义：“透明”指物体能透光，不用来形容人的心理变化。", "矮小": "体貌：“矮小”描写身材，与“经过这件事”的心理变化不符。", "碧绿": "搭配：“碧绿”形容颜色，不能用来形容人的变化。"}, "sentence_index": 6, "correct_answer": "成熟"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次手术终于成熟了。", "explanation": "这里应该用〈成功〉。成熟说果实或人达到完善，手术取得预期结果要说成功。"}, {"text": "这棵小树苗才种下几天，已经成熟了。", "explanation": "这里应该用〈成长〉。成熟指已达到完善或可收获的阶段，小树苗还在生长要说成长。"}, {"text": "这份报告已经成熟了，明天交给老板。", "explanation": "这里应该用〈完成〉。成熟不用于报告的结束，报告写好了要说完成。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a6ce99f-2bd7-452c-a342-bb9bcb78d1ce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21250, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她比以前最成熟。", "corrected_sentence": "她比以前更成熟。", "error_description": "与“比”连用表示程度要用“更”，“最”表示最高程度，不能与“比”同用，应说“比以前更成熟”，不能说“比以前最成熟”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a6ce99f-2bd7-452c-a342-bb9bcb78d1ce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21250, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个年轻人很更成熟的样子让人敬佩。", "corrected_sentence": "这个年轻人很成熟的样子让人敬佩。", "error_description": "错误：“很”与“更”不能同用，只能用其一；正确：“很成熟的样子”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a6ce99f-2bd7-452c-a342-bb9bcb78d1ce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
