INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21252, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "用来强调，意思是''正是''。", "primary_collocate": null, "pronunciation": "jiù shì", "ipa": "tɕjoʊ˥˩ ʂɻ̩˥˩", "syllable_count": 2, "sentences": [{"text": "他就是我们的新老师。", "target_word": "就是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这就是我要找的那本书。", "target_word": "就是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位穿红衣服的就是我姐姐。", "target_word": "就是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我最喜欢的颜色就是蓝色。", "target_word": "就是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你看，前面那个小村子就是我的家乡。", "target_word": "就是", "complexity_tier": "T3", "furigana": "jiù shì", "sentence_source": "generated"}, {"text": "这里就是我们学校的大门。", "target_word": "就是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他最大的问题就是不爱睡觉。", "target_word": "就是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "王明就是昨天打电话的那个人。", "target_word": "就是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我最想去的地方就是北京。", "target_word": "就是", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天来的客人就是他的老同学。", "target_word": "就是", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "就是说", "label": "复合"}], "register": "口语", "sense_fingerprint": "强调判断，表示“正是、恰恰是”", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be5ee50c-f9af-43f9-b71d-60fc13a41298') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21252, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "就是", "is_correct": true, "explanation": "“就是”表示强调判断，“他就是我们的新老师”指明身份，与句意相合。"}, {"text": "常", "is_correct": false, "explanation": "语义：“常”表示经常、反复，不能用来说明某人的身份。"}, {"text": "正在", "is_correct": false, "explanation": "语法：“正在”后面要接动词，不能直接接“我们的新老师”。"}, {"text": "曾", "is_correct": false, "explanation": "语义：“曾”指过去，与“新老师”所指的现在状态矛盾。"}], "explanations": {"就是": "“就是”表示强调判断，“他就是我们的新老师”指明身份，与句意相合。", "常": "语义：“常”表示经常、反复，不能用来说明某人的身份。", "正在": "语法：“正在”后面要接动词，不能直接接“我们的新老师”。", "曾": "语义：“曾”指过去，与“新老师”所指的现在状态矛盾。"}, "sentence_index": 0, "correct_answer": "就是"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他这人就是实在。", "explanation": "这里“就是”表示“很、实在”，强调程度，与强调判断的“正是”不同，是另一种用法。"}, {"text": "我昨天就是没去学校。", "explanation": "这里“就是”表示“只是”，与强调判断的“正是”不同，是另一种用法。"}, {"text": "他越劝，我就是不听。", "explanation": "这里“就是”表示“偏偏”，与强调判断的“正是”不同，是另一种用法。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26accaa6-266c-48d1-a7a2-07e94e88f0e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21252, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "偶尔", "is_correct": false, "explanation": "语义：“偶尔”表示不经常，与“最大的问题”的持续性相矛盾。"}, {"text": "就是", "is_correct": true, "explanation": "“就是”强调“最大的问题”正是“不爱睡觉”，与句意相合。"}, {"text": "很是", "is_correct": false, "explanation": "语域：“很是”偏书面、文言，与本句的口语语境不合。"}, {"text": "有时", "is_correct": false, "explanation": "语义：“有时”表示时而如此，与“最大的问题”的固定性不合。"}], "explanations": {"偶尔": "语义：“偶尔”表示不经常，与“最大的问题”的持续性相矛盾。", "就是": "“就是”强调“最大的问题”正是“不爱睡觉”，与句意相合。", "很是": "语域：“很是”偏书面、文言，与本句的口语语境不合。", "有时": "语义：“有时”表示时而如此，与“最大的问题”的固定性不合。"}, "sentence_index": 6, "correct_answer": "就是"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他没来，就是没告诉我。", "explanation": "这里“就是”表示“只是、仅仅”，与强调判断的“正是”不同，是另一种用法。"}, {"text": "这件衣服很好看，就是有点贵。", "explanation": "这里“就是”表示转折，意思是“不过”，与强调判断的“正是”不同，是另一种用法。"}, {"text": "下雨了，我就是要出门。", "explanation": "这里“就是”表示“偏要”，与强调判断的“正是”不同，是另一种用法。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26accaa6-266c-48d1-a7a2-07e94e88f0e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21252, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这件事就是他做得。", "corrected_sentence": "这件事就是他做的。", "error_description": "助词错误：“就是……的”强调句要用“的”，“得”是补语标记，后面必须接补语，“做得”后面没有补语，应说“做的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26accaa6-266c-48d1-a7a2-07e94e88f0e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21252, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们班最聪明的学生就是的小红。", "corrected_sentence": "我们班最聪明的学生就是小红。", "error_description": "多加字错误：“就是”后面直接接名词，不能多加“的”，“的”在这里是多余的。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26accaa6-266c-48d1-a7a2-07e94e88f0e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21254, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "买", "is_correct": true, "explanation": "买：指用钱换东西，与“卖”相反，是反义词。"}, {"text": "送", "is_correct": false, "explanation": "送：指无偿给予，与“卖”不构成反义关系。"}, {"text": "借", "is_correct": false, "explanation": "借：指暂时使用别人的东西，与“卖”没有反义关系。"}, {"text": "修", "is_correct": false, "explanation": "修：指修理，与“卖”没有反义关系。"}], "correct_answer": "买", "explanations": {"买": "买：指用钱换东西，与“卖”相反，是反义词。", "送": "送：指无偿给予，与“卖”不构成反义关系。", "借": "借：指暂时使用别人的东西，与“卖”没有反义关系。", "修": "修：指修理，与“卖”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '776b36fe-5714-4c91-a872-cd46e51e87e7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21254, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "买", "is_correct": true, "explanation": "买：指用钱换东西，与“卖”相反，是反义词。"}, {"text": "租", "is_correct": false, "explanation": "租：指付钱暂时使用，与“卖”不构成反义关系。"}, {"text": "赠", "is_correct": false, "explanation": "赠：指无偿送人，与“卖”不构成反义关系。"}, {"text": "拆", "is_correct": false, "explanation": "拆：指拆开、拆卸，与“卖”没有反义关系。"}], "correct_answer": "买", "explanations": {"买": "买：指用钱换东西，与“卖”相反，是反义词。", "租": "租：指付钱暂时使用，与“卖”不构成反义关系。", "赠": "赠：指无偿送人，与“卖”不构成反义关系。", "拆": "拆：指拆开、拆卸，与“卖”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '776b36fe-5714-4c91-a872-cd46e51e87e7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21254, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用手里的东西换钱。", "primary_collocate": null, "pronunciation": "mài", "ipa": "mai˥˩", "syllable_count": 1, "sentences": [{"text": "他在市场卖水果。", "target_word": "卖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想卖这辆旧车。", "target_word": "卖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把旧书都卖了。", "target_word": "卖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店卖很多种茶。", "target_word": "卖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他以前卖过报纸。", "target_word": "卖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶在门口卖菜。", "target_word": "卖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我卖了旧手机，买了新的。", "target_word": "卖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们家卖鱼，不卖肉。", "target_word": "卖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不想卖房子。", "target_word": "卖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟在路边卖着自己做的小玩具。", "target_word": "卖", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "卖了", "label": "体标"}, {"form": "卖过", "label": "体标"}, {"form": "卖着", "label": "体标"}, {"form": "卖家", "label": "复合"}, {"form": "买卖", "label": "复合"}], "register": "口语", "sense_fingerprint": "把东西给别人，从别人那里得到钱", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3b355173-4ded-4ba2-b8ef-c4046b577508') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21254, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "卖", "is_correct": true, "explanation": "卖 mài：正确答案，指用东西换钱。"}, {"text": "买", "is_correct": false, "explanation": "mǎi（第三声）与 mài（第四声）声调不同，意思是买。"}, {"text": "骂", "is_correct": false, "explanation": "mà 与 mài 韵母不同（ai 与 a），意思是骂。"}, {"text": "慢", "is_correct": false, "explanation": "màn 与 mài 韵母不同（ai 与 an），意思是慢。"}, {"text": "埋", "is_correct": false, "explanation": "mái（第二声）与 mài（第四声）声调不同，意思是埋藏。"}, {"text": "败", "is_correct": false, "explanation": "bài 与 mài 声母不同（b 与 m），意思是失败。"}], "explanations": {"卖": "卖 mài：正确答案，指用东西换钱。", "买": "mǎi（第三声）与 mài（第四声）声调不同，意思是买。", "骂": "mà 与 mài 韵母不同（ai 与 a），意思是骂。", "慢": "màn 与 mài 韵母不同（ai 与 an），意思是慢。", "埋": "mái（第二声）与 mài（第四声）声调不同，意思是埋藏。", "败": "bài 与 mài 声母不同（b 与 m），意思是失败。"}, "sentence_index": null, "correct_answer": "卖"}, "level_3": {"options": [{"text": "卖", "is_correct": true, "explanation": "卖：把水果给别人并收取钱款，符合句意。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”的对象是歌曲等，不能带“水果”作宾语。"}, {"text": "修", "is_correct": false, "explanation": "语义：“修”指修理，水果不能修理，句意不通。"}, {"text": "拆", "is_correct": false, "explanation": "语义：“拆”指拆开、拆卸，“拆水果”句意不通。"}], "explanations": {"卖": "卖：把水果给别人并收取钱款，符合句意。", "唱": "搭配：“唱”的对象是歌曲等，不能带“水果”作宾语。", "修": "语义：“修”指修理，水果不能修理，句意不通。", "拆": "语义：“拆”指拆开、拆卸，“拆水果”句意不通。"}, "sentence_index": 0, "correct_answer": "卖"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家店免费卖茶。", "explanation": "这里应该用〈送〉。“卖”指用东西换钱，与“免费”矛盾，免费给人应说“送”。"}, {"text": "他卖了我五块钱的费用。", "explanation": "这里应该用〈收〉。卖的对象是商品，收取费用要用“收”，不能说卖费用。"}, {"text": "他卖了一个问题给老师。", "explanation": "这里应该用〈问〉。问题不是商品，不能用“卖”；向老师提问应说“问”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '776b36fe-5714-4c91-a872-cd46e51e87e7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21254, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "卖", "is_correct": true, "explanation": "卖 mài：正确答案，指用东西换钱。"}, {"text": "妹", "is_correct": false, "explanation": "mèi 与 mài 韵母不同（ai 与 ei），意思是妹妹。"}, {"text": "耐", "is_correct": false, "explanation": "nài 与 mài 声母不同（n 与 m），意思是忍耐。"}, {"text": "拜", "is_correct": false, "explanation": "bài 与 mài 声母不同（b 与 m），意思是拜访。"}, {"text": "带", "is_correct": false, "explanation": "dài 与 mài 声母不同（d 与 m），意思是携带。"}], "explanations": {"卖": "卖 mài：正确答案，指用东西换钱。", "妹": "mèi 与 mài 韵母不同（ai 与 ei），意思是妹妹。", "耐": "nài 与 mài 声母不同（n 与 m），意思是忍耐。", "拜": "bài 与 mài 声母不同（b 与 m），意思是拜访。", "带": "dài 与 mài 声母不同（d 与 m），意思是携带。"}, "sentence_index": null, "correct_answer": "卖"}, "level_3": {"options": [{"text": "卖", "is_correct": true, "explanation": "卖：把旧手机给别人并换钱，与后面“买了新的”构成对照，符合句意。"}, {"text": "弹", "is_correct": false, "explanation": "搭配：“弹”指弹奏或弹射，不能用于手机，搭配不当。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”指进食，手机不能吃，句意不通。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：“洗”与“旧手机”搭配不当，句意不通。"}], "explanations": {"卖": "卖：把旧手机给别人并换钱，与后面“买了新的”构成对照，符合句意。", "弹": "搭配：“弹”指弹奏或弹射，不能用于手机，搭配不当。", "吃": "语义：“吃”指进食，手机不能吃，句意不通。", "洗": "搭配：“洗”与“旧手机”搭配不当，句意不通。"}, "sentence_index": 6, "correct_answer": "卖"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我每个月都卖房租。", "explanation": "这里应该用〈付〉。“卖”的对象是东西，支付房租要用“付”。"}, {"text": "他卖了我一拳。", "explanation": "这里应该用〈打〉。“卖”指用东西换钱，“一拳”不是可以出售的东西，应说打。"}, {"text": "我卖到了一个老朋友。", "explanation": "这里应该用〈遇到〉。“卖到”不能用于人，遇见老朋友要用遇到。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '776b36fe-5714-4c91-a872-cd46e51e87e7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21254, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他每天早上在车站卖了报纸。", "corrected_sentence": "他每天早上在车站卖报纸。", "error_description": "体标用错：表示每天重复的习惯性动作时不能用“了”，应说“卖报纸”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '776b36fe-5714-4c91-a872-cd46e51e87e7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21254, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我卖了给朋友一辆旧车。", "corrected_sentence": "我卖给了朋友一辆旧车。", "error_description": "补语位置用错：“卖给”是动补结构，“了”应放在“给”之后，正确形式是“卖给了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '776b36fe-5714-4c91-a872-cd46e51e87e7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
