INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21256, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "很大的水流，像大河一样。", "primary_collocate": null, "pronunciation": "hóng liú", "ipa": "xʊŋ˧˥ lioʊ˧˥", "syllable_count": 2, "sentences": [{"text": "洪流从山上冲下来，声音很大。", "target_word": "洪流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大雨过后，河里出现了一股洪流。", "target_word": "洪流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桥下的洪流又急又猛。", "target_word": "洪流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "洪流冲走了河边的小树。", "target_word": "洪流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "洪流淹没了路边的田地。", "target_word": "洪流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他站在高处，看着洪流往下游流去。", "target_word": "洪流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春天雪化了，山里有洪流冲下来。", "target_word": "洪流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "洪流冲过了大坝，下游的人都很紧张。", "target_word": "洪流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们离洪流远一点，太危险了。", "target_word": "洪流", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "洪流像一条黄龙，一直向东流。", "target_word": "洪流", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一股洪流", "label": "量词"}], "register": "书面", "sense_fingerprint": "洪流·很大的水流，如大河", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '58d39713-e02e-4d8c-930e-db2b66dc5d9d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21256, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "洪流", "is_correct": true, "explanation": "正确：洪流指很大的水流，从山上冲下来且声音很大，符合语境。"}, {"text": "微风", "is_correct": false, "explanation": "语义：微风轻柔，不会从山上冲下来，更不会声音很大。"}, {"text": "棉絮", "is_correct": false, "explanation": "搭配：“冲下来”用于水流、石块，不用于棉絮。"}, {"text": "信件", "is_correct": false, "explanation": "语义：信件是纸质的书写物，不能从山上冲下来。"}], "explanations": {"洪流": "正确：洪流指很大的水流，从山上冲下来且声音很大，符合语境。", "微风": "语义：微风轻柔，不会从山上冲下来，更不会声音很大。", "棉絮": "搭配：“冲下来”用于水流、石块，不用于棉絮。", "信件": "语义：信件是纸质的书写物，不能从山上冲下来。"}, "sentence_index": 0, "correct_answer": "洪流"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这条洪流很清，可以直接喝。", "explanation": "这里应该用〈清泉〉。洪流湍急浑浊，不能说“很清，可以直接喝”；清澈可饮的水要说〈清泉〉。"}, {"text": "洪流平静地躺在河床上。", "explanation": "这里应该用〈湖水〉。洪流汹涌湍急，不会“平静地躺”；平静的水才用〈湖水〉来形容。"}, {"text": "洪流安静地流过了村子。", "explanation": "这里应该用〈溪流〉。洪流湍急汹涌，不能说“安静地流”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80b7578c-1d5b-477c-bd47-adf515e73689') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21256, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "洪流", "is_correct": true, "explanation": "正确：春天雪化后，山里的洪流冲下来，符合语境。"}, {"text": "白云", "is_correct": false, "explanation": "语义：白云飘在天上，不会从山里冲下来。"}, {"text": "粉笔", "is_correct": false, "explanation": "语义：粉笔是文具，不能从山里冲下来。"}, {"text": "纸张", "is_correct": false, "explanation": "搭配：“冲下来”不能用于纸张。"}], "explanations": {"洪流": "正确：春天雪化后，山里的洪流冲下来，符合语境。", "白云": "语义：白云飘在天上，不会从山里冲下来。", "粉笔": "语义：粉笔是文具，不能从山里冲下来。", "纸张": "搭配：“冲下来”不能用于纸张。"}, "sentence_index": 6, "correct_answer": "洪流"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "洪流轻轻地流进了村子。", "explanation": "这里应该用〈溪水〉。洪流湍急汹涌，不能说“轻轻地流进”。"}, {"text": "洪流从山上飘了下来。", "explanation": "这里应该用〈雾〉。洪流湍急有力，不能说“飘下来”；轻飘的东西才用“飘”，如〈雾〉。"}, {"text": "洪流叮咚地流着。", "explanation": "这里应该用〈清泉〉。“叮咚”形容清脆的水声，洪流的声音是轰鸣，不说“叮咚”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80b7578c-1d5b-477c-bd47-adf515e73689') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21256, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "一个洪流从山谷里冲了下来。", "corrected_sentence": "一股洪流从山谷里冲了下来。", "error_description": "量词错误：洪流应用量词“股”，不说“个”。正确应为“一股洪流从山谷里冲了下来”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80b7578c-1d5b-477c-bd47-adf515e73689') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21256, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "暴雨过后，洪流从山上冲下了来。", "corrected_sentence": "暴雨过后，洪流从山上冲了下来。", "error_description": "趋向补语错误：「冲下来」是复合趋向补语，「了」应放在「下来」之前，应说「冲了下来」，不说「冲下了来」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80b7578c-1d5b-477c-bd47-adf515e73689') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
