INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21260, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "工厂是制造东西的地方。", "primary_collocate": null, "pronunciation": "gōng chǎng", "ipa": "kʊŋ˥ ʈʂʰɑŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "他爸爸在一家工厂工作。", "target_word": "工厂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个工厂有两百个工人。", "target_word": "工厂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工厂离市中心很远。", "target_word": "工厂", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们昨天参观了一个汽车工厂。", "target_word": "工厂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家工厂每天做一万个杯子。", "target_word": "工厂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工厂里的机器声音很大。", "target_word": "工厂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她毕业后进了一家大工厂。", "target_word": "工厂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板在城外开了一个工厂。", "target_word": "工厂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个工厂的产品卖到国外。", "target_word": "工厂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工厂下个月要搬到新地方。", "target_word": "工厂", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "家", "label": "量词"}, {"form": "個", "label": "量词"}, {"form": "工廠", "label": "繁体"}, {"form": "汽车工厂", "label": "复合"}], "register": "中性", "sense_fingerprint": "制造产品的场所", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3365f9ac-881d-493f-88dc-1a13db791d52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21260, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "森林", "is_correct": false, "explanation": "语义：森林是自然景观，不是可以去上班的单位，“一家森林”说不通。"}, {"text": "工厂", "is_correct": true, "explanation": "工厂：制造东西的地方，可以在里面工作，量词用“家”。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不是工作的地方，“在一家石头工作”说不通。"}, {"text": "房子", "is_correct": false, "explanation": "搭配：“家”量的是公司、商店等单位，不能量“房子”。"}], "explanations": {"森林": "语义：森林是自然景观，不是可以去上班的单位，“一家森林”说不通。", "工厂": "工厂：制造东西的地方，可以在里面工作，量词用“家”。", "石头": "语义：石头不是工作的地方，“在一家石头工作”说不通。", "房子": "搭配：“家”量的是公司、商店等单位，不能量“房子”。"}, "sentence_index": 0, "correct_answer": "工厂"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个工厂种了三百亩小麦。", "explanation": "这里应该用〈农场〉。种小麦要在农场或农田里进行，工厂是制造东西的地方，不种庄稼。"}, {"text": "这家工厂每天有一千名病人。", "explanation": "这里应该用〈医院〉。病人要在医院里治疗，工厂是制造东西的地方，不会有病人就诊。"}, {"text": "矿工们每天在工厂里挖煤。", "explanation": "这里应该用〈矿山〉。挖煤要在矿山里进行，工厂是制造东西的地方，不能用来挖煤。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6b9e4da-c487-4ed1-b041-32c7a850e850') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21260, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "水果", "is_correct": false, "explanation": "搭配：“家”量的是商店、公司等单位，不能用来量“水果”。"}, {"text": "海洋", "is_correct": false, "explanation": "语义：海洋是自然景观，不是可以进去工作的单位。"}, {"text": "天空", "is_correct": false, "explanation": "语义：天空不是工作单位，“进了一家大天空”说不通。"}, {"text": "工厂", "is_correct": true, "explanation": "工厂：制造东西的地方，可以进去工作，量词用“家”。"}], "explanations": {"水果": "搭配：“家”量的是商店、公司等单位，不能用来量“水果”。", "海洋": "语义：海洋是自然景观，不是可以进去工作的单位。", "天空": "语义：天空不是工作单位，“进了一家大天空”说不通。", "工厂": "工厂：制造东西的地方，可以进去工作，量词用“家”。"}, "sentence_index": 6, "correct_answer": "工厂"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个工厂里有很多大象。", "explanation": "这里应该用〈动物园〉。大象要在动物园里饲养，工厂是制造东西的地方，不能用来饲养大象。"}, {"text": "这座工厂的讲台上，老师正在给学生讲唐诗。", "explanation": "这里应该用〈学校〉。讲台、老师讲课、学生听讲属于学校，工厂是制造东西的地方，一般不会有这样的课堂。"}, {"text": "这个工厂里有熔岩流动。", "explanation": "这里应该用〈火山〉。熔岩是火山喷发时流出的，工厂是制造东西的地方，不会有熔岩流动。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6b9e4da-c487-4ed1-b041-32c7a850e850') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21260, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只工厂的规模很大。", "corrected_sentence": "这座工厂的规模很大。", "error_description": "量词错误：“工厂”不用“只”计量（“只”多用于动物和成对物品中的一个），应改为“座”，说“这座工厂”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6b9e4da-c487-4ed1-b041-32c7a850e850') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21260, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些工厂们下个月都会开始招工。", "corrected_sentence": "这些工厂下个月都会开始招工。", "error_description": "词尾错误：“工厂”是无生命的地方，一般不加“们”表示复数，应说“这些工厂”。“们”多用于指人的名词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6b9e4da-c487-4ed1-b041-32c7a850e850') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
