INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21266, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "可以喝的东西，比如水、牛奶、果汁。", "primary_collocate": null, "pronunciation": "yǐn liào", "ipa": "in˨˩ ljɑʊ˥˩", "syllable_count": 2, "sentences": [{"text": "我喜欢喝冰的饮料。", "target_word": "饮料", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "桌子上有三杯饮料。", "target_word": "饮料", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这家店的饮料很便宜。", "target_word": "饮料", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "孩子们不能喝太多饮料。", "target_word": "饮料", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你想要什么饮料？", "target_word": "饮料", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我给朋友买了两瓶饮料。", "target_word": "饮料", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "夏天很热，大家都爱喝冰饮料。", "target_word": "饮料", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "菜单上有咖啡、果汁和别的饮料。", "target_word": "饮料", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把饮料放在桌子上，就去看电视了。", "target_word": "饮料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说，运动以后不要马上喝甜饮料。", "target_word": "饮料", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "瓶", "label": "量词"}, {"form": "杯", "label": "量词"}, {"form": "飲料", "label": "繁体"}], "register": "中性", "sense_fingerprint": "可以喝的液体，如水、牛奶、果汁（名词）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'acd4d851-86a9-4cfd-a310-ec607390ed11') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21266, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "饮料", "is_correct": true, "explanation": "正确。“饮料”是可以喝的液体，与“喝”和“冰的”相符。"}, {"text": "食物", "is_correct": false, "explanation": "搭配：“喝”的对象是液体，不能说“喝食物”。"}, {"text": "面包", "is_correct": false, "explanation": "语义：面包是固体食物，不能用“喝”。"}, {"text": "水果", "is_correct": false, "explanation": "搭配：“水果”一般用“吃”，不能说“喝冰的水果”。"}], "explanations": {"饮料": "正确。“饮料”是可以喝的液体，与“喝”和“冰的”相符。", "食物": "搭配：“喝”的对象是液体，不能说“喝食物”。", "面包": "语义：面包是固体食物，不能用“喝”。", "水果": "搭配：“水果”一般用“吃”，不能说“喝冰的水果”。"}, "sentence_index": 0, "correct_answer": "饮料"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "医生给他打了一针饮料。", "explanation": "这里应该用〈药水〉。饮料是喝的东西，不能注射进身体，“打针”要用药液。"}, {"text": "我用饮料点灯。", "explanation": "这里应该用〈煤油〉。饮料是用来喝的液体，不能当燃料点灯。"}, {"text": "我用饮料洗手。", "explanation": "这里应该用〈肥皂〉。饮料是用来喝的，不能用来洗手。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97137d70-c8c5-4684-b97d-32d1743ca14d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21266, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "饮料", "is_correct": true, "explanation": "正确。“饮料”可以喝，与“夏天很热”和“喝冰”相符。"}, {"text": "空调", "is_correct": false, "explanation": "语义：空调不能喝，与句中的“喝”矛盾。"}, {"text": "糖", "is_correct": false, "explanation": "语义：“冰糖”是固体，不能用“喝”。"}, {"text": "冰块", "is_correct": false, "explanation": "搭配：“冰块”一般用“吃”或“含”，不说“喝冰块”。"}], "explanations": {"饮料": "正确。“饮料”可以喝，与“夏天很热”和“喝冰”相符。", "空调": "语义：空调不能喝，与句中的“喝”矛盾。", "糖": "语义：“冰糖”是固体，不能用“喝”。", "冰块": "搭配：“冰块”一般用“吃”或“含”，不说“喝冰块”。"}, "sentence_index": 6, "correct_answer": "饮料"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "医生说，病人要输饮料。", "explanation": "这里应该用〈血〉。“输”用于血或液体药物，饮料不能输入血管。"}, {"text": "他在脸上抹了饮料。", "explanation": "这里应该用〈防晒霜〉。饮料是喝的东西，不能涂抹在脸上。"}, {"text": "工人用饮料建房子。", "explanation": "这里应该用〈水泥〉。建造房屋要用水泥等建筑材料，饮料不能用来建房。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97137d70-c8c5-4684-b97d-32d1743ca14d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21266, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈给我倒了一个饮料。", "corrected_sentence": "妈妈给我倒了一杯饮料。", "error_description": "错误形式：“一个饮料”，量词“个”不用于饮料。正确形式：“一杯饮料”，饮料常用“杯”“瓶”计量。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97137d70-c8c5-4684-b97d-32d1743ca14d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21266, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我在超市买了一块饮料。", "corrected_sentence": "我在超市买了一瓶饮料。", "error_description": "量词错误：“块”用于块状物，饮料是液体，应用“瓶”或“杯”计量。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97137d70-c8c5-4684-b97d-32d1743ca14d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
