INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21272, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "出口就是可以走出去的门或路。", "primary_collocate": null, "pronunciation": "chū kǒu", "ipa": "ʈʂʰu˥ kʰou˨˩˦", "syllable_count": 2, "sentences": [{"text": "电影结束了，大家从出口慢慢走出去。", "target_word": "出口", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "超市的出口在左边，入口在右边。", "target_word": "出口", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请问，地铁站的出口在哪儿？", "target_word": "出口", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "着火时，请从最近的出口离开。", "target_word": "出口", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个商店只有一个出口，人很多。", "target_word": "出口", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在体育馆的出口等你。", "target_word": "出口", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们走错了路，找不到公园的出口。", "target_word": "出口", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "进去的门叫入口，出去的门叫出口。", "target_word": "出口", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "出口前面站着很多人，我们走不出去。", "target_word": "出口", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地铁二号出口旁边有一家咖啡店。", "target_word": "出口", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}], "register": "中性", "sense_fingerprint": "出去的门或通道，与入口相对", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2b68117-69f0-4db3-8b42-afed4406c8c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21272, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "厨房", "is_correct": false, "explanation": "语义：“厨房”不是观众散场时走出的地方，与电影院的场景不符。"}, {"text": "出口", "is_correct": true, "explanation": "“出口”指可以走出去的门或通道，与“从……走出去”相合，填入正确。"}, {"text": "售票处", "is_correct": false, "explanation": "语义：“售票处”是买票的地方，电影结束后大家不会从那里走出去。"}, {"text": "柜台", "is_correct": false, "explanation": "搭配：“柜台”是营业的设备，不能作为人走出去的通道，与“从……走出去”不搭配。"}], "explanations": {"厨房": "语义：“厨房”不是观众散场时走出的地方，与电影院的场景不符。", "出口": "“出口”指可以走出去的门或通道，与“从……走出去”相合，填入正确。", "售票处": "语义：“售票处”是买票的地方，电影结束后大家不会从那里走出去。", "柜台": "搭配：“柜台”是营业的设备，不能作为人走出去的通道，与“从……走出去”不搭配。"}, "sentence_index": 0, "correct_answer": "出口"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这扇门是进去用的，所以标着出口。", "explanation": "这里应该用〈入口〉。“出口”指出去的门，进去的门要说入口。"}, {"text": "他把旧房子出口了，搬到了城外。", "explanation": "这里应该用〈出售〉。“出口”指把货物运到国外卖，卖房子不能用出口。"}, {"text": "这个房间有一只出口，很窄。", "explanation": "这里不能用〈只〉。“出口”是地方，量词应该用〈个〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e82f6a0-beb9-4f40-83b9-f068af0d5d6d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21272, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "天空", "is_correct": false, "explanation": "语义：“天空”不是可以去寻找的地方，“找不到公园的天空”不通。"}, {"text": "出口", "is_correct": true, "explanation": "“出口”指公园里可以走出去的门或通道，找不到的正是它，填入正确。"}, {"text": "音乐", "is_correct": false, "explanation": "语义：“音乐”是声音艺术，不能作为园内的地点被找不到，句意不合。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“找不到”后面常接地点或路线，“公园的颜色”不能组成可以寻找的对象。"}], "explanations": {"天空": "语义：“天空”不是可以去寻找的地方，“找不到公园的天空”不通。", "出口": "“出口”指公园里可以走出去的门或通道，找不到的正是它，填入正确。", "音乐": "语义：“音乐”是声音艺术，不能作为园内的地点被找不到，句意不合。", "颜色": "搭配：“找不到”后面常接地点或路线，“公园的颜色”不能组成可以寻找的对象。"}, "sentence_index": 6, "correct_answer": "出口"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他终于找到了工作的出口。", "explanation": "这里应该用〈出路〉。“出口”只指具体的门或通道，比喻意义要说出路。"}, {"text": "这栋楼有一条出口，很宽。", "explanation": "这里不能用〈条〉。“出口”是地方，量词应该用〈个〉。"}, {"text": "我们公司今年从国外出口了很多机器。", "explanation": "这里应该用〈进口〉。“出口”指把货物运往国外卖出，从国外买进要说进口。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e82f6a0-beb9-4f40-83b9-f068af0d5d6d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21272, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个车站的一只出口在西边，很好找。", "corrected_sentence": "这个车站的一个出口在西边，很好找。", "error_description": "量词错误：“出口”应该用量词“个”，不能用“只”，“只”通常用于动物等。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e82f6a0-beb9-4f40-83b9-f068af0d5d6d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21272, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "地下通道的出口了在东边，很好找。", "corrected_sentence": "地下通道的出口在东边，很好找。", "error_description": "助词错误：名词“出口”后面不能加“了”，正确的说法是“出口在东边”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1e82f6a0-beb9-4f40-83b9-f068af0d5d6d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
