INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21278, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '547c9bf1-1d04-47df-8459-aa8d45987f7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21278, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "人种就是世界上不同的人，比如有黑皮肤的人、白皮肤的人和黄皮肤的人。", "primary_collocate": null, "pronunciation": "rén zhǒng", "ipa": "ʐən˧˥ ʈʂʊŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "人种不同，皮肤的颜色也常常不同。", "target_word": "人种", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这本书介绍了世界上的三大人种。", "target_word": "人种", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "不管是什么人种，大家都需要朋友。", "target_word": "人种", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师问我们：“世界上有几个人种？”", "target_word": "人种", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "白皮肤、黑皮肤和黄皮肤的人属于不同人种。", "target_word": "人种", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在这个学校里，有很多人种的学生。", "target_word": "人种", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们属于不同人种，但是成了好朋友。", "target_word": "人种", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "人种不一样，可是我们都说汉语。", "target_word": "人种", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "看一个人，不能只看他是什么人种。", "target_word": "人种", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个城市里住着各种人种的人。", "target_word": "人种", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "人種", "label": "繁体"}, {"form": "人种学", "label": "复合"}, {"form": "个", "label": "量词"}], "register": "中性", "sense_fingerprint": "世界上肤色等不同的人群", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94f37671-3cb2-4c91-96f6-cc44ccf4491d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21278, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "人种", "is_correct": true, "explanation": "人种：正确答案，指按肤色等不同划分的人群。"}, {"text": "性别", "is_correct": false, "explanation": "语义：性别与皮肤颜色无关，句意不通。"}, {"text": "人口", "is_correct": false, "explanation": "搭配：“人口”指人数，不用来说明肤色上的差别。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：年龄与皮肤颜色无关，句意不通。"}], "explanations": {"人种": "人种：正确答案，指按肤色等不同划分的人群。", "性别": "语义：性别与皮肤颜色无关，句意不通。", "人口": "搭配：“人口”指人数，不用来说明肤色上的差别。", "年龄": "语义：年龄与皮肤颜色无关，句意不通。"}, "sentence_index": 0, "correct_answer": "人种"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个地方的人说一种人种，很难听懂。", "explanation": "这里应该用〈方言〉。“人种”指按遗传特征划分的人群，语言差异要说“方言”。"}, {"text": "博物馆里展出了一条人种。", "explanation": "这里应该用〈个〉。“人种”是名词，量词用“个”；“条”多用于长形事物，不能用来数人种。"}, {"text": "这座岛上有几十个人种的鸟。", "explanation": "这里应该用〈物种〉。“人种”只指人类群体，鸟类要说“物种”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '547c9bf1-1d04-47df-8459-aa8d45987f7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21278, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "人种", "is_correct": true, "explanation": "人种：正确答案，表示有不同人种的人。"}, {"text": "身高", "is_correct": false, "explanation": "搭配：“属于不同身高”不成立，身高不能作为人的类别。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色是事物的属性，不指代人群，“属于不同颜色”句意不通。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：“属于不同体重”不成立，体重不能作为人的类别。"}], "explanations": {"人种": "人种：正确答案，表示有不同人种的人。", "身高": "搭配：“属于不同身高”不成立，身高不能作为人的类别。", "颜色": "语义：颜色是事物的属性，不指代人群，“属于不同颜色”句意不通。", "体重": "搭配：“属于不同体重”不成立，体重不能作为人的类别。"}, "sentence_index": 6, "correct_answer": "人种"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个农场养了很多人种的鸡。", "explanation": "这里应该用〈品种〉。“人种”只指人类群体，鸡的类别要说“品种”。"}, {"text": "这家超市卖很多人种的水果。", "explanation": "这里应该用〈种类〉。“人种”只指人类，水果的类别要说“种类”。"}, {"text": "我们班新来了一位人种。", "explanation": "这里应该用〈个〉。“人种”是名词，量词用“个”；“位”只用于具体的人，不能用来数人种。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '547c9bf1-1d04-47df-8459-aa8d45987f7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21278, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们研究了两只人种的差异。", "corrected_sentence": "我们研究了两个人种的差异。", "error_description": "错误：“两只人种”；正确：“两个人种”。“人种”是名词，量词用“个”；“只”多用于动物等。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '547c9bf1-1d04-47df-8459-aa8d45987f7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21278, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个班的同学来自两条人种。", "corrected_sentence": "这个班的同学来自两个人种。", "error_description": "错误：“两条人种”；正确：“两个人种”。“人种”是名词，量词用“个”；“条”用于长条形的事物。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '547c9bf1-1d04-47df-8459-aa8d45987f7c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
