INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21280, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "人们用东西换东西，或者用钱买东西。", "primary_collocate": null, "pronunciation": "mào yì", "ipa": "mau˥˩ i˥˩", "syllable_count": 2, "sentences": [{"text": "中国和很多国家做贸易。", "target_word": "贸易", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两个国家的贸易越来越多。", "target_word": "贸易", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在一家贸易公司工作。", "target_word": "贸易", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海上贸易已经有几百年的历史了。", "target_word": "贸易", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国际贸易让人们买到各国的东西。", "target_word": "贸易", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们两国之间的贸易很好。", "target_word": "贸易", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个港口的贸易很忙。", "target_word": "贸易", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "以前人们用盐做贸易。", "target_word": "贸易", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小镇靠贸易变得很有钱。", "target_word": "贸易", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两国政府想增加贸易。", "target_word": "贸易", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "国际贸易", "label": "复合"}, {"form": "贸易公司", "label": "复合"}, {"form": "貿易", "label": "繁体"}], "register": "书面", "sense_fingerprint": "国家、公司或个人之间买卖和交换商品", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be5ee50c-f9af-43f9-b71d-60fc13a41298') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21280, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "贸易", "is_correct": true, "explanation": "贸易 mào yì：国家或公司之间买卖商品、交换物品的活动。"}, {"text": "毛衣", "is_correct": false, "explanation": "máo yī（第二声、第一声）与 mào yì（第四声、第四声）两个音节的声调都不同，意思是毛线织成的上衣。"}, {"text": "冒雨", "is_correct": false, "explanation": "mào 相同，yǔ（第三声）与 yì（第四声）声调不同，意思是顶着雨（去做某事）。"}, {"text": "满意", "is_correct": false, "explanation": "mǎn（第三声）与 mào（第四声）韵母不同（an 与 ao），声调也不同，意思是对结果感到满足。"}, {"text": "好意", "is_correct": false, "explanation": "hǎo（第三声）与 mào（第四声）声母不同（h 与 m），韵母相同，意思是善意。"}], "explanations": {"贸易": "贸易 mào yì：国家或公司之间买卖商品、交换物品的活动。", "毛衣": "máo yī（第二声、第一声）与 mào yì（第四声、第四声）两个音节的声调都不同，意思是毛线织成的上衣。", "冒雨": "mào 相同，yǔ（第三声）与 yì（第四声）声调不同，意思是顶着雨（去做某事）。", "满意": "mǎn（第三声）与 mào（第四声）韵母不同（an 与 ao），声调也不同，意思是对结果感到满足。", "好意": "hǎo（第三声）与 mào（第四声）声母不同（h 与 m），韵母相同，意思是善意。"}, "sentence_index": null, "correct_answer": "贸易"}, "level_3": {"options": [{"text": "作业", "is_correct": false, "explanation": "语义：“作业”指学生的功课，国家之间不能“做作业”。"}, {"text": "贸易", "is_correct": true, "explanation": "“做贸易”指进行买卖交换，与“中国和很多国家”的对象相合。"}, {"text": "报纸", "is_correct": false, "explanation": "搭配：“做”不与“报纸”搭配，报纸要说“办”或“出版”。"}, {"text": "游戏", "is_correct": false, "explanation": "语义：“游戏”是娱乐活动，不能拿来和很多国家“做”。"}], "explanations": {"作业": "语义：“作业”指学生的功课，国家之间不能“做作业”。", "贸易": "“做贸易”指进行买卖交换，与“中国和很多国家”的对象相合。", "报纸": "搭配：“做”不与“报纸”搭配，报纸要说“办”或“出版”。", "游戏": "语义：“游戏”是娱乐活动，不能拿来和很多国家“做”。"}, "sentence_index": 0, "correct_answer": "贸易"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这道菜的贸易很香。", "explanation": "这里应该用〈味道〉。“贸易”是买卖活动，不能用来形容菜的香气，应说“味道”。"}, {"text": "他很有贸易。", "explanation": "这里应该用〈经验〉。“有经验”指懂得门道、做过某事，“贸易”是买卖活动本身，不能说“很有贸易”。"}, {"text": "他的贸易很感人。", "explanation": "这里应该用〈文章〉。“感人”形容作品或事迹，“贸易”是买卖活动，不能用“感人”来形容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26accaa6-266c-48d1-a7a2-07e94e88f0e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21280, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "考试", "is_correct": false, "explanation": "语义：“考试”是学生的活动，与港口无关，“港口的考试很忙”说不通。"}, {"text": "贸易", "is_correct": true, "explanation": "“港口的贸易很忙”指港口的买卖交换频繁，与“港口”和“很忙”相合。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：“忙”不用来形容价格，价格只说高或低。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”不会“忙”，也与港口的活动无关。"}], "explanations": {"考试": "语义：“考试”是学生的活动，与港口无关，“港口的考试很忙”说不通。", "贸易": "“港口的贸易很忙”指港口的买卖交换频繁，与“港口”和“很忙”相合。", "价格": "搭配：“忙”不用来形容价格，价格只说高或低。", "颜色": "语义：“颜色”不会“忙”，也与港口的活动无关。"}, "sentence_index": 6, "correct_answer": "贸易"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我的贸易增加了三公斤。", "explanation": "这里应该用〈体重〉。“贸易”是买卖活动，没有重量，不能用“公斤”计量，体重才说“增加”。"}, {"text": "他对家乡有很深的贸易。", "explanation": "这里应该用〈感情〉。“深”用于感情，“贸易”不能用“深”来形容。"}, {"text": "这座城市的贸易很漂亮。", "explanation": "这里应该用〈建筑〉。“漂亮”形容外观，“贸易”不能用“漂亮”来形容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26accaa6-266c-48d1-a7a2-07e94e88f0e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21280, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们公司和他们做了一只贸易。", "corrected_sentence": "我们公司和他们做了一笔贸易。", "error_description": "量词错误：“贸易”是一笔一笔的交易，量词应用“笔”。“只”用于动物或单件物品，不能用来数“贸易”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26accaa6-266c-48d1-a7a2-07e94e88f0e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21280, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "几百年前，这里的人就开始写贸易了。", "corrected_sentence": "几百年前，这里的人就开始做贸易了。", "error_description": "搭配错误：“贸易”要用“做”，不能用“写”，应说“做贸易”。“写”不能与“贸易”搭配。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26accaa6-266c-48d1-a7a2-07e94e88f0e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
