INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21288, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "被装是军队或某些单位发给人的衣服和被子。", "primary_collocate": null, "pronunciation": "bèi zhuāng", "ipa": "pei˥˩ ʈʂwaŋ˥", "syllable_count": 2, "sentences": [{"text": "新兵到了部队，先领了被装。", "target_word": "被装", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "部队每年都会发放新的被装。", "target_word": "被装", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的被装整齐地放在床上。", "target_word": "被装", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "战士们领到了冬季被装。", "target_word": "被装", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "被装不够用，班长去仓库换了一些。", "target_word": "被装", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "连队的被装已经全部发完了。", "target_word": "被装", "complexity_tier": "T3", "furigana": "lián duì de bèi zhuāng yǐ jīng quán bù fā wán le", "sentence_source": "generated"}, {"text": "军人的被装由部队统一发放。", "target_word": "被装", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这批被装都是为新兵准备的。", "target_word": "被装", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把旧被装还给了仓库。", "target_word": "被装", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "退伍的时候，他交回了所有被装。", "target_word": "被装", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "套", "label": "量词"}], "register": "中性", "sense_fingerprint": "军队、警察等单位发给个人的衣服和被子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a205f67f-de37-430b-aeff-79a766f5bb67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21288, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "被装", "is_correct": true, "explanation": "被装（bèi zhuāng）指军队或单位发给个人的衣服和被子，是正确答案。"}, {"text": "被撞", "is_correct": false, "explanation": "被撞（bèi zhuàng）与被装的第二个音节声调不同（zhuàng 为第四声，zhuāng 为第一声），意思是被撞击。"}, {"text": "悲壮", "is_correct": false, "explanation": "悲壮（bēi zhuàng）两个音节的声调都与被装不同（bēi 为第一声，bèi 为第四声；zhuàng 为第四声，zhuāng 为第一声），意思是悲伤而雄壮。"}, {"text": "美妆", "is_correct": false, "explanation": "美妆（měi zhuāng）第一音节声母与声调不同（měi 为 m- 声母、第三声，bèi 为 b- 声母、第四声），意思是美容化妆。"}], "explanations": {"被装": "被装（bèi zhuāng）指军队或单位发给个人的衣服和被子，是正确答案。", "被撞": "被撞（bèi zhuàng）与被装的第二个音节声调不同（zhuàng 为第四声，zhuāng 为第一声），意思是被撞击。", "悲壮": "悲壮（bēi zhuàng）两个音节的声调都与被装不同（bēi 为第一声，bèi 为第四声；zhuàng 为第四声，zhuāng 为第一声），意思是悲伤而雄壮。", "美妆": "美妆（měi zhuāng）第一音节声母与声调不同（měi 为 m- 声母、第三声，bèi 为 b- 声母、第四声），意思是美容化妆。"}, "sentence_index": null, "correct_answer": "被装"}, "level_3": {"options": [{"text": "被装", "is_correct": true, "explanation": "被装：与“领了”搭配，指部队发给新兵的衣被，是唯一符合语境的词。"}, {"text": "校服", "is_correct": false, "explanation": "语义：校服是学校的服装，与“新兵到了部队”的语境不符。"}, {"text": "机票", "is_correct": false, "explanation": "语义：机票是乘机凭证，与部队发放衣被无关，“新兵到了部队，先领了机票”句意不通。"}, {"text": "学费", "is_correct": false, "explanation": "语义：学费是交给学校的钱，不是部队发放的东西。"}], "explanations": {"被装": "被装：与“领了”搭配，指部队发给新兵的衣被，是唯一符合语境的词。", "校服": "语义：校服是学校的服装，与“新兵到了部队”的语境不符。", "机票": "语义：机票是乘机凭证，与部队发放衣被无关，“新兵到了部队，先领了机票”句意不通。", "学费": "语义：学费是交给学校的钱，不是部队发放的东西。"}, "sentence_index": 0, "correct_answer": "被装"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这床被装是妈妈亲手缝的，很暖和。", "explanation": "这里应该用〈被子〉。被装是军队或单位统一发的，不是家人亲手缝的。"}, {"text": "我们班领到了三只被装。", "explanation": "量词错误：被装应用〈套〉，不用〈只〉。“只”多用于单个动物或成对物品中的一个。"}, {"text": "我在超市买了一床被装，很便宜。", "explanation": "这里应该用〈毛毯〉。被装是军队或单位配发的，超市里买的不是被装。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ea95ddf-7bed-40ca-9eb5-3364ba2f79f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21288, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "被装", "is_correct": true, "explanation": "被装：军人的被装由部队统一发放，是唯一符合语境的词。"}, {"text": "课本", "is_correct": false, "explanation": "语义：课本由学校发放，与“军人”和“部队”的语境不符。"}, {"text": "学籍", "is_correct": false, "explanation": "语义：学籍与学校有关，不是部队发给军人的东西。"}, {"text": "电费", "is_correct": false, "explanation": "搭配：“发放”多用于物资、奖金，电费是缴纳的，不说发放。"}], "explanations": {"被装": "被装：军人的被装由部队统一发放，是唯一符合语境的词。", "课本": "语义：课本由学校发放，与“军人”和“部队”的语境不符。", "学籍": "语义：学籍与学校有关，不是部队发给军人的东西。", "电费": "搭配：“发放”多用于物资、奖金，电费是缴纳的，不说发放。"}, "sentence_index": 6, "correct_answer": "被装"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在沙发上盖着被装看电视。", "explanation": "这里应该用〈毛毯〉。被装是军队或单位配发的，在沙发上看电视时盖的不是被装。"}, {"text": "他领到了一件被装。", "explanation": "量词错误：被装应用〈套〉，不用〈件〉。“件”用于单件衣物，被装是成套配发的。"}, {"text": "他冬天戴着被装出门。", "explanation": "这里应该用〈手套〉。被装是成套的衣被，不指戴在手上的单件手套。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ea95ddf-7bed-40ca-9eb5-3364ba2f79f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21288, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "仓库里有一只新被装。", "corrected_sentence": "仓库里有一套新被装。", "error_description": "量词错误：被装应使用量词“套”，不能用“只”。“只”多用于单个动物或成对物品中的一个。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ea95ddf-7bed-40ca-9eb5-3364ba2f79f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21288, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "班长把发给新兵被装收好了。", "corrected_sentence": "班长把发给新兵的被装收好了。", "error_description": "定语标记错误：“发给新兵”修饰“被装”时，中间要用“的”连接，应说“发给新兵的被装”；漏掉“的”，“新兵被装”不成词组，句子不通。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ea95ddf-7bed-40ca-9eb5-3364ba2f79f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21290, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "修理", "is_correct": false, "explanation": "修理是使物品恢复正常，与运送无关，不是“运到”的反义词。"}, {"text": "运走", "is_correct": true, "explanation": "“运走”与“运到”相对：运到是运送到说话人这里，运走是从这里运出去。"}, {"text": "参观", "is_correct": false, "explanation": "参观是去看展览或景点等，与运送无关，也不构成反义。"}, {"text": "讨论", "is_correct": false, "explanation": "讨论是交换意见，与运送无关，不是“运到”的反义词。"}], "correct_answer": "运走", "explanations": {"修理": "修理是使物品恢复正常，与运送无关，不是“运到”的反义词。", "运走": "“运走”与“运到”相对：运到是运送到说话人这里，运走是从这里运出去。", "参观": "参观是去看展览或景点等，与运送无关，也不构成反义。", "讨论": "讨论是交换意见，与运送无关，不是“运到”的反义词。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ea95ddf-7bed-40ca-9eb5-3364ba2f79f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21290, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "打扫", "is_correct": false, "explanation": "打扫是清理卫生，与运送无关，不是“运到”的反义词。"}, {"text": "运走", "is_correct": true, "explanation": "“运走”与“运到”相对：运到是运送到这里，运走是从这里运出去。"}, {"text": "唱歌", "is_correct": false, "explanation": "唱歌是发出歌声，与运送无关，不构成反义。"}, {"text": "原谅", "is_correct": false, "explanation": "原谅是不再怪罪，与运送无关，不是“运到”的反义词。"}], "correct_answer": "运走", "explanations": {"打扫": "打扫是清理卫生，与运送无关，不是“运到”的反义词。", "运走": "“运走”与“运到”相对：运到是运送到这里，运走是从这里运出去。", "唱歌": "唱歌是发出歌声，与运送无关，不构成反义。", "原谅": "原谅是不再怪罪，与运送无关，不是“运到”的反义词。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ea95ddf-7bed-40ca-9eb5-3364ba2f79f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21290, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用车、船等把货物从别处运送到某个地方。", "primary_collocate": null, "pronunciation": "yùn dào", "ipa": "yn˥˩ tau̯˥˩", "syllable_count": 2, "sentences": [{"text": "新买的桌子今天运到我家了。", "target_word": "运到", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这些书是从北京运到这里的。", "target_word": "运到", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "货什么时候能运到我们这儿？", "target_word": "运到", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "冰箱今天下午会运到我家。", "target_word": "运到", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "海边的鱼一早就运到了市场。", "target_word": "运到", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "蔬菜运到这里要两个小时。", "target_word": "运到", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "要是东西运到了，请给我打电话。", "target_word": "运到", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你的行李已经运到酒店了。", "target_word": "运到", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这批菜刚运到，还很新鲜。", "target_word": "运到", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他把家具从老家运到了这个城市。", "target_word": "运到", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "运到了", "label": "完成体"}, {"form": "运不到", "label": "否定可能补语"}], "register": "中性", "sense_fingerprint": "货物用车船等从别处被运送到某个地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a205f67f-de37-430b-aeff-79a766f5bb67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21290, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "吃到", "is_correct": false, "explanation": "语义：“吃”只能用于食物，桌子不能被吃，“吃到我家”不成立。"}, {"text": "运到", "is_correct": true, "explanation": "“运到”表示把东西从别处运送来，与“新买的桌子”和“到我家”相符。"}, {"text": "听到", "is_correct": false, "explanation": "配价：“听”不表示位移，不能带处所补语“到我家”，句子不通。"}, {"text": "飞到", "is_correct": false, "explanation": "语义：桌子不会自己飞行，“飞到我家”与桌子被运送的情境不符。"}], "explanations": {"吃到": "语义：“吃”只能用于食物，桌子不能被吃，“吃到我家”不成立。", "运到": "“运到”表示把东西从别处运送来，与“新买的桌子”和“到我家”相符。", "听到": "配价：“听”不表示位移，不能带处所补语“到我家”，句子不通。", "飞到": "语义：桌子不会自己飞行，“飞到我家”与桌子被运送的情境不符。"}, "sentence_index": 0, "correct_answer": "运到"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他下班后把我运到了车站。", "explanation": "这里应该用〈送〉。“运”侧重成批运输，日常把一个人送到某处要说“送”。"}, {"text": "他的想法运到了大家面前。", "explanation": "这里应该用〈传达〉。运到指把实物运送到某处，用于抽象的想法时要说「传达」或「传到」，不能用「运」。"}, {"text": "妈妈每天把孩子运到幼儿园。", "explanation": "这里应该用〈带〉。“运”侧重成批运输，接送孩子要说“带”或“送”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ea95ddf-7bed-40ca-9eb5-3364ba2f79f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21290, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "唱", "is_correct": false, "explanation": "语义：东西不会唱歌，“要是东西唱了”与后文的情境不符。"}, {"text": "运到", "is_correct": true, "explanation": "“运到”表示把东西运送到说话人处，与“东西”“了”相符，句意是东西送到了。"}, {"text": "讲", "is_correct": false, "explanation": "配价：“讲”需要说话的内容作宾语，不能以“东西”作主语表示到达。"}, {"text": "笑", "is_correct": false, "explanation": "语义：东西不会笑，“要是东西笑了”与“请给我打电话”之间没有合理的联系。"}], "explanations": {"唱": "语义：东西不会唱歌，“要是东西唱了”与后文的情境不符。", "运到": "“运到”表示把东西运送到说话人处，与“东西”“了”相符，句意是东西送到了。", "讲": "配价：“讲”需要说话的内容作宾语，不能以“东西”作主语表示到达。", "笑": "语义：东西不会笑，“要是东西笑了”与“请给我打电话”之间没有合理的联系。"}, "sentence_index": 6, "correct_answer": "运到"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "一只小鸟运到了树上。", "explanation": "这里应该用〈飞〉。运到只用于被运送的货物，小鸟会自己飞，不能说被“运”。"}, {"text": "河水运到了大海。", "explanation": "这里应该用〈流〉。运到只用于货物，河水是自然流动的，不能说“运”。"}, {"text": "他把一杯水运到了桌上。", "explanation": "这里应该用〈端〉。运到指用车船等大批量运送货物，把一杯水从别处端到桌上要用「端」，不能用「运」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ea95ddf-7bed-40ca-9eb5-3364ba2f79f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21290, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "工人已经货运到了仓库。", "corrected_sentence": "工人已经把货运到了仓库。", "error_description": "把字句错误：“运到”之前的宾语“货”需用“把”引出，应说“工人已经把货运到了仓库”；“工人已经货运到了仓库”中“货”直接放在动词前，句子不成立。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ea95ddf-7bed-40ca-9eb5-3364ba2f79f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21290, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这批机器还没运到了工厂。", "corrected_sentence": "这批机器还没运到工厂。", "error_description": "体标与否定词错误：“没”否定已发生的动作时句末不能再带“了”，应说“还没运到工厂”，不说“还没运到了工厂”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ea95ddf-7bed-40ca-9eb5-3364ba2f79f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
