INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21294, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "商店的内部空间，与“店外”相对。", "primary_collocate": null, "pronunciation": "diàn lǐ", "ipa": "tjɛn⁵¹ li²¹⁴", "syllable_count": 2, "sentences": [{"text": "店外很冷，店里很暖和。", "target_word": "店里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "店门关着，我从外面看不清店里的样子。", "target_word": "店里", "complexity_tier": "T3", "furigana": "diàn li", "sentence_source": "generated"}, {"text": "你先在门口等，我进去看看店里有没有座位。", "target_word": "店里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "店里很安静，只有两三个客人。", "target_word": "店里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店不大，店里只放得下四张桌子。", "target_word": "店里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗跑进了店里，老板吓了一跳。", "target_word": "店里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请不要在店里大声说话。", "target_word": "店里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "店里的空调坏了，我们都出汗了。", "target_word": "店里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨停了，大家从店里走了出来。", "target_word": "店里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把新书摆在店里最显眼的地方。", "target_word": "店里", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "店裡", "label": "繁体"}, {"form": "店里面", "label": "复合"}], "register": "口语", "sense_fingerprint": "商店内部的空间（与店外相对）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '24631489-7be5-43ad-b7ec-de458e1dff98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21294, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "店里", "is_correct": true, "explanation": "正确答案：店里（diànlǐ），指商店的内部空间。"}, {"text": "典礼", "is_correct": false, "explanation": "diǎnlǐ 与 diànlǐ 第一音节声调不同（第三声 / 第四声），意思是典礼。"}, {"text": "电力", "is_correct": false, "explanation": "diànlì 与 diànlǐ 第二音节声调不同（第四声 / 第三声），意思是电力。"}, {"text": "县里", "is_correct": false, "explanation": "xiànlǐ 与 diànlǐ 第一音节声母不同（x / d），意思是县里（县的内部或县政府）。"}], "explanations": {"店里": "正确答案：店里（diànlǐ），指商店的内部空间。", "典礼": "diǎnlǐ 与 diànlǐ 第一音节声调不同（第三声 / 第四声），意思是典礼。", "电力": "diànlì 与 diànlǐ 第二音节声调不同（第四声 / 第三声），意思是电力。", "县里": "xiànlǐ 与 diànlǐ 第一音节声母不同（x / d），意思是县里（县的内部或县政府）。"}, "sentence_index": null, "correct_answer": "店里"}, "level_3": {"options": [{"text": "店里", "is_correct": true, "explanation": "正确：店里与前句的店外相对，指店内暖和。"}, {"text": "店外", "is_correct": false, "explanation": "语义：前句说店外很冷，“店外很暖和”自相矛盾。"}, {"text": "外面", "is_correct": false, "explanation": "语义：与前句“店外很冷”指同一处所，“外面很暖和”自相矛盾。"}, {"text": "冰箱", "is_correct": false, "explanation": "搭配：“很暖和”用于房间、空间，不能说冰箱暖和。"}], "explanations": {"店里": "正确：店里与前句的店外相对，指店内暖和。", "店外": "语义：前句说店外很冷，“店外很暖和”自相矛盾。", "外面": "语义：与前句“店外很冷”指同一处所，“外面很暖和”自相矛盾。", "冰箱": "搭配：“很暖和”用于房间、空间，不能说冰箱暖和。"}, "sentence_index": 0, "correct_answer": "店里"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他爬到店里的山顶看日出。", "explanation": "这里应该用〈店外〉。“店里”指店内部，“山顶”在室外，位置冲突。"}, {"text": "我们在店里的湖边钓鱼。", "explanation": "这里应该用〈店外〉。“店里”表示店内，与“湖边”的室外位置相冲突。"}, {"text": "这些羊在店里的高速公路上吃草。", "explanation": "这里应该用〈店外〉。“店里”指店内，“高速公路”在室外，二者位置冲突。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8169780f-25c6-4833-86ed-eeb43322c526') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21294, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "店里", "is_correct": true, "explanation": "正确答案：店里（diànlǐ），指商店的内部空间。"}, {"text": "献礼", "is_correct": false, "explanation": "xiànlǐ 与 diànlǐ 第一音节声母不同（x / d），意思是献礼。"}, {"text": "电笔", "is_correct": false, "explanation": "diànbǐ 与 diànlǐ 第二音节声母不同（b / l），意思是电笔（测电的工具）。"}, {"text": "电离", "is_correct": false, "explanation": "diànlí 与 diànlǐ 第二音节声调不同（第二声 / 第三声），意思是电离（化学术语）。"}], "explanations": {"店里": "正确答案：店里（diànlǐ），指商店的内部空间。", "献礼": "xiànlǐ 与 diànlǐ 第一音节声母不同（x / d），意思是献礼。", "电笔": "diànbǐ 与 diànlǐ 第二音节声母不同（b / l），意思是电笔（测电的工具）。", "电离": "diànlí 与 diànlǐ 第二音节声调不同（第二声 / 第三声），意思是电离（化学术语）。"}, "sentence_index": null, "correct_answer": "店里"}, "level_3": {"options": [{"text": "店里", "is_correct": true, "explanation": "正确：店里指店内，在店内说话才会受到“不要大声”的约束。"}, {"text": "天空", "is_correct": false, "explanation": "语义：天空不是人可以聚集说话的处所，句子不通。"}, {"text": "大海", "is_correct": false, "explanation": "语义：大海不是可以在其中交谈的场所，与“在…说话”不合。"}, {"text": "柜子", "is_correct": false, "explanation": "搭配：“在…说话”的处所需能容纳人，柜子不能与之搭配。"}], "explanations": {"店里": "正确：店里指店内，在店内说话才会受到“不要大声”的约束。", "天空": "语义：天空不是人可以聚集说话的处所，句子不通。", "大海": "语义：大海不是可以在其中交谈的场所，与“在…说话”不合。", "柜子": "搭配：“在…说话”的处所需能容纳人，柜子不能与之搭配。"}, "sentence_index": 6, "correct_answer": "店里"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把新书放在店里的海底。", "explanation": "这里应该用〈店外〉。“店里”指店内，“海底”是水下深处，二者不能同时作处所。"}, {"text": "他把新书摆在店里的沙漠上。", "explanation": "这里应该用〈店外〉。“店里”指店内，“沙漠”是室外荒地，二者位置相冲突。"}, {"text": "他把新书堆在店里的高速公路旁。", "explanation": "这里应该用〈店外〉。“高速公路”在店外，与表示店内的“店里”矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8169780f-25c6-4833-86ed-eeb43322c526') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21294, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我在店里里挑了一双袜子。", "corrected_sentence": "我在店里挑了一双袜子。", "error_description": "错误：“店里里”，多加了一个“里”。正确：“店里”。“里”已包含在“店里”之中，不能重复。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8169780f-25c6-4833-86ed-eeb43322c526') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21294, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈店里挑了一件毛衣。", "corrected_sentence": "妈妈在店里挑了一件毛衣。", "error_description": "错误：“妈妈店里挑”，缺少介词“在”。正确：“妈妈在店里挑”。“店里”作处所状语，需用“在”引出。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8169780f-25c6-4833-86ed-eeb43322c526') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
