INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21302, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "用布、纸、塑料等材料制成、可以装东西的器物。", "primary_collocate": null, "pronunciation": "dài zi", "ipa": "tai˥˩ tsɨ", "syllable_count": 2, "sentences": [{"text": "她背着一个蓝色的袋子去学校。", "target_word": "袋子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "袋子里有三本书和一瓶水。", "target_word": "袋子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个袋子太小，装不下我的衣服。", "target_word": "袋子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我把垃圾放进一个黑袋子里。", "target_word": "袋子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他提着袋子走进商店。", "target_word": "袋子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个袋子是布做的，洗一洗还能用。", "target_word": "袋子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把袋子打开，我来放水果。", "target_word": "袋子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "袋子太重了，我拿不动。", "target_word": "袋子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗咬着一个袋子跑了。", "target_word": "袋子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在袋子上写了自己的名字。", "target_word": "袋子", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个袋子", "label": "量词"}, {"form": "纸袋子", "label": "复合"}, {"form": "塑料袋子", "label": "复合"}], "register": "中性", "sense_fingerprint": "布、纸或塑料制成的可装东西的器物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd70a85e3-8683-4acb-9c19-ccb5efd1bd2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21302, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "袋子", "is_correct": true, "explanation": "袋子（dài zi）是用来装东西的器具，是正确答案。"}, {"text": "对子", "is_correct": false, "explanation": "dài 与 duì 韵母不同（ai 与 ui），意思是成对的对联或成对的东西。"}, {"text": "太子", "is_correct": false, "explanation": "d 与 t 声母不同（不送气与送气），意思是君主的继承人。"}, {"text": "稻子", "is_correct": false, "explanation": "dài 与 dào 韵母不同（ai 与 ao），意思是水稻。"}], "explanations": {"袋子": "袋子（dài zi）是用来装东西的器具，是正确答案。", "对子": "dài 与 duì 韵母不同（ai 与 ui），意思是成对的对联或成对的东西。", "太子": "d 与 t 声母不同（不送气与送气），意思是君主的继承人。", "稻子": "dài 与 dào 韵母不同（ai 与 ao），意思是水稻。"}, "sentence_index": null, "correct_answer": "袋子"}, "level_3": {"options": [{"text": "袋子", "is_correct": true, "explanation": "“背着”可以背袋子，“一个蓝色的袋子”可以填入。"}, {"text": "黑板", "is_correct": false, "explanation": "语义：黑板是教室里的设备，不能背着去学校。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱太重，不能背着去学校。"}, {"text": "眼镜", "is_correct": false, "explanation": "搭配：“背”不搭配眼镜，眼镜是戴在脸上的。"}], "explanations": {"袋子": "“背着”可以背袋子，“一个蓝色的袋子”可以填入。", "黑板": "语义：黑板是教室里的设备，不能背着去学校。", "冰箱": "语义：冰箱太重，不能背着去学校。", "眼镜": "搭配：“背”不搭配眼镜，眼镜是戴在脸上的。"}, "sentence_index": 0, "correct_answer": "袋子"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我把垃圾放进一块黑袋子里。", "explanation": "这里应该用〈个〉。“块”用于块状的东西，袋子不能用“块”。"}, {"text": "我把垃圾放进一朵黑袋子里。", "explanation": "这里应该用〈个〉。“朵”用于花朵、云朵等，袋子不能用“朵”。"}, {"text": "我把垃圾放进一张黑袋子里。", "explanation": "这里应该用〈个〉。“张”用于纸、桌子等平面物体，袋子不能用“张”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75032242-aa41-4dc6-a1af-4b3c4359a516') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21302, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "袋子", "is_correct": true, "explanation": "袋子（dài zi）是用来装东西的器具，是正确答案。"}, {"text": "盖子", "is_correct": false, "explanation": "dài 与 gài 声母不同（d 与 g），意思是器物的盖子。"}, {"text": "弹子", "is_correct": false, "explanation": "dài 与 dàn 韵母不同（ai 与 an），意思是弹珠。"}, {"text": "赖子", "is_correct": false, "explanation": "dài 与 lài 声母不同（d 与 l），意思是无赖，或麻将中的百搭牌。"}], "explanations": {"袋子": "袋子（dài zi）是用来装东西的器具，是正确答案。", "盖子": "dài 与 gài 声母不同（d 与 g），意思是器物的盖子。", "弹子": "dài 与 dàn 韵母不同（ai 与 an），意思是弹珠。", "赖子": "dài 与 lài 声母不同（d 与 l），意思是无赖，或麻将中的百搭牌。"}, "sentence_index": null, "correct_answer": "袋子"}, "level_3": {"options": [{"text": "袋子", "is_correct": true, "explanation": "“打开”后接可以打开的容器，“袋子”可以填入。"}, {"text": "墙", "is_correct": false, "explanation": "语义：墙不能打开，也装不了水果。"}, {"text": "镜子", "is_correct": false, "explanation": "搭配：“打开”不搭配镜子，镜子也不能用来放水果。"}, {"text": "树", "is_correct": false, "explanation": "搭配：“打开”不搭配树，树也无法用来放水果。"}], "explanations": {"袋子": "“打开”后接可以打开的容器，“袋子”可以填入。", "墙": "语义：墙不能打开，也装不了水果。", "镜子": "搭配：“打开”不搭配镜子，镜子也不能用来放水果。", "树": "搭配：“打开”不搭配树，树也无法用来放水果。"}, "sentence_index": 6, "correct_answer": "袋子"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她端起袋子，喝了一口水。", "explanation": "这里应该用〈杯子〉。喝水要端杯子，袋子不能端起来喝水。"}, {"text": "她对着袋子照了照。", "explanation": "这里应该用〈镜子〉。“照”要对着镜子，袋子不能反射影像。"}, {"text": "她拿起袋子，给朋友打了个电话。", "explanation": "这里应该用〈手机〉。打电话要用手机，袋子不能用来打电话。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75032242-aa41-4dc6-a1af-4b3c4359a516') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21302, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她买了一块新袋子。", "corrected_sentence": "她买了一个新袋子。", "error_description": "“袋子”的量词应用“个”，不能用“块”。“块”用于块状的东西，袋子要用“个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75032242-aa41-4dc6-a1af-4b3c4359a516') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21302, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他拎着一个很重袋子回家。", "corrected_sentence": "他拎着一个很重的袋子回家。", "error_description": "修饰语“很重”与名词“袋子”之间漏了“的”。修饰语是词组时要用“的”连接，应说“很重的袋子”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75032242-aa41-4dc6-a1af-4b3c4359a516') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
