INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21310, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "身体动一动，或者做一件事。", "primary_collocate": null, "pronunciation": "huó dòng", "ipa": "xuɔ˧˥ tʊŋ˥˩", "syllable_count": 2, "sentences": [{"text": "坐了很久，我站起来活动一下。", "target_word": "活动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "早上先活动活动身体再跑步。", "target_word": "活动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说他的腿可以慢慢活动了。", "target_word": "活动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗在院子里自由活动。", "target_word": "活动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "上课前，老师让我们活动一下手和脚。", "target_word": "活动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的手受伤了，不能活动。", "target_word": "活动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每天坐着工作，要多活动身体。", "target_word": "活动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天天冷，孩子们在屋里活动。", "target_word": "活动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛前，运动员先活动腿。", "target_word": "活动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "坐了十个小时，下飞机后我想活动一下。", "target_word": "活动", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "活动活动", "label": "重叠"}, {"form": "活动了", "label": "完成体"}, {"form": "活动着", "label": "持续体"}], "register": "中性", "sense_fingerprint": "让身体动一动，放松手脚", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77d97711-45c9-40d1-a540-071631f184cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21310, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "活动", "is_correct": true, "explanation": "正确：“活动”指动一动身体，与“站起来”和“一下”相合。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：“睡觉”与“站起来”动一动的意思相反，句子说的是要活动身体。"}, {"text": "洗澡", "is_correct": false, "explanation": "语义：“洗澡”指清洗身体，与“站起来动一动”的意思不符。"}, {"text": "游泳", "is_correct": false, "explanation": "语义：坐了很久后站起来，不是去游泳，与句意不符。"}], "explanations": {"活动": "正确：“活动”指动一动身体，与“站起来”和“一下”相合。", "睡觉": "语义：“睡觉”与“站起来”动一动的意思相反，句子说的是要活动身体。", "洗澡": "语义：“洗澡”指清洗身体，与“站起来动一动”的意思不符。", "游泳": "语义：坐了很久后站起来，不是去游泳，与句意不符。"}, "sentence_index": 0, "correct_answer": "活动"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "周末我们一家人去云南活动了一周。", "explanation": "这里应该用〈旅游〉。出门游览用“旅游”，“活动”指身体动一动或做一件事，不表示外出游玩。"}, {"text": "他的脑子很活动，总能想出新办法。", "explanation": "这里应该用〈灵活〉。形容人反应快、变通力强用“灵活”，“活动”不能用来形容人的头脑。"}, {"text": "这列火车每天准时活动。", "explanation": "这里应该用〈运行〉。车辆有规律地行进用“运行”，“活动”不用于这种意义。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc650faf-eef1-4b87-8649-678eec955448') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21310, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "活动", "is_correct": true, "explanation": "正确：句子要求坐着工作的人多动动身体，“活动”指动一动身体，符合语境。"}, {"text": "伤害", "is_correct": false, "explanation": "语义：“伤害”是损伤，与句中“要多……身体”的建议相反。"}, {"text": "扔", "is_correct": false, "explanation": "搭配：“扔”的对象是具体物品，不能用来处理身体。"}, {"text": "消耗", "is_correct": false, "explanation": "搭配：“消耗”多指耗费能量、钱财，不能说“消耗身体”。"}], "explanations": {"活动": "正确：句子要求坐着工作的人多动动身体，“活动”指动一动身体，符合语境。", "伤害": "语义：“伤害”是损伤，与句中“要多……身体”的建议相反。", "扔": "搭配：“扔”的对象是具体物品，不能用来处理身体。", "消耗": "搭配：“消耗”多指耗费能量、钱财，不能说“消耗身体”。"}, "sentence_index": 6, "correct_answer": "活动"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他听到这个消息，活动得说不出话。", "explanation": "这里应该用〈激动〉。因情绪而心潮起伏用“激动”，“活动”指身体动一动或做一件事，不表示内心的情绪。"}, {"text": "公司决定活动三名员工的岗位。", "explanation": "这里应该用〈调动〉。人员的岗位变换用“调动”，“活动”没有这个意思。"}, {"text": "管道把天然气活动到各家各户。", "explanation": "这里应该用〈输送〉。把天然气等物资运送到各处用“输送”，“活动”不用于这种意义。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc650faf-eef1-4b87-8649-678eec955448') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21310, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "下班以后，我想出去活动一个下。", "corrected_sentence": "下班以后，我想出去活动一下。", "error_description": "量词错误：“一下”是动词后的动量短语，不能用量词“个”，写成“活动一个下”不通顺，应改为“活动一下”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc650faf-eef1-4b87-8649-678eec955448') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21310, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他的腿躺久了，慢慢活动下来了。", "corrected_sentence": "他的腿躺久了，慢慢活动起来了。", "error_description": "补语错误：身体部位从不能动到能动，应接趋向补语“起来”，写成“下来”不通顺，应改为“活动起来”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc650faf-eef1-4b87-8649-678eec955448') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
