INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21326, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指全世界各个地方。", "primary_collocate": null, "pronunciation": "shì jiè gè dì", "ipa": "ʂɻ̩˥˩ tɕjɛ˥˩ kɤ˥˩ ti˥˩", "syllable_count": 4, "sentences": [{"text": "世界各地都有中国餐馆。", "target_word": "世界各地", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他工作很忙，常常飞到世界各地。", "target_word": "世界各地", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "世界各地的孩子都爱玩游戏。", "target_word": "世界各地", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位老师在世界各地教过中文。", "target_word": "世界各地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "世界各地的天气不一样。", "target_word": "世界各地", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "网络让世界各地的人可以聊天。", "target_word": "世界各地", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我收集了世界各地的明信片。", "target_word": "世界各地", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "现在世界各地都有人过春节。", "target_word": "世界各地", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我的同学去了世界各地工作。", "target_word": "世界各地", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "世界各地的足球迷都在看比赛。", "target_word": "世界各地", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "全世界的各个地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18eb6d63-0232-4cd9-8252-5118ed2ad4bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21326, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "世界各地", "is_correct": true, "explanation": "“世界各地”指全世界各个地方，与“都有中国餐馆”的范围相符。"}, {"text": "月球", "is_correct": false, "explanation": "语义：月球上没有餐馆，句子不成立。"}, {"text": "无人区", "is_correct": false, "explanation": "语义：无人区没有人居住，自然不会有餐馆，句意不通。"}, {"text": "海底", "is_correct": false, "explanation": "搭配：中国餐馆不会开在海底，“海底”与“餐馆”搭配不当。"}], "explanations": {"世界各地": "“世界各地”指全世界各个地方，与“都有中国餐馆”的范围相符。", "月球": "语义：月球上没有餐馆，句子不成立。", "无人区": "语义：无人区没有人居住，自然不会有餐馆，句意不通。", "海底": "搭配：中国餐馆不会开在海底，“海底”与“餐馆”搭配不当。"}, "sentence_index": 0, "correct_answer": "世界各地"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这所学校的世界各地都有篮球场。", "explanation": "这里应该用〈各处〉。“世界各地”指全球，不能用来指一所学校之内。"}, {"text": "我家世界各地有很多超市。", "explanation": "这里应该用〈附近〉。“世界各地”是全球范围，不能用来指家附近。"}, {"text": "这个公园的世界各地都种满了花。", "explanation": "这里应该用〈各个角落〉。“世界各地”指全球，不能用来指一个公园里的各处。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b861901-a8a7-4920-a931-2ea8e81bdd82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21326, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "世界各地", "is_correct": true, "explanation": "“世界各地”能修饰“明信片”，表示来自各处，句意通顺。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气不能被收集成明信片，句意不通。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱不是明信片的来源或类别，句意不通。"}, {"text": "电脑", "is_correct": false, "explanation": "搭配：“电脑的明信片”与“收集”搭配不当，明信片不是电脑的产物。"}], "explanations": {"世界各地": "“世界各地”能修饰“明信片”，表示来自各处，句意通顺。", "空气": "语义：空气不能被收集成明信片，句意不通。", "冰箱": "语义：冰箱不是明信片的来源或类别，句意不通。", "电脑": "搭配：“电脑的明信片”与“收集”搭配不当，明信片不是电脑的产物。"}, "sentence_index": 6, "correct_answer": "世界各地"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我的弟弟和世界各地是好朋友。", "explanation": "这里应该用〈一位同学〉。“世界各地”指许多地方，不能指一个人。"}, {"text": "他把书放在了书架的世界各地。", "explanation": "这里应该用〈各层〉。“世界各地”指全球，不能用来指一个书架的各层。"}, {"text": "这所医院的世界各地都有病人。", "explanation": "这里应该用〈各个病房〉。“世界各地”指全球，不能用来指一所医院之内。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b861901-a8a7-4920-a931-2ea8e81bdd82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21326, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个故事传了世界各地。", "corrected_sentence": "这个故事传到了世界各地。", "error_description": "错误：“传”后漏掉趋向补语“到”。正确说法是“传到了世界各地”，“传了世界各地”不成立，“到”不能省略。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b861901-a8a7-4920-a931-2ea8e81bdd82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21326, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她在世界各地的有很多朋友。", "corrected_sentence": "她在世界各地有很多朋友。", "error_description": "错误：“世界各地”后面多加了“的”，“的”后面没有中心语，句子不通。正确说法是“她在世界各地有很多朋友”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b861901-a8a7-4920-a931-2ea8e81bdd82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21338, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "播种", "is_correct": true, "explanation": "播种是撒下种子，与收获（把成熟的果实取下来）相对。"}, {"text": "清洗", "is_correct": false, "explanation": "清洗是把东西弄干净，与收获没有反义关系。"}, {"text": "散步", "is_correct": false, "explanation": "散步是慢慢走路，与收获没有反义关系。"}, {"text": "翻译", "is_correct": false, "explanation": "翻译是把一种语言转成另一种语言，与收获没有反义关系。"}], "correct_answer": "播种", "explanations": {"播种": "播种是撒下种子，与收获（把成熟的果实取下来）相对。", "清洗": "清洗是把东西弄干净，与收获没有反义关系。", "散步": "散步是慢慢走路，与收获没有反义关系。", "翻译": "翻译是把一种语言转成另一种语言，与收获没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a329c5ea-d5a1-4cba-aeea-314414166c15') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21338, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "播种", "is_correct": true, "explanation": "播种是撒下种子，与收获（把成熟的果实取下来）相对。"}, {"text": "修理", "is_correct": false, "explanation": "修理是把坏的东西弄好，与收获没有反义关系。"}, {"text": "思考", "is_correct": false, "explanation": "思考是用脑子想问题，与收获没有反义关系。"}, {"text": "眺望", "is_correct": false, "explanation": "眺望是远远地看，与收获没有反义关系。"}], "correct_answer": "播种", "explanations": {"播种": "播种是撒下种子，与收获（把成熟的果实取下来）相对。", "修理": "修理是把坏的东西弄好，与收获没有反义关系。", "思考": "思考是用脑子想问题，与收获没有反义关系。", "眺望": "眺望是远远地看，与收获没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a329c5ea-d5a1-4cba-aeea-314414166c15') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21338, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把成熟的东西从田里或者树上拿下来。", "primary_collocate": null, "pronunciation": "shōu huò", "ipa": "ʂou˥ xuo˥˩", "syllable_count": 2, "sentences": [{"text": "农民在秋天收获稻子。", "target_word": "收获", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块地的小麦还没熟，不能收获。", "target_word": "收获", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们一早就到果园收获苹果。", "target_word": "收获", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天到了，爸爸在地里收获西红柿。", "target_word": "收获", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨以前，大家把麦子都收获完了。", "target_word": "收获", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山上的茶树春天可以收获新茶。", "target_word": "收获", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这片葡萄熟了，工人正在收获。", "target_word": "收获", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶在院子里收获了一篮豆子。", "target_word": "收获", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "十月是收获大豆的好时候。", "target_word": "收获", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们用机器收获棉花，又快又好。", "target_word": "收获", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "收获了", "label": "体标"}, {"form": "收获过", "label": "体标"}, {"form": "收获季节", "label": "复合"}, {"form": "收穫", "label": "繁体"}], "register": "中性", "sense_fingerprint": "动词：把成熟的庄稼、水果从田里或树上取下来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc8a5f9d-92ef-4665-a680-e80b55a2bde9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21338, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "收获", "is_correct": true, "explanation": "词条本身，读作 shōu huò。"}, {"text": "售货", "is_correct": false, "explanation": "第一个音节声调不同：shòu 为第四声，shōu 为第一声；意思是卖货。"}, {"text": "搜获", "is_correct": false, "explanation": "第一个音节声母不同：s 与 sh；意思是搜查后得到。"}, {"text": "首获", "is_correct": false, "explanation": "第一个音节声调不同：shǒu 为第三声，shōu 为第一声；意思是第一次获得，多用于比赛。"}], "explanations": {"收获": "词条本身，读作 shōu huò。", "售货": "第一个音节声调不同：shòu 为第四声，shōu 为第一声；意思是卖货。", "搜获": "第一个音节声母不同：s 与 sh；意思是搜查后得到。", "首获": "第一个音节声调不同：shǒu 为第三声，shōu 为第一声；意思是第一次获得，多用于比赛。"}, "sentence_index": null, "correct_answer": "收获"}, "level_3": {"options": [{"text": "收获", "is_correct": true, "explanation": "正确。此处指把成熟的稻子从田里割下来。"}, {"text": "烘焙", "is_correct": false, "explanation": "语义：烘焙指烘烤面点，与农民在秋天的田间农事无关。"}, {"text": "饲养", "is_correct": false, "explanation": "搭配：饲养的对象是动物，稻子不能饲养。"}, {"text": "熨烫", "is_correct": false, "explanation": "搭配：熨烫用于衣物，稻子不能熨烫。"}], "explanations": {"收获": "正确。此处指把成熟的稻子从田里割下来。", "烘焙": "语义：烘焙指烘烤面点，与农民在秋天的田间农事无关。", "饲养": "搭配：饲养的对象是动物，稻子不能饲养。", "熨烫": "搭配：熨烫用于衣物，稻子不能熨烫。"}, "sentence_index": 0, "correct_answer": "收获"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在工厂里收获了一台机器。", "explanation": "这里应该用〈制造〉。这里的“收获”指从田地或树上取下成熟的东西，机器是制造出来的，不能说收获。"}, {"text": "妈妈在超市收获了两斤西红柿。", "explanation": "这里应该用〈买〉。超市里的西红柿是买来的，收获指从田地或果树上取下果实。"}, {"text": "学校每学期收获一座教学楼。", "explanation": "这里应该用〈盖〉。这里的“收获”指从田地或树上取下成熟的东西，教学楼是盖起来的，不能说收获。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a329c5ea-d5a1-4cba-aeea-314414166c15') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21338, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "收获", "is_correct": true, "explanation": "正确。葡萄成熟后，工人把它们从架上摘下来。"}, {"text": "生长", "is_correct": false, "explanation": "语义：生长是植物发育，工人不会生长，且葡萄已经熟了，与语境矛盾。"}, {"text": "发芽", "is_correct": false, "explanation": "搭配：发芽指种子或植物萌发，与已经成熟的葡萄矛盾。"}, {"text": "演奏", "is_correct": false, "explanation": "搭配：演奏是表演乐曲，葡萄熟了不能用演奏。"}], "explanations": {"收获": "正确。葡萄成熟后，工人把它们从架上摘下来。", "生长": "语义：生长是植物发育，工人不会生长，且葡萄已经熟了，与语境矛盾。", "发芽": "搭配：发芽指种子或植物萌发，与已经成熟的葡萄矛盾。", "演奏": "搭配：演奏是表演乐曲，葡萄熟了不能用演奏。"}, "sentence_index": 6, "correct_answer": "收获"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在厨房里收获了一锅饭。", "explanation": "这里应该用〈做〉。收获只用于从田地或树上取下成熟的东西，饭是做出来的，不能说收获。"}, {"text": "他在花园里收获了一把椅子。", "explanation": "这里应该用〈放〉。收获只指从田地或树上取下成熟的果实，椅子是摆放的，不能说收获。"}, {"text": "工人在车间里收获了一批零件。", "explanation": "这里应该用〈加工〉。收获只指从田地或树上取下成熟的东西，零件要加工，不能说收获。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a329c5ea-d5a1-4cba-aeea-314414166c15') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21338, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "姐姐昨天在果园里收获的很多苹果。", "corrected_sentence": "姐姐昨天在果园里收获了很多苹果。", "error_description": "“的”误用：加上“的”后，句子变成名词短语，没有谓语；应用“了”表示完成，说“收获了很多苹果”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a329c5ea-d5a1-4cba-aeea-314414166c15') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21338, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "邻居昨天在田里收获一大片小麦。", "corrected_sentence": "邻居昨天在田里收获了一大片小麦。", "error_description": "“收获”后缺少“了”。昨天已经完成的收获要用“了”表示完成，应说“收获了一大片小麦”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a329c5ea-d5a1-4cba-aeea-314414166c15') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
