INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21344, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "function", "definition": "表示事情做完了或变成了别的样子。", "primary_collocate": null, "pronunciation": "chéng", "ipa": "ʈʂʰɤŋ˧˥", "syllable_count": 1, "sentences": [{"text": "请把这张纸剪成两半。", "target_word": "成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把蛋糕切成了六块。", "target_word": "成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子把月亮画成了方的。", "target_word": "成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他终于把这件事办成了。", "target_word": "成", "complexity_tier": "T3", "furigana": "tā zhōngyú bǎ zhè jiàn shì bàn chéng le", "sentence_source": "generated"}, {"text": "冬天到了，河水变成了冰。", "target_word": "成", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们把教室布置成了花园。", "target_word": "成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把长句子改成了短句子。", "target_word": "成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个计划终于办成了。", "target_word": "成", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把大米磨成了粉。", "target_word": "成", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨下了一夜，路都变成了小河。", "target_word": "成", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "成了", "label": "体标"}, {"form": "变成", "label": "复合"}, {"form": "做成", "label": "复合"}], "register": "中性", "sense_fingerprint": "放在动词后，表示做成或变成另一种样子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0b7c2170-8037-4fb9-be28-1859d5540cd4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21344, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "成", "is_correct": true, "explanation": "成（chéng）是目标词，放在动词后表示做成或变成另一种样子。"}, {"text": "长", "is_correct": false, "explanation": "cháng（第二声）与 chéng 韵母不同（ang/eng），意思是长短、长大。"}, {"text": "层", "is_correct": false, "explanation": "céng 与 chéng 声母不同（c/ch），意思是层次、楼层。"}, {"text": "撑", "is_correct": false, "explanation": "chēng（第一声）与 chéng（第二声）声调不同，意思是支撑。"}, {"text": "沉", "is_correct": false, "explanation": "chén（第二声）与 chéng 韵母不同（n/ng），意思是沉没。"}], "explanations": {"成": "成（chéng）是目标词，放在动词后表示做成或变成另一种样子。", "长": "cháng（第二声）与 chéng 韵母不同（ang/eng），意思是长短、长大。", "层": "céng 与 chéng 声母不同（c/ch），意思是层次、楼层。", "撑": "chēng（第一声）与 chéng（第二声）声调不同，意思是支撑。", "沉": "chén（第二声）与 chéng 韵母不同（n/ng），意思是沉没。"}, "sentence_index": null, "correct_answer": "成"}, "level_3": {"options": [{"text": "成", "is_correct": true, "explanation": "成：“剪成两半”表示剪开后变成两半，符合语境。"}, {"text": "断", "is_correct": false, "explanation": "搭配：“剪断”指切断、剪断开，不能说“剪断两半”。"}, {"text": "碎", "is_correct": false, "explanation": "语义：“碎”表示弄成细小的碎片，不是分成两半。"}, {"text": "裂", "is_correct": false, "explanation": "配价：“裂”是不及物动词，不能用来表示“剪”的结果。"}], "explanations": {"成": "成：“剪成两半”表示剪开后变成两半，符合语境。", "断": "搭配：“剪断”指切断、剪断开，不能说“剪断两半”。", "碎": "语义：“碎”表示弄成细小的碎片，不是分成两半。", "裂": "配价：“裂”是不及物动词，不能用来表示“剪”的结果。"}, "sentence_index": 0, "correct_answer": "成"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他终于把这件事成了。", "explanation": "这里应该用〈完成〉。“成”不能单独放在“把”字后作谓语，表示做完事情要说“完成”。"}, {"text": "他把米成了粥。", "explanation": "这里应该用〈煮成〉。“成”作结果补语要紧跟动词，不能直接接在“把”字结构后面。"}, {"text": "他把小说成了电影。", "explanation": "缺少动词：“成”作结果补语须紧跟动词，应为“把小说改编成了电影”，句中少了动词。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b391b74d-4f42-4d48-a002-89ac6119d04f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21344, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "成", "is_correct": true, "explanation": "成（chéng）是目标词，放在动词后表示做成或变成另一种样子。"}, {"text": "虫", "is_correct": false, "explanation": "chóng（第二声）与 chéng 韵母不同（o/e），意思是昆虫。"}, {"text": "称", "is_correct": false, "explanation": "chēng（第一声）与 chéng 声调不同，意思是称重。"}, {"text": "曾", "is_correct": false, "explanation": "céng 与 chéng 声母不同（c/ch），意思是曾经。"}, {"text": "陈", "is_correct": false, "explanation": "chén（第二声）与 chéng 韵母不同（n/ng），意思是陈旧。"}], "explanations": {"成": "成（chéng）是目标词，放在动词后表示做成或变成另一种样子。", "虫": "chóng（第二声）与 chéng 韵母不同（o/e），意思是昆虫。", "称": "chēng（第一声）与 chéng 声调不同，意思是称重。", "曾": "céng 与 chéng 声母不同（c/ch），意思是曾经。", "陈": "chén（第二声）与 chéng 韵母不同（n/ng），意思是陈旧。"}, "sentence_index": null, "correct_answer": "成"}, "level_3": {"options": [{"text": "成", "is_correct": true, "explanation": "成：“改成”表示改动后变成另一种形式，符合语境。"}, {"text": "织", "is_correct": false, "explanation": "语义：“织”指用线、布等编结，句子不能被编织，句意不通。"}, {"text": "掉", "is_correct": false, "explanation": "搭配：“改掉”表示去除缺点或习惯，不能用于句子的改写。"}, {"text": "坏", "is_correct": false, "explanation": "语义：“改坏”表示改得不好、弄坏了，与“改成短句子”的意思不符。"}], "explanations": {"成": "成：“改成”表示改动后变成另一种形式，符合语境。", "织": "语义：“织”指用线、布等编结，句子不能被编织，句意不通。", "掉": "搭配：“改掉”表示去除缺点或习惯，不能用于句子的改写。", "坏": "语义：“改坏”表示改得不好、弄坏了，与“改成短句子”的意思不符。"}, "sentence_index": 6, "correct_answer": "成"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他大学毕业后成了一名老师。", "explanation": "这里的“成”是动词“成为”，单独作谓语，不是结果补语，不接在动词后表示变成的样子。"}, {"text": "工资涨了一成。", "explanation": "这里的“成”表示十分之一，是数量用法，与“变成另一种样子”无关。"}, {"text": "这个计划终于成了。", "explanation": "这里的“成”是动词“成功”，单独作谓语，不是结果补语的用法。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b391b74d-4f42-4d48-a002-89ac6119d04f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21344, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把木头劈了成两段。", "corrected_sentence": "他把木头劈成了两段。", "error_description": "错在“了”和“成”的顺序：应为“劈成了两段”，结果补语“成”紧跟动词，“了”放在“成”后。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b391b74d-4f42-4d48-a002-89ac6119d04f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21344, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把面粉成了面团。", "corrected_sentence": "他把面粉揉成了面团。", "error_description": "错误：结果补语“成”前面必须有动词，漏掉了动词“揉”；应为“他把面粉揉成了面团”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b391b74d-4f42-4d48-a002-89ac6119d04f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21348, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "卖出", "is_correct": true, "explanation": "正确。买进与卖出互为反义，一买一卖。"}, {"text": "保存", "is_correct": false, "explanation": "与买进无反义关系，保存指妥善存放东西。"}, {"text": "参观", "is_correct": false, "explanation": "与买进无反义关系，参观指去某处看看。"}, {"text": "休息", "is_correct": false, "explanation": "与买进无反义关系，休息指停止工作以恢复体力。"}], "correct_answer": "卖出", "explanations": {"卖出": "正确。买进与卖出互为反义，一买一卖。", "保存": "与买进无反义关系，保存指妥善存放东西。", "参观": "与买进无反义关系，参观指去某处看看。", "休息": "与买进无反义关系，休息指停止工作以恢复体力。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a329c5ea-d5a1-4cba-aeea-314414166c15') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21348, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "卖出", "is_correct": true, "explanation": "正确。买进与卖出互为反义，一买一卖。"}, {"text": "收藏", "is_correct": false, "explanation": "与买进无反义关系，收藏指把珍贵的东西保存起来。"}, {"text": "出发", "is_correct": false, "explanation": "与买进无反义关系，出发指离开某地前往别处。"}, {"text": "睡觉", "is_correct": false, "explanation": "与买进无反义关系，睡觉指入睡休息。"}], "correct_answer": "卖出", "explanations": {"卖出": "正确。买进与卖出互为反义，一买一卖。", "收藏": "与买进无反义关系，收藏指把珍贵的东西保存起来。", "出发": "与买进无反义关系，出发指离开某地前往别处。", "睡觉": "与买进无反义关系，睡觉指入睡休息。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a329c5ea-d5a1-4cba-aeea-314414166c15') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21348, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用钱把东西买过来。", "primary_collocate": null, "pronunciation": "mǎi jìn", "ipa": "mai˨˩˦ tɕin˥˩", "syllable_count": 2, "sentences": [{"text": "超市每天从农场买进新鲜牛奶。", "target_word": "买进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板买进了一百件新衣服。", "target_word": "买进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校买进了一批桌子和椅子。", "target_word": "买进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的公司从朋友那里买进了一辆旧车。", "target_word": "买进", "complexity_tier": "T3", "furigana": "tā de gōngsī cóng péngyou nàlǐ mǎi jìn le yí liàng jiù chē.", "sentence_source": "generated"}, {"text": "店里刚买进了一些水果，很新鲜。", "target_word": "买进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工厂买进原料，做成商品再卖出去。", "target_word": "买进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "饭店今天早上买进了二十斤鱼。", "target_word": "买进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "价钱合适，我们就多买进一些。", "target_word": "买进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们一次买进了三台电脑。", "target_word": "买进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书店从出版社买进了很多新书。", "target_word": "买进", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "买进了", "label": "体标"}, {"form": "买进过", "label": "体标"}, {"form": "買進", "label": "繁体"}], "register": "中性", "sense_fingerprint": "动词：花钱把东西买入、收进来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc8a5f9d-92ef-4665-a680-e80b55a2bde9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21348, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "买进", "is_correct": true, "explanation": "正确。mǎi jìn，指花钱把东西买过来。"}, {"text": "迈进", "is_correct": false, "explanation": "mài jìn（第四声）与 mǎi（第三声）声调不同，意思是向前迈步。"}, {"text": "埋进", "is_correct": false, "explanation": "mái jìn（第二声）与 mǎi（第三声）声调不同，意思是埋入。"}, {"text": "摆进", "is_correct": false, "explanation": "bǎi jìn 与 mǎi 声母不同（b 与 m），意思是摆放进去。"}], "explanations": {"买进": "正确。mǎi jìn，指花钱把东西买过来。", "迈进": "mài jìn（第四声）与 mǎi（第三声）声调不同，意思是向前迈步。", "埋进": "mái jìn（第二声）与 mǎi（第三声）声调不同，意思是埋入。", "摆进": "bǎi jìn 与 mǎi 声母不同（b 与 m），意思是摆放进去。"}, "sentence_index": null, "correct_answer": "买进"}, "level_3": {"options": [{"text": "买进", "is_correct": true, "explanation": "正确。与“从农场”的来源方向一致，指从农场买入牛奶。"}, {"text": "扔掉", "is_correct": false, "explanation": "语义：扔掉是丢弃，与超市每天进货、保证新鲜的意思相反。"}, {"text": "销毁", "is_correct": false, "explanation": "语义：销毁是彻底毁掉，与超市每天进货、出售的意思矛盾。"}, {"text": "生产", "is_correct": false, "explanation": "配价：超市不是牛奶的制造者，“生产”的主语应是制造者。"}], "explanations": {"买进": "正确。与“从农场”的来源方向一致，指从农场买入牛奶。", "扔掉": "语义：扔掉是丢弃，与超市每天进货、保证新鲜的意思相反。", "销毁": "语义：销毁是彻底毁掉，与超市每天进货、出售的意思矛盾。", "生产": "配价：超市不是牛奶的制造者，“生产”的主语应是制造者。"}, "sentence_index": 0, "correct_answer": "买进"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她深深地买进了一口气，然后开始唱歌。", "explanation": "这里应该用〈吸〉。“买进”表示用钱购买东西，不能用来指吸气。"}, {"text": "学校买进了一项新规定。", "explanation": "这里应该用〈制定〉。“买进”的对象是货物或资产，规定不能用钱买。"}, {"text": "他买进了一句承诺。", "explanation": "这里应该用〈许下〉。“买进”只用于有形的货物或资产，承诺不能买。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a329c5ea-d5a1-4cba-aeea-314414166c15') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21348, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "买进", "is_correct": true, "explanation": "正确。mǎi jìn，指花钱把东西买过来。"}, {"text": "卖劲", "is_correct": false, "explanation": "mài jìn（第四声）与 mǎi（第三声）声调不同，意思是使劲、卖力。"}, {"text": "卖尽", "is_correct": false, "explanation": "mài jìn 与 mǎi 声调不同，意思是全部卖光。"}, {"text": "摆尽", "is_correct": false, "explanation": "bǎi jìn 与 mǎi 声母不同（b 与 m），意思是全部摆出、用尽。"}], "explanations": {"买进": "正确。mǎi jìn，指花钱把东西买过来。", "卖劲": "mài jìn（第四声）与 mǎi（第三声）声调不同，意思是使劲、卖力。", "卖尽": "mài jìn 与 mǎi 声调不同，意思是全部卖光。", "摆尽": "bǎi jìn 与 mǎi 声母不同（b 与 m），意思是全部摆出、用尽。"}, "sentence_index": null, "correct_answer": "买进"}, "level_3": {"options": [{"text": "买进", "is_correct": true, "explanation": "正确。指饭店一早进货，与句意相符。"}, {"text": "养殖", "is_correct": false, "explanation": "语义：养殖是培育动物，饭店不是养殖的主体，句子说不通。"}, {"text": "送给", "is_correct": false, "explanation": "配价：“送给”需要接受者，句中没有接受者。"}, {"text": "参观", "is_correct": false, "explanation": "语义：参观的对象是地方或场所，不能用于鱼。"}], "explanations": {"买进": "正确。指饭店一早进货，与句意相符。", "养殖": "语义：养殖是培育动物，饭店不是养殖的主体，句子说不通。", "送给": "配价：“送给”需要接受者，句中没有接受者。", "参观": "语义：参观的对象是地方或场所，不能用于鱼。"}, "sentence_index": 6, "correct_answer": "买进"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "书店把这些书买进了书架。", "explanation": "这里应该用〈放〉。“买进”表示用钱购买，不表示把东西放进某处。"}, {"text": "书店买进了一场展览。", "explanation": "这里应该用〈举办〉。“买进”的对象是货物或资产，展览不能买。"}, {"text": "老板买进了一位顾客的信任。", "explanation": "这里应该用〈赢得〉。“买进”只用于有形的货物或资产，信任不能买。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a329c5ea-d5a1-4cba-aeea-314414166c15') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21348, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "学校上个月买进着五张课桌。", "corrected_sentence": "学校上个月买进了五张课桌。", "error_description": "错误在“买进”后的动态助词。上个月已经完成的购买应用“了”，“着”表示持续状态，不能用于已完成的事件，应说“买进了五张课桌”，不能说“买进着五张课桌”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a329c5ea-d5a1-4cba-aeea-314414166c15') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21348, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们昨天从批发商那里买进十箱饮料。", "corrected_sentence": "我们昨天从批发商那里买进了十箱饮料。", "error_description": "“买进”后缺少“了”。句子说昨天已经完成的购买，应说“买进了十箱饮料”，“了”紧跟“买进”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a329c5ea-d5a1-4cba-aeea-314414166c15') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
