INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21354, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "一个可以买咖啡、喝茶、吃点心的地方。", "primary_collocate": null, "pronunciation": "kā fēi guǎn", "ipa": "kʰa˥ fei˥ kwan˨˩˦", "syllable_count": 3, "sentences": [{"text": "那家咖啡馆在地铁站旁边。", "target_word": "咖啡馆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想去咖啡馆喝杯咖啡，吃块点心。", "target_word": "咖啡馆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "咖啡馆里很安静，适合写作业。", "target_word": "咖啡馆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友在咖啡馆门口等着我。", "target_word": "咖啡馆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条街上有三家咖啡馆。", "target_word": "咖啡馆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们在咖啡馆坐了一下午。", "target_word": "咖啡馆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天早上去咖啡馆买面包。", "target_word": "咖啡馆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新开的咖啡馆有很多年轻人。", "target_word": "咖啡馆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "咖啡馆的音乐很好听。", "target_word": "咖啡馆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她想在海边开一家咖啡馆。", "target_word": "咖啡馆", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "家", "label": "量词"}, {"form": "咖啡馆", "label": "基本形"}, {"form": "咖啡館", "label": "繁体"}], "register": "中性", "sense_fingerprint": "可以喝咖啡茶、吃点心的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc8a5f9d-92ef-4665-a680-e80b55a2bde9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21354, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "咖啡馆", "is_correct": true, "explanation": "咖啡馆是可以买咖啡、喝茶、吃点心的店，设在地铁站旁边很常见。"}, {"text": "沙漠", "is_correct": false, "explanation": "语义：沙漠在荒野，不会开在地铁站旁边，也不是店铺。"}, {"text": "养殖场", "is_correct": false, "explanation": "语义：养殖场需要远离居民区，不会建在地铁站旁边。"}, {"text": "监狱", "is_correct": false, "explanation": "语域：监狱是司法机构，用在这种日常描述中语气突兀，与“那家咖啡馆”的句意不符。"}], "explanations": {"咖啡馆": "咖啡馆是可以买咖啡、喝茶、吃点心的店，设在地铁站旁边很常见。", "沙漠": "语义：沙漠在荒野，不会开在地铁站旁边，也不是店铺。", "养殖场": "语义：养殖场需要远离居民区，不会建在地铁站旁边。", "监狱": "语域：监狱是司法机构，用在这种日常描述中语气突兀，与“那家咖啡馆”的句意不符。"}, "sentence_index": 0, "correct_answer": "咖啡馆"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我常去那只咖啡馆看书。", "explanation": "这里应该用〈家〉。咖啡馆是店铺，量词用“家”，不用“只”。"}, {"text": "我去咖啡馆给车加了油。", "explanation": "这里应该用〈加油站〉。咖啡馆不提供加油服务，给车加油要去加油站。"}, {"text": "晚上我们在咖啡馆吃了一顿火锅。", "explanation": "这里应该用〈餐厅〉。咖啡馆只提供咖啡、茶和点心，吃火锅要去餐厅。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a329c5ea-d5a1-4cba-aeea-314414166c15') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21354, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "咖啡馆", "is_correct": true, "explanation": "咖啡馆可以买咖啡、喝茶、吃点心，“买面包”在这里合理。"}, {"text": "银行", "is_correct": false, "explanation": "搭配：“买面包”要去卖面包的店，银行不卖面包。"}, {"text": "图书馆", "is_correct": false, "explanation": "语义：图书馆不卖面包，不能在那里买面包。"}, {"text": "药店", "is_correct": false, "explanation": "语义：药店卖药品，不卖面包。"}], "explanations": {"咖啡馆": "咖啡馆可以买咖啡、喝茶、吃点心，“买面包”在这里合理。", "银行": "搭配：“买面包”要去卖面包的店，银行不卖面包。", "图书馆": "语义：图书馆不卖面包，不能在那里买面包。", "药店": "语义：药店卖药品，不卖面包。"}, "sentence_index": 6, "correct_answer": "咖啡馆"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们去咖啡馆理了个发。", "explanation": "这里应该用〈理发店〉。咖啡馆不提供理发，理发要去理发店。"}, {"text": "我去咖啡馆取了五百块钱。", "explanation": "这里应该用〈银行〉。咖啡馆不办理取款，取钱要去银行。"}, {"text": "妈妈去咖啡馆拿了感冒药。", "explanation": "这里应该用〈药店〉。咖啡馆不卖药，拿感冒药要去药店。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a329c5ea-d5a1-4cba-aeea-314414166c15') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21354, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他常咖啡馆见朋友。", "corrected_sentence": "他常在咖啡馆见朋友。", "error_description": "“咖啡馆”作地点时要用介词“在”引出，应说“在咖啡馆见朋友”，不能省去“在”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a329c5ea-d5a1-4cba-aeea-314414166c15') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21354, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们去一咖啡馆看看吧。", "corrected_sentence": "我们去一家咖啡馆看看吧。", "error_description": "“咖啡馆”前的数词“一”要带量词，应说“一家咖啡馆”，不能说“一咖啡馆”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a329c5ea-d5a1-4cba-aeea-314414166c15') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
