INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21360, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "卖东西的大房子，人们去那里买吃的和用的。", "primary_collocate": null, "pronunciation": "chāo shì", "ipa": "ʈʂʰaʊ˥ ʂɻ̩˥˩", "syllable_count": 2, "sentences": [{"text": "我每个星期六去超市买菜。", "target_word": "超市", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "超市里的水果很新鲜。", "target_word": "超市", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈在超市买了牛奶和面包。", "target_word": "超市", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家超市离我家很近。", "target_word": "超市", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "超市晚上十点才关门。", "target_word": "超市", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们家旁边新开了一家超市。", "target_word": "超市", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在超市工作，每天都很忙。", "target_word": "超市", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "超市里人太多，我们不想去了。", "target_word": "超市", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我把买好的东西从超市拿回了家。", "target_word": "超市", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "超市的东西比小店便宜一点。", "target_word": "超市", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一家超市", "label": "量词"}], "register": "中性", "sense_fingerprint": "名词，顾客自己拿东西再付钱的大商店，卖食品和日用品", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9ddbf6c1-65b5-4c28-9abb-1fe3d7a1f8f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21360, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "超市", "is_correct": true, "explanation": "正确。“超市”指顾客自选商品、付款的大型商店。"}, {"text": "超时", "is_correct": false, "explanation": "声调不同：shí（第二声）与 shì（第四声）不同，意思是超过时间。"}, {"text": "招式", "is_correct": false, "explanation": "声母不同：zhāo 与 chāo 的声母不同（zh 与 ch），意思是招数。"}, {"text": "朝市", "is_correct": false, "explanation": "声调不同：cháo（第二声）与 chāo（第一声）不同，意思是早市。"}], "explanations": {"超市": "正确。“超市”指顾客自选商品、付款的大型商店。", "超时": "声调不同：shí（第二声）与 shì（第四声）不同，意思是超过时间。", "招式": "声母不同：zhāo 与 chāo 的声母不同（zh 与 ch），意思是招数。", "朝市": "声调不同：cháo（第二声）与 chāo（第一声）不同，意思是早市。"}, "sentence_index": null, "correct_answer": "超市"}, "level_3": {"options": [{"text": "医院", "is_correct": false, "explanation": "语义：医院不卖菜，“买菜”的地点不能是医院。"}, {"text": "超市", "is_correct": true, "explanation": "正确。超市卖食品和蔬菜，符合“去……买菜”的语境。"}, {"text": "银行", "is_correct": false, "explanation": "语义：银行是办理存取款的地方，不卖菜。"}, {"text": "书店", "is_correct": false, "explanation": "搭配：书店卖的是书，不说在书店“买菜”。"}], "explanations": {"医院": "语义：医院不卖菜，“买菜”的地点不能是医院。", "超市": "正确。超市卖食品和蔬菜，符合“去……买菜”的语境。", "银行": "语义：银行是办理存取款的地方，不卖菜。", "书店": "搭配：书店卖的是书，不说在书店“买菜”。"}, "sentence_index": 0, "correct_answer": "超市"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我去超市看病。", "explanation": "这里应该用〈医院〉。超市是卖东西的地方，不能用来看病。"}, {"text": "我们去超市看电影。", "explanation": "这里应该用〈电影院〉。超市卖食品和日用品，不放映电影，“去超市看电影”不符合实际。"}, {"text": "我们坐超市去学校。", "explanation": "“坐”后面要接交通工具，超市不是交通工具。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d6c19ad-5bbb-4eee-a007-d6f320b39185') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21360, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "书包", "is_correct": false, "explanation": "语义：书包是装东西的袋子，不是工作的地方，“在书包工作”说不通。"}, {"text": "超市", "is_correct": true, "explanation": "正确。超市是工作场所，符合“他在……工作”的语境。"}, {"text": "花瓶", "is_correct": false, "explanation": "语义：花瓶是插花的器物，不是工作的地方，“在花瓶工作”说不通。"}, {"text": "窗户", "is_correct": false, "explanation": "搭配：窗户不是工作场所，不能用于“在……工作”。"}], "explanations": {"书包": "语义：书包是装东西的袋子，不是工作的地方，“在书包工作”说不通。", "超市": "正确。超市是工作场所，符合“他在……工作”的语境。", "花瓶": "语义：花瓶是插花的器物，不是工作的地方，“在花瓶工作”说不通。", "窗户": "搭配：窗户不是工作场所，不能用于“在……工作”。"}, "sentence_index": 6, "correct_answer": "超市"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我去超市剪头发。", "explanation": "这里应该用〈理发店〉。超市卖食品和日用品，不提供理发服务，“去超市剪头发”不符合实际。"}, {"text": "我们附近开了一只超市。", "explanation": "这里应该用〈家〉。超市的量词是“家”，“只”多用于动物。"}, {"text": "我借了超市一本书。", "explanation": "“借”的对象应是人，超市是场所，不能向它借书。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d6c19ad-5bbb-4eee-a007-d6f320b39185') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21360, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我朋友在街角开了一只超市。", "corrected_sentence": "我朋友在街角开了一家超市。", "error_description": "错误在量词“只”：超市的量词应用“家”，“只”多用于动物，不能用于商店。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d6c19ad-5bbb-4eee-a007-d6f320b39185') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21360, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他超市里买了两瓶酸奶。", "corrected_sentence": "他在超市里买了两瓶酸奶。", "error_description": "错误：“超市里买了”；正确：“在超市里买了”。表示动作发生的处所要用介词“在”引出，缺少“在”不通。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d6c19ad-5bbb-4eee-a007-d6f320b39185') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
