INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21362, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用钱买东西。", "primary_collocate": null, "pronunciation": "gòu mǎi", "ipa": "koʊ˥˩ maɪ˨˩˦", "syllable_count": 2, "sentences": [{"text": "他在网上购买了一台电脑。", "target_word": "购买", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请在这里购买火车票。", "target_word": "购买", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "顾客可以用现金购买。", "target_word": "购买", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想购买一辆新车。", "target_word": "购买", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她购买了很多水果。", "target_word": "购买", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你可以用手机购买电影票。", "target_word": "购买", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店不能购买药品。", "target_word": "购买", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "购买之前，他问了朋友的意见。", "target_word": "购买", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多人喜欢在节日购买礼物。", "target_word": "购买", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司决定购买新的机器。", "target_word": "购买", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "购买了", "label": "体标"}, {"form": "购买过", "label": "体标"}, {"form": "購買", "label": "繁体"}, {"form": "购买力", "label": "复合"}, {"form": "购买者", "label": "复合"}], "register": "书面", "sense_fingerprint": "花钱买下东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3365f9ac-881d-493f-88dc-1a13db791d52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21362, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "唱", "is_correct": false, "explanation": "搭配：“唱”后面不能跟“电脑”这样的物品，句子说不通。"}, {"text": "购买", "is_correct": true, "explanation": "购买：用钱买下东西，此处指在网上花钱买了一台电脑。"}, {"text": "游泳", "is_correct": false, "explanation": "配价：“游泳”是不及物动词，后面不能带“电脑”作宾语。"}, {"text": "吃", "is_correct": false, "explanation": "语义：电脑不是可以吃的东西，“吃”与“电脑”不搭。"}], "explanations": {"唱": "搭配：“唱”后面不能跟“电脑”这样的物品，句子说不通。", "购买": "购买：用钱买下东西，此处指在网上花钱买了一台电脑。", "游泳": "配价：“游泳”是不及物动词，后面不能带“电脑”作宾语。", "吃": "语义：电脑不是可以吃的东西，“吃”与“电脑”不搭。"}, "sentence_index": 0, "correct_answer": "购买"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每个星期都去图书馆购买书。", "explanation": "这里应该用〈借〉。“我”去图书馆是借阅书籍，不用付钱，不是购买；图书馆自己采购书籍才可以说购买。"}, {"text": "学生们在办公室购买了免费的课本。", "explanation": "这里应该用〈领取〉。课本是免费发放的，不用花钱，与“购买”矛盾。"}, {"text": "朋友免费购买了一台旧电脑送给我。", "explanation": "这里应该用〈赠送〉。“免费”与“购买”矛盾，购买要付钱；把东西送人要用赠送。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6b9e4da-c487-4ed1-b041-32c7a850e850') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21362, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "服用", "is_correct": false, "explanation": "语义：“服用”是病人吃药，店铺不会服用药品，句子说不通。"}, {"text": "购买", "is_correct": true, "explanation": "购买：用钱买下东西，此处指这家店不许买进药品。"}, {"text": "欣赏", "is_correct": false, "explanation": "搭配：“欣赏”的对象是风景、艺术，不跟“药品”搭配。"}, {"text": "咳嗽", "is_correct": false, "explanation": "配价：“咳嗽”是不及物动词，后面不能直接带“药品”作宾语。"}], "explanations": {"服用": "语义：“服用”是病人吃药，店铺不会服用药品，句子说不通。", "购买": "购买：用钱买下东西，此处指这家店不许买进药品。", "欣赏": "搭配：“欣赏”的对象是风景、艺术，不跟“药品”搭配。", "咳嗽": "配价：“咳嗽”是不及物动词，后面不能直接带“药品”作宾语。"}, "sentence_index": 6, "correct_answer": "购买"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家公司向小公司购买了一批旧机器，收到了一笔钱。", "explanation": "这里应该用〈出售〉。收到钱说明是卖出去，购买则是付钱买进，二者矛盾。"}, {"text": "他购买了这个木箱，是他亲手做的。", "explanation": "这里应该用〈制作〉。亲手做的东西不是买来的，“购买”与“是他亲手做的”矛盾。"}, {"text": "他向朋友购买了店铺，没有收钱。", "explanation": "这里应该用〈转让〉。句中说“没有收钱”，与购买要付钱矛盾；把店铺让给朋友要用转让。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6b9e4da-c487-4ed1-b041-32c7a850e850') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21362, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈在超市购买了过一箱牛奶。", "corrected_sentence": "妈妈在超市购买过一箱牛奶。", "error_description": "体标重复：“购买”后面只能用一个动态助词。“了”和“过”同时用在“购买”后面，应只保留“过”，说“购买过”，不能说“购买了过”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6b9e4da-c487-4ed1-b041-32c7a850e850') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21362, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他购买起这辆车。", "corrected_sentence": "他购买得起这辆车。", "error_description": "补语错误：表示能力的可能补语要用“得”，应说“购买得起”，去掉“得”就变成不合语法的“购买起”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6b9e4da-c487-4ed1-b041-32c7a850e850') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
