INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21370, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把东西卖给别人，换回钱。", "primary_collocate": null, "pronunciation": "xiāo shòu", "ipa": "ɕjɑʊ˥ ʂoʊ˥˩", "syllable_count": 2, "sentences": [{"text": "这家店专门销售旧书。", "target_word": "销售", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们公司销售电脑和手机。", "target_word": "销售", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种茶在国外也销售得很好。", "target_word": "销售", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天在网上销售水果。", "target_word": "销售", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "商店不能销售过期的牛奶。", "target_word": "销售", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些衣服只在春天销售。", "target_word": "销售", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们把新产品销售到了很多城市。", "target_word": "销售", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "超市里销售各种各样的零食。", "target_word": "销售", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在市场上销售自己做的面包。", "target_word": "销售", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家工厂的鞋子已经销售了一百双。", "target_word": "销售", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "销售", "label": "基本形"}, {"form": "销售了", "label": "体标（了）"}, {"form": "销售过", "label": "体标（过）"}, {"form": "銷售", "label": "繁体"}], "register": "书面", "sense_fingerprint": "把东西卖给别人换钱", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc8a5f9d-92ef-4665-a680-e80b55a2bde9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21370, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "销售", "is_correct": true, "explanation": "店铺专门卖旧书，“销售”指卖出商品换钱，与“专门”搭配。"}, {"text": "培育", "is_correct": false, "explanation": "语义：培育是培养动植物或人才，旧书不能被培育，句子说不通。"}, {"text": "讲解", "is_correct": false, "explanation": "语义：讲解的对象是内容或知识，不能讲解一批旧书。"}, {"text": "制作", "is_correct": false, "explanation": "语义：这家店经营的旧书是现成的，不是制作出来的。"}], "explanations": {"销售": "店铺专门卖旧书，“销售”指卖出商品换钱，与“专门”搭配。", "培育": "语义：培育是培养动植物或人才，旧书不能被培育，句子说不通。", "讲解": "语义：讲解的对象是内容或知识，不能讲解一批旧书。", "制作": "语义：这家店经营的旧书是现成的，不是制作出来的。"}, "sentence_index": 0, "correct_answer": "销售"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这些旧书免费销售给学生。", "explanation": "这里应该用〈赠送〉。“销售”要收钱换回钱，免费给人要说赠送。"}, {"text": "我们把设备销售给客户使用一个月。", "explanation": "这里应该用〈出租〉。“销售”是卖断，物品归买方；只让对方使用一段时间要说出租。"}, {"text": "他把过期的牛奶销售到了垃圾桶里。", "explanation": "这里应该用〈丢弃〉。“销售”要卖给人换钱，扔掉的东西要说丢弃。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a329c5ea-d5a1-4cba-aeea-314414166c15') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21370, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "销售", "is_correct": true, "explanation": "把新产品卖到很多城市，“销售”指卖出换钱，与“到了很多城市”搭配。"}, {"text": "研发", "is_correct": false, "explanation": "配价：“研发”不能带“到……城市”这样的去向宾语。"}, {"text": "发明", "is_correct": false, "explanation": "语义：发明的是新事物，不是把产品送到各地。"}, {"text": "撤回", "is_correct": false, "explanation": "语义：撤回是收回，与把新产品送往多个城市的方向相反。"}], "explanations": {"销售": "把新产品卖到很多城市，“销售”指卖出换钱，与“到了很多城市”搭配。", "研发": "配价：“研发”不能带“到……城市”这样的去向宾语。", "发明": "语义：发明的是新事物，不是把产品送到各地。", "撤回": "语义：撤回是收回，与把新产品送往多个城市的方向相反。"}, "sentence_index": 6, "correct_answer": "销售"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把自己的旧衣服销售给了灾区。", "explanation": "这里应该用〈捐赠〉。“销售”要收钱，捐给灾区不收钱要说捐赠。"}, {"text": "我把书销售给同学看了三天。", "explanation": "这里应该用〈借〉。“销售”是卖断，借给别人看一段时间要说“借”。"}, {"text": "他们用玩具销售了一本书。", "explanation": "这里应该用〈交换〉。“销售”要收钱，用物品换物品要说交换。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a329c5ea-d5a1-4cba-aeea-314414166c15') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21370, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们公司去年销售着一千台电脑。", "corrected_sentence": "我们公司去年销售了一千台电脑。", "error_description": "错误在“销售”后的动态助词。去年已经完成的销售应用“了”，“着”表示持续状态，不能用于已完成的事件，应说“销售了一千台电脑”，不能说“销售着一千台电脑”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a329c5ea-d5a1-4cba-aeea-314414166c15') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21370, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这款洗衣机销售地很好。", "corrected_sentence": "这款洗衣机销售得很好。", "error_description": "错误在补语的结构助词。“销售”后接程度补语，要用“得”，“地”只用于状语，应说“销售得很好”，不能说“销售地很好”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a329c5ea-d5a1-4cba-aeea-314414166c15') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21376, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "断开", "is_correct": true, "explanation": "正确：“断开”与“连接”意思相反，指使两个东西分离。"}, {"text": "保持", "is_correct": false, "explanation": "与“连接”没有反义关系，“保持”指维持原状。"}, {"text": "进入", "is_correct": false, "explanation": "与“连接”没有反义关系，“进入”指从外面到里面。"}, {"text": "观察", "is_correct": false, "explanation": "与“连接”没有反义关系，“观察”指仔细地看。"}], "correct_answer": "断开", "explanations": {"断开": "正确：“断开”与“连接”意思相反，指使两个东西分离。", "保持": "与“连接”没有反义关系，“保持”指维持原状。", "进入": "与“连接”没有反义关系，“进入”指从外面到里面。", "观察": "与“连接”没有反义关系，“观察”指仔细地看。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26accaa6-266c-48d1-a7a2-07e94e88f0e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21376, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "分离", "is_correct": true, "explanation": "正确：“分离”与“连接”意思相反，指使两个东西分开。"}, {"text": "修理", "is_correct": false, "explanation": "与“连接”没有反义关系，“修理”指修补使其恢复正常。"}, {"text": "支持", "is_correct": false, "explanation": "与“连接”没有反义关系，“支持”指给予帮助或撑持。"}, {"text": "参加", "is_correct": false, "explanation": "与“连接”没有反义关系，“参加”指加入某项活动。"}], "correct_answer": "分离", "explanations": {"分离": "正确：“分离”与“连接”意思相反，指使两个东西分开。", "修理": "与“连接”没有反义关系，“修理”指修补使其恢复正常。", "支持": "与“连接”没有反义关系，“支持”指给予帮助或撑持。", "参加": "与“连接”没有反义关系，“参加”指加入某项活动。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26accaa6-266c-48d1-a7a2-07e94e88f0e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21376, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "让两个东西合在一起。", "primary_collocate": null, "pronunciation": "lián jiē", "ipa": "ljɛn˧˥ tɕjɛ˥", "syllable_count": 2, "sentences": [{"text": "这座桥连接着两个城市。", "target_word": "连接", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把电脑和电视连接起来。", "target_word": "连接", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条路连接山上和山下。", "target_word": "连接", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我用手机连接了无线网。", "target_word": "连接", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条铁路连接北京和上海。", "target_word": "连接", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人用电线把两台机器连接好了。", "target_word": "连接", "complexity_tier": "T3", "furigana": "gōng rén yòng diàn xiàn bǎ liǎng tái jī qì lián jiē hǎo le.", "sentence_source": "generated"}, {"text": "网络把世界各地的人连接在一起。", "target_word": "连接", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个门连接着客厅和厨房。", "target_word": "连接", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你的手机连接上耳机了吗？", "target_word": "连接", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两条小河在这里连接，变成一条大河。", "target_word": "连接", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "连接了", "label": "体标"}, {"form": "连接着", "label": "体标"}, {"form": "連接", "label": "繁体"}], "register": "中性", "sense_fingerprint": "使两个事物接在一起或相通", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be5ee50c-f9af-43f9-b71d-60fc13a41298') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21376, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "参观", "is_correct": false, "explanation": "语义：桥不能“参观”城市，参观是人去看一个地方。"}, {"text": "打扫", "is_correct": false, "explanation": "搭配：“打扫”的对象一般是房间、地面，不说“打扫两个城市”。"}, {"text": "离开", "is_correct": false, "explanation": "语义：桥与城市是相连的，不是“离开”，“离开着两个城市”说不通。"}, {"text": "连接", "is_correct": true, "explanation": "正确：“连接着两个城市”说桥把两个城市接在一起，与语境相符。"}], "explanations": {"参观": "语义：桥不能“参观”城市，参观是人去看一个地方。", "打扫": "搭配：“打扫”的对象一般是房间、地面，不说“打扫两个城市”。", "离开": "语义：桥与城市是相连的，不是“离开”，“离开着两个城市”说不通。", "连接": "正确：“连接着两个城市”说桥把两个城市接在一起，与语境相符。"}, "sentence_index": 0, "correct_answer": "连接"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我和他是去年连接的。", "explanation": "这里应该用〈认识〉。“连接”指事物之间的接通，人与人初次相识要说“认识”。"}, {"text": "他一直连接我，想让我帮忙。", "explanation": "这里应该用〈找〉。“连接”指事物之间的接通，找人、与人取得联系不用“连接”。"}, {"text": "两家公司连接以后，成立了一个新公司。", "explanation": "这里应该用〈联合〉。“连接”指物体之间的接通，公司之间的合作要说“联合”或“合并”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26accaa6-266c-48d1-a7a2-07e94e88f0e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21376, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "分开", "is_correct": false, "explanation": "语义：“分开”与“在一起”意思相反，句子自相矛盾。"}, {"text": "拆散", "is_correct": false, "explanation": "语义：“拆散”指使分离，与“在一起”矛盾。"}, {"text": "隔开", "is_correct": false, "explanation": "搭配：“隔开”后面一般接处所或对象，与“在一起”搭配不当。"}, {"text": "连接", "is_correct": true, "explanation": "正确：“连接在一起”说把人联系起来，与“在一起”相符。"}], "explanations": {"分开": "语义：“分开”与“在一起”意思相反，句子自相矛盾。", "拆散": "语义：“拆散”指使分离，与“在一起”矛盾。", "隔开": "搭配：“隔开”后面一般接处所或对象，与“在一起”搭配不当。", "连接": "正确：“连接在一起”说把人联系起来，与“在一起”相符。"}, "sentence_index": 6, "correct_answer": "连接"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他们俩连接得很好，每天一起吃饭。", "explanation": "这里应该用〈相处〉。“连接”指事物之间的接通，人与人之间融洽地相处要说“相处”。"}, {"text": "这次考试我连接了三十分。", "explanation": "这里应该用〈得〉。考试分数是“得”来的，不说“连接”。"}, {"text": "他每天连接两个小时的书，成绩一直很好。", "explanation": "这里应该用〈读〉。“连接”不能和书搭配表示阅读，读书要说“读”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26accaa6-266c-48d1-a7a2-07e94e88f0e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21376, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "工人把两根水管连接下来了。", "corrected_sentence": "工人把两根水管连接起来了。", "error_description": "补语选错：“连接”后应接趋向补语“起来”，表示连在一起；“下来”不能与“连接”搭配，应说“连接起来了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26accaa6-266c-48d1-a7a2-07e94e88f0e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21376, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们明天连接了两台旧电脑。", "corrected_sentence": "他们明天连接两台旧电脑。", "error_description": "体标错误：“了”表示已经完成，不能用于“明天”这样的将来时间，应说“明天连接两台旧电脑”，去掉“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26accaa6-266c-48d1-a7a2-07e94e88f0e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
