INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21378, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "最开始在某个地方做出来或长出来。", "primary_collocate": null, "pronunciation": "yuán chǎn", "ipa": "ɥɛn˧˥ ʈʂʰan˨˩˦", "syllable_count": 2, "sentences": [{"text": "这种苹果原产于新疆。", "target_word": "原产", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种玉米原产于墨西哥。", "target_word": "原产", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "西瓜原产于非洲，夏天很受欢迎。", "target_word": "原产", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种辣椒原产于美洲，后来传到中国。", "target_word": "原产", "complexity_tier": "T3", "furigana": "Zhè zhǒng là jiāo yuán chǎn yú měi zhōu, hòu lái chuán dào zhōng guó.", "sentence_source": "generated"}, {"text": "茶最早原产于中国，后来传到世界各地。", "target_word": "原产", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种小麦原产于西亚，后来传遍世界。", "target_word": "原产", "complexity_tier": "T3", "furigana": "Zhè zhǒng xiǎo mài yuán chǎn yú xī yà, hòu lái chuán biàn shì jiè.", "sentence_source": "generated"}, {"text": "我家的盆花原产于云南。", "target_word": "原产", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种咖啡树原产于非洲。", "target_word": "原产", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，葡萄原产于西亚。", "target_word": "原产", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种山羊原产于中东地区。", "target_word": "原产", "complexity_tier": "T3", "furigana": "Zhè zhǒng shān yáng yuán chǎn yú zhōng dōng dì qū.", "sentence_source": "generated"}], "morphological_forms": [{"form": "原產", "label": "繁体"}], "register": "中性", "sense_fingerprint": "最开始在某个地方做出来或长出来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18eb6d63-0232-4cd9-8252-5118ed2ad4bb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21378, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "原产", "is_correct": true, "explanation": "原产：表示苹果最初出产的地方，与“于新疆”搭配，符合句意。"}, {"text": "出生", "is_correct": false, "explanation": "搭配：出生用于人或动物，苹果不能说出生于新疆。"}, {"text": "进口", "is_correct": false, "explanation": "语义：进口指从国外买入，新疆是国内地区，句子语义不通。"}, {"text": "寄居", "is_correct": false, "explanation": "语义：寄居指暂时借住，只用于人或动物，苹果不能寄居于某地。"}], "explanations": {"原产": "原产：表示苹果最初出产的地方，与“于新疆”搭配，符合句意。", "出生": "搭配：出生用于人或动物，苹果不能说出生于新疆。", "进口": "语义：进口指从国外买入，新疆是国内地区，句子语义不通。", "寄居": "语义：寄居指暂时借住，只用于人或动物，苹果不能寄居于某地。"}, "sentence_index": 0, "correct_answer": "原产"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "黄河原产于青海。", "explanation": "这里应该用〈发源〉。河流的源头要说“发源”，“原产”只用于物种或物产。"}, {"text": "这句诗原产于李白。", "explanation": "这里应该用〈出自〉。诗句的作者或出处要说“出自”，“原产”只用于物产的产地。"}, {"text": "这所学校原产于1949年。", "explanation": "这里应该用〈创办〉。学校、机构的建立要说“创办”，“原产”只用于物产。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b861901-a8a7-4920-a931-2ea8e81bdd82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21378, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "原产", "is_correct": true, "explanation": "原产：表示盆花最初出产的地方，与“于云南”搭配，符合句意。"}, {"text": "出口", "is_correct": false, "explanation": "语义：出口指运往国外，云南是国内省份，与句意不符。"}, {"text": "寄养", "is_correct": false, "explanation": "语义：寄养指托付他人照看，多用于宠物或孩子，盆花不能寄养于某地。"}, {"text": "旅居", "is_correct": false, "explanation": "搭配：旅居指人在异地长期居住，不用于盆花。"}], "explanations": {"原产": "原产：表示盆花最初出产的地方，与“于云南”搭配，符合句意。", "出口": "语义：出口指运往国外，云南是国内省份，与句意不符。", "寄养": "语义：寄养指托付他人照看，多用于宠物或孩子，盆花不能寄养于某地。", "旅居": "搭配：旅居指人在异地长期居住，不用于盆花。"}, "sentence_index": 6, "correct_answer": "原产"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他原产于农民家庭。", "explanation": "这里应该用〈出身〉。人的家庭背景要说“出身”，“原产”只用于物产。"}, {"text": "这场争论原产于一个误会。", "explanation": "这里应该用〈产生〉。事情、矛盾的起因要说“产生于”，“原产”只用于物种或物产。"}, {"text": "这个说法原产于古代。", "explanation": "这里应该用〈源自〉。说法、思想的来源要说“源自”，“原产”只用于物产。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b861901-a8a7-4920-a931-2ea8e81bdd82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21378, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这种橡胶树原产地于巴西。", "corrected_sentence": "这种橡胶树原产于巴西。", "error_description": "错误形式：“原产地于”；正确形式：“原产于”。“原产地”是名词，表示产地，不能直接接介词“于”引出地点。应说“原产于巴西”，或说“产地是巴西”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b861901-a8a7-4920-a931-2ea8e81bdd82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21378, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这种咖啡豆原产到埃塞俄比亚。", "corrected_sentence": "这种咖啡豆原产于埃塞俄比亚。", "error_description": "错误形式：“原产到”；正确形式：“原产于”。“原产”后面引出出产地要用介词“于”，“到”表示到达，不能用来表示出处。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b861901-a8a7-4920-a931-2ea8e81bdd82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
