INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21380, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51b02fcb-c6ae-4f20-8356-50f5f4438809') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21380, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "你需要的东西。", "primary_collocate": null, "pronunciation": "xū qiú", "ipa": "ɕy˥˥ tɕʰjoʊ˧˥", "syllable_count": 2, "sentences": [{"text": "每个孩子的需求都不一样，爸妈要多听听。", "target_word": "需求", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "客人有什么需求，可以直接告诉服务员。", "target_word": "需求", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的需求很简单，有吃有住就行。", "target_word": "需求", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买手机以前，先想想自己的需求。", "target_word": "需求", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不好意思说出自己的需求。", "target_word": "需求", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个房间太小，不能满足我的需求。", "target_word": "需求", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板很快就明白了客人的需求。", "target_word": "需求", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你把你的需求写在这张纸上。", "target_word": "需求", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的需求不多，一本书一杯茶就够了。", "target_word": "需求", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每个人的生活需求，都应该得到关心。", "target_word": "需求", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "种", "label": "量词"}, {"form": "生活需求", "label": "复合"}], "register": "中性", "sense_fingerprint": "个人或客人所需要的具体东西或要求", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a949716a-af53-4c71-8fd0-9a695ad86cc0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21380, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "身高", "is_correct": false, "explanation": "体貌：身高是孩子的体征，不是可以“多听听”的东西，句子说不通。"}, {"text": "需求", "is_correct": true, "explanation": "正确：“每个孩子的需求都不一样”指每个孩子想要的东西不同，“爸妈要多听听”与之搭配，合理。"}, {"text": "门票", "is_correct": false, "explanation": "语义：门票是凭证，不是孩子想要的东西，“爸妈要多听听门票”没有意义。"}, {"text": "车票", "is_correct": false, "explanation": "语义：车票是乘车的凭证，不能被“多听听”，与“不一样”也不构成合理的说法。"}], "explanations": {"身高": "体貌：身高是孩子的体征，不是可以“多听听”的东西，句子说不通。", "需求": "正确：“每个孩子的需求都不一样”指每个孩子想要的东西不同，“爸妈要多听听”与之搭配，合理。", "门票": "语义：门票是凭证，不是孩子想要的东西，“爸妈要多听听门票”没有意义。", "车票": "语义：车票是乘车的凭证，不能被“多听听”，与“不一样”也不构成合理的说法。"}, "sentence_index": 0, "correct_answer": "需求"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的需求是环游世界。", "explanation": "这里应该用〈愿望〉。“愿望”指希望实现的心愿，“需求”指必要的东西，不能用来表示理想或心愿。"}, {"text": "我的需求是当一名老师。", "explanation": "这里应该用〈理想〉。“理想”指心中向往的目标，“需求”指自己必要的东西，不能用来表示职业理想。"}, {"text": "他有一张需求，想请大家帮忙。", "explanation": "这里应该用“种”或“个”。“张”用于纸、桌子等扁平的东西，不能用来计量“需求”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51b02fcb-c6ae-4f20-8356-50f5f4438809') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21380, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "座位", "is_correct": false, "explanation": "搭配：“明白”多接想法、意思等，不说明白客人的座位。"}, {"text": "需求", "is_correct": true, "explanation": "正确：“明白了客人的需求”指弄清客人想要什么，搭配自然。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色不是可以“明白”的内容，“明白了客人的颜色”说不通。"}, {"text": "身份证", "is_correct": false, "explanation": "语义：身份证是证件，不能作为“明白”的对象，句子没有合理的意思。"}], "explanations": {"座位": "搭配：“明白”多接想法、意思等，不说明白客人的座位。", "需求": "正确：“明白了客人的需求”指弄清客人想要什么，搭配自然。", "颜色": "语义：颜色不是可以“明白”的内容，“明白了客人的颜色”说不通。", "身份证": "语义：身份证是证件，不能作为“明白”的对象，句子没有合理的意思。"}, "sentence_index": 6, "correct_answer": "需求"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我需求一本新字典。", "explanation": "这里应该用〈需要〉。“需求”是名词，不能直接带宾语；“需要”是动词，可以直接带宾语“一本新字典”。"}, {"text": "我对这次旅行充满需求。", "explanation": "这里应该用〈期待〉。“充满”搭配“期待”“希望”，不搭配“需求”；“需求”指必要的东西。"}, {"text": "我有一条需求，要先写下来。", "explanation": "这里应该用“种”或“个”。“条”用于长条形的东西，不能用来计量“需求”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51b02fcb-c6ae-4f20-8356-50f5f4438809') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21380, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他的一双需求只是想要一杯热茶。", "corrected_sentence": "他的需求只是想要一杯热茶。", "error_description": "错误在“一双需求”。“双”用于成对的东西，不能用来计量“需求”；这里不需要数量词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51b02fcb-c6ae-4f20-8356-50f5f4438809') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21380, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这位老人的一朵需求都很简单，有人陪着就好。", "corrected_sentence": "这位老人的需求都很简单，有人陪着就好。", "error_description": "错误在“一朵需求”。“朵”用于花朵等，不能用来计量抽象的“需求”；应去掉数量词，直接说“需求”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51b02fcb-c6ae-4f20-8356-50f5f4438809') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
