INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21384, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8bbf090c-9111-4bb0-969c-6e03428fbc33') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21384, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "心里觉得够了，开心了。", "primary_collocate": null, "pronunciation": "mǎn zú", "ipa": "man˨˩ tsu˧˥", "syllable_count": 2, "sentences": [{"text": "他对现在的生活很满足。", "target_word": "满足", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吃完这碗热面，我觉得很满足。", "target_word": "满足", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子吃完饭，满足地笑了。", "target_word": "满足", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他得到第一名，但还不满足。", "target_word": "满足", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一杯热茶就能让她满足。", "target_word": "满足", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗吃饱了，满足地睡着了。", "target_word": "满足", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你不要对一点成绩就满足。", "target_word": "满足", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸说，有家人在身边，他就很满足。", "target_word": "满足", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她从来不满足于现在的成绩，每天都练习。", "target_word": "满足", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看完这场电影，大家都觉得很满足。", "target_word": "满足", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "满足了", "label": "体标"}, {"form": "满足感", "label": "复合"}], "register": "中性", "sense_fingerprint": "心里觉得够了、感到满意和开心", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8b8dcf6e-820e-41d6-966b-7b4656bddf4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21384, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "满足", "is_correct": true, "explanation": "正确：“很满足”表示对现在的生活心里觉得够了，符合句意。"}, {"text": "快", "is_correct": false, "explanation": "搭配：“很快”一般用于速度、动作，不用来形容对生活的满意。"}, {"text": "陈旧", "is_correct": false, "explanation": "语义：陈旧指过时，与“现在的”生活相矛盾。"}, {"text": "矮", "is_correct": false, "explanation": "体貌：“矮”描述人或物的高度，不能用来形容生活。"}], "explanations": {"满足": "正确：“很满足”表示对现在的生活心里觉得够了，符合句意。", "快": "搭配：“很快”一般用于速度、动作，不用来形容对生活的满意。", "陈旧": "语义：陈旧指过时，与“现在的”生活相矛盾。", "矮": "体貌：“矮”描述人或物的高度，不能用来形容生活。"}, "sentence_index": 0, "correct_answer": "满足"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他很满足你的帮助。", "explanation": "这里应该用〈感激〉。满足表示心里觉得够了，表达对别人帮助的感谢要用感激，不能说“满足你的帮助”。"}, {"text": "老人满足常乐，很少抱怨。", "explanation": "这里应该用〈知足〉。“知足常乐”是固定说法，不能换成“满足常乐”。"}, {"text": "听到这个好消息，他满足得跳了起来。", "explanation": "这里应该用〈高兴〉。满足表示心里觉得够了，不能用来形容兴奋得跳起来。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8bbf090c-9111-4bb0-969c-6e03428fbc33') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21384, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "满足", "is_correct": true, "explanation": "正确：“就满足”表示只要有一点成绩就觉得够了，符合句意。"}, {"text": "放大", "is_correct": false, "explanation": "语义：放大指使东西变大，不能用来说对成绩的态度。"}, {"text": "打印", "is_correct": false, "explanation": "语义：“打印”指把文件印出来，与对成绩的态度无关，句意不通。"}, {"text": "运输", "is_correct": false, "explanation": "语义：“运输”指运送货物，与对成绩的态度无关，句意不通。"}], "explanations": {"满足": "正确：“就满足”表示只要有一点成绩就觉得够了，符合句意。", "放大": "语义：放大指使东西变大，不能用来说对成绩的态度。", "打印": "语义：“打印”指把文件印出来，与对成绩的态度无关，句意不通。", "运输": "语义：“运输”指运送货物，与对成绩的态度无关，句意不通。"}, "sentence_index": 6, "correct_answer": "满足"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个瓶子装了水，很快就满足了。", "explanation": "这里应该用〈装满〉。满足表示心里觉得够了，不能用来说容器被装满。"}, {"text": "他满足了这次比赛。", "explanation": "这里应该用〈放弃〉。满足表示心里觉得够了，表示不再参加比赛要用放弃，不能说“满足了这次比赛”。"}, {"text": "我满足了你的道歉。", "explanation": "这里应该用〈接受〉。满足表示心里觉得够了，表示同意对方的道歉要用接受。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8bbf090c-9111-4bb0-969c-6e03428fbc33') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21384, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈看着吃饱的孩子，满足笑了。", "corrected_sentence": "妈妈看着吃饱的孩子，满足地笑了。", "error_description": "状语错误：“满足”修饰后面的动词“笑”，要加“地”，应说“满足地笑了”，不说“满足笑了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8bbf090c-9111-4bb0-969c-6e03428fbc33') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21384, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他对这次旅行地满足。", "corrected_sentence": "他对这次旅行很满足。", "error_description": "结构助词错误：“地”只用于修饰后面的动词，这里“满足”作谓语，应用程度副词“很”，说“很满足”，不说“地满足”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8bbf090c-9111-4bb0-969c-6e03428fbc33') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
