INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21392, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "东西不一样，就是它们不是一样的。", "primary_collocate": null, "pronunciation": "bù tóng", "ipa": "pu˥˩ tʰʊŋ˧˥", "syllable_count": 2, "sentences": [{"text": "我和姐姐的看法不同。", "target_word": "不同", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这两个城市的天气不同。", "target_word": "不同", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "每个人的爱好都不同。", "target_word": "不同", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他们来自不同的国家。", "target_word": "不同", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这两本书的作者不同。", "target_word": "不同", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我们的想法不同，但我们是朋友。", "target_word": "不同", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "北方和南方的饭不同。", "target_word": "不同", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "不同的人有不同的习惯。", "target_word": "不同", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个词在两个句子里的意思不同。", "target_word": "不同", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的做法和别人不同。", "target_word": "不同", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "不同的", "label": "定语形式"}, {"form": "不同于", "label": "复合"}], "register": "中性", "sense_fingerprint": "形容词：几个事物彼此不一样", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ff2dc4db-9995-4fb8-b9e3-e98d425bf1f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21392, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "不同", "is_correct": true, "explanation": "不同：形容词，表示彼此不一样，与“看法”搭配，句子通顺。"}, {"text": "漂亮", "is_correct": false, "explanation": "搭配：“看法”不能用“漂亮”来形容，句子不通。"}, {"text": "矮", "is_correct": false, "explanation": "体貌：“矮”形容身高，不能形容看法。"}, {"text": "圆", "is_correct": false, "explanation": "语义：“圆”指形状，与“看法”不搭，句子不通。"}], "explanations": {"不同": "不同：形容词，表示彼此不一样，与“看法”搭配，句子通顺。", "漂亮": "搭配：“看法”不能用“漂亮”来形容，句子不通。", "矮": "体貌：“矮”形容身高，不能形容看法。", "圆": "语义：“圆”指形状，与“看法”不搭，句子不通。"}, "sentence_index": 0, "correct_answer": "不同"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我和弟弟的年龄不同两岁。", "explanation": "这里应该用〈相差〉。“不同”表示彼此不一样，说年龄或数量的差距要用“相差”，不能直接带数量词。"}, {"text": "两座城市的距离不同三百公里。", "explanation": "这里应该用〈相隔〉。“不同”不表示距离，两地之间的距离要说“相隔”。"}, {"text": "这次考试我的分数不同他两分。", "explanation": "这里应该用〈相差〉。说分数的差距要用“相差”，“不同”不能直接带数量词。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5bb3f5c4-42e4-4b4e-92d9-88bee7a69a8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21392, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "不同", "is_correct": true, "explanation": "不同：形容词，表示彼此不一样，与“饭”搭配，句子通顺。"}, {"text": "聪明", "is_correct": false, "explanation": "语义：“聪明”形容人的智力，不能用来形容饭。"}, {"text": "胖", "is_correct": false, "explanation": "体貌：“胖”形容人或动物的体形，不能形容饭。"}, {"text": "善良", "is_correct": false, "explanation": "语义：“善良”形容人的品性，与“饭”不搭，句子不通。"}], "explanations": {"不同": "不同：形容词，表示彼此不一样，与“饭”搭配，句子通顺。", "聪明": "语义：“聪明”形容人的智力，不能用来形容饭。", "胖": "体貌：“胖”形容人或动物的体形，不能形容饭。", "善良": "语义：“善良”形容人的品性，与“饭”不搭，句子不通。"}, "sentence_index": 6, "correct_answer": "不同"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们班的人数不同五个。", "explanation": "这里应该用〈相差〉。说数量的差距要用“相差”，“不同”表示性质或样子不一样。"}, {"text": "这个方案的成本不同十万元。", "explanation": "这里应该用〈相差〉。说金额的差距要用“相差”，“不同”不能直接带数量词。"}, {"text": "我们的成绩不同他三分。", "explanation": "这里应该用〈相差〉。说成绩的差距要用“相差”，不能说“不同”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5bb3f5c4-42e4-4b4e-92d9-88bee7a69a8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21392, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这两种方法的步骤不同的。", "corrected_sentence": "这两种方法的步骤不同。", "error_description": "“不同”作谓语时后面不加“的”。“的”用于修饰名词，应说“步骤不同”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5bb3f5c4-42e4-4b4e-92d9-88bee7a69a8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21392, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他的想法比我不同。", "corrected_sentence": "他的想法跟我不同。", "error_description": "“不同”与比较对象连用时，应使用“跟”或“和”，不能用“比”，应说“跟我不同”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5bb3f5c4-42e4-4b4e-92d9-88bee7a69a8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21394, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "特殊", "is_correct": true, "explanation": "“普通”与“特殊”是反义词：普通指不特别，特殊指与众不同。"}, {"text": "漂亮", "is_correct": false, "explanation": "“漂亮”形容外貌或事物好看，与“普通”没有反义关系。"}, {"text": "复杂", "is_correct": false, "explanation": "“复杂”指事情或结构繁多，与“普通”没有反义关系。"}, {"text": "聪明", "is_correct": false, "explanation": "“聪明”形容智力，与“普通”没有反义关系。"}], "correct_answer": "特殊", "explanations": {"特殊": "“普通”与“特殊”是反义词：普通指不特别，特殊指与众不同。", "漂亮": "“漂亮”形容外貌或事物好看，与“普通”没有反义关系。", "复杂": "“复杂”指事情或结构繁多，与“普通”没有反义关系。", "聪明": "“聪明”形容智力，与“普通”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26accaa6-266c-48d1-a7a2-07e94e88f0e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21394, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "特别", "is_correct": true, "explanation": "“普通”与“特别”是反义词：普通指不特别，特别指与一般不同。"}, {"text": "热情", "is_correct": false, "explanation": "“热情”形容态度或感情，与“普通”没有反义关系。"}, {"text": "柔软", "is_correct": false, "explanation": "“柔软”形容质地，与“普通”没有反义关系。"}, {"text": "清楚", "is_correct": false, "explanation": "“清楚”形容清晰明白，与“普通”没有反义关系。"}], "correct_answer": "特别", "explanations": {"特别": "“普通”与“特别”是反义词：普通指不特别，特别指与一般不同。", "热情": "“热情”形容态度或感情，与“普通”没有反义关系。", "柔软": "“柔软”形容质地，与“普通”没有反义关系。", "清楚": "“清楚”形容清晰明白，与“普通”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26accaa6-266c-48d1-a7a2-07e94e88f0e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21394, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "就是很常见的样子。", "primary_collocate": null, "pronunciation": "pǔ tōng", "ipa": "pʰu˨˩˦ tʰʊŋ˥", "syllable_count": 2, "sentences": [{"text": "他是一个普通的学生。", "target_word": "普通", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这只是一件很普通的衣服。", "target_word": "普通", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们都是普通的人。", "target_word": "普通", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家饭馆的菜很普通。", "target_word": "普通", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他住在一个普通的小房子里。", "target_word": "普通", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天只是普通的一天。", "target_word": "普通", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种水果很普通，每家商店都有。", "target_word": "普通", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的工作很普通，但是她很开心。", "target_word": "普通", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我只是想过普通的生活。", "target_word": "普通", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种情况太普通了，大家都见过。", "target_word": "普通", "complexity_tier": "T3", "furigana": "pǔ tōng", "sentence_source": "generated"}], "morphological_forms": [{"form": "普通人", "label": "复合"}, {"form": "普普通通", "label": "重叠"}], "register": "中性", "sense_fingerprint": "常见的、不特别的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be5ee50c-f9af-43f9-b71d-60fc13a41298') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21394, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "发达", "is_correct": false, "explanation": "搭配：“发达”多用于国家、经济，不能修饰学生。"}, {"text": "透明", "is_correct": false, "explanation": "语义：“透明”形容物体能被看穿，不能形容学生。"}, {"text": "普通", "is_correct": true, "explanation": "“普通”指常见、不特别，可以修饰“学生”，与句意相合。"}, {"text": "辣", "is_correct": false, "explanation": "语义：“辣”形容味道，不能用来形容人。"}], "explanations": {"发达": "搭配：“发达”多用于国家、经济，不能修饰学生。", "透明": "语义：“透明”形容物体能被看穿，不能形容学生。", "普通": "“普通”指常见、不特别，可以修饰“学生”，与句意相合。", "辣": "语义：“辣”形容味道，不能用来形容人。"}, "sentence_index": 0, "correct_answer": "普通"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次的成功非同普通。", "explanation": "这里应该用〈寻常〉。“非同寻常”是固定说法，表示超出一般，“普通”不能替换其中的“寻常”。"}, {"text": "这个小镇的人口很普通。", "explanation": "这里应该用〈多〉。“普通”形容质量或水平，不用来描述人口数量，说人口多要用“多”。"}, {"text": "他创造了一个普通的世界纪录。", "explanation": "这里应该用〈非凡〉。“普通”表示常见、不特别，与“世界纪录”的突出意义相矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26accaa6-266c-48d1-a7a2-07e94e88f0e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21394, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "稀少", "is_correct": false, "explanation": "语义：“稀少”说明数量少，与“每家商店都有”矛盾。"}, {"text": "普通", "is_correct": true, "explanation": "“普通”指常见，与“每家商店都有”相合。"}, {"text": "热闹", "is_correct": false, "explanation": "搭配：“热闹”形容场所或场面，不能形容水果。"}, {"text": "珍贵", "is_correct": false, "explanation": "语义：“珍贵”说明东西很宝贵，与“每家商店都有”矛盾。"}], "explanations": {"稀少": "语义：“稀少”说明数量少，与“每家商店都有”矛盾。", "普通": "“普通”指常见，与“每家商店都有”相合。", "热闹": "搭配：“热闹”形容场所或场面，不能形容水果。", "珍贵": "语义：“珍贵”说明东西很宝贵，与“每家商店都有”矛盾。"}, "sentence_index": 6, "correct_answer": "普通"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这是一个普通的奇迹。", "explanation": "这里应该用〈非凡〉。“普通”表示常见、不特别，与“奇迹”的罕见意义相矛盾。"}, {"text": "这是一件普通的大事。", "explanation": "这里应该用〈重要〉。“普通”表示常见、不特别，与事情的重要性相矛盾，应说“重要”。"}, {"text": "他的表演普通得让全场观众惊叹。", "explanation": "这里应该用〈精彩〉。“普通”表示平常、不出众，与“惊叹”的高度评价相矛盾，应说“精彩”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26accaa6-266c-48d1-a7a2-07e94e88f0e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21394, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他爸爸只是一个普通地工人。", "corrected_sentence": "他爸爸只是一个普通的工人。", "error_description": "结构助词错误：“普通”修饰名词“工人”时要用“的”，不能用“地”。“地”用于修饰动词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26accaa6-266c-48d1-a7a2-07e94e88f0e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21394, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家饭店的服务地普通。", "corrected_sentence": "这家饭店的服务很普通。", "error_description": "用词错误：作谓语的形容词前应加程度副词“很”，不能用状语助词“地”代替，应说“很普通”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26accaa6-266c-48d1-a7a2-07e94e88f0e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
