INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21398, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "别人对你做一件事，你心里有了感觉，这就是受到。", "primary_collocate": null, "pronunciation": "shòu dào", "ipa": "ʂou˥˩ tau˥˩", "syllable_count": 2, "sentences": [{"text": "小明做了好事，受到老师的表扬。", "target_word": "受到", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这只小狗受到全家人的喜爱。", "target_word": "受到", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他迟到了，受到了老师的批评。", "target_word": "受到", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我刚到北京时，受到很多邻居的帮助。", "target_word": "受到", "complexity_tier": "T3", "furigana": "wǒ gāng dào Běijīng shí shòudào hěn duō línjū de bāngzhù", "sentence_source": "generated"}, {"text": "小鸟受到惊吓，飞走了。", "target_word": "受到", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你的话让我受到很大的鼓励。", "target_word": "受到", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她听到这个消息后，受到了很大的打击。", "target_word": "受到", "complexity_tier": "T3", "furigana": "tā tīngdào zhège xiāoxi hòu shòudào le hěn dà de dǎjī", "sentence_source": "generated"}, {"text": "她受到过很多人的关心。", "target_word": "受到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "受到别人的夸奖，他很高兴。", "target_word": "受到", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他没考好，却受到了大家的安慰。", "target_word": "受到", "complexity_tier": "T3", "furigana": "tā méi kǎo hǎo, què shòudào le dàjiā de ānwèi", "sentence_source": "generated"}], "morphological_forms": [{"form": "受到了", "label": "完成体"}, {"form": "受到过", "label": "经历体"}], "register": "中性", "sense_fingerprint": "受到：承受别人给予的表扬、批评、影响、帮助等", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '048066ef-e0c6-43cd-971f-4df52a6c6dbb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21398, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "违反", "is_correct": false, "explanation": "搭配：“违反”的对象是规则或法律，不能与“表扬”搭配。"}, {"text": "处罚", "is_correct": false, "explanation": "语义：“处罚”与“做了好事”及“表扬”的语义相反。"}, {"text": "受到", "is_correct": true, "explanation": "正确：“受到”表示承受别人给予的表扬，与“做了好事”的语境相符。"}, {"text": "批评", "is_correct": false, "explanation": "搭配：“批评”的对象是人或行为，不能作“表扬”的宾语。"}], "explanations": {"违反": "搭配：“违反”的对象是规则或法律，不能与“表扬”搭配。", "处罚": "语义：“处罚”与“做了好事”及“表扬”的语义相反。", "受到": "正确：“受到”表示承受别人给予的表扬，与“做了好事”的语境相符。", "批评": "搭配：“批评”的对象是人或行为，不能作“表扬”的宾语。"}, "sentence_index": 0, "correct_answer": "受到"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我终于受到了这份工作。", "explanation": "这里应该用〈得到〉。受到用于表扬、批评、帮助等待遇，获得工作要用得到。"}, {"text": "他受到了一封妈妈寄来的信。", "explanation": "这里应该用〈收到〉。受到是承受别人给予的待遇，接到信件要用收到。"}, {"text": "我们受到了美好的假期。", "explanation": "这里应该用〈享受〉。受到指承受表扬、批评等，享受假期要用享受。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a81cd2d3-d40a-44eb-a4d6-0c714a342f1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21398, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "带来", "is_correct": false, "explanation": "语义：“带来”的施加者应是别人，此处“她”是听到消息的人，语义不符。"}, {"text": "受到", "is_correct": true, "explanation": "正确：“受到”表示承受打击，与“听到这个消息后”的语境相符。"}, {"text": "施加", "is_correct": false, "explanation": "语义：“施加”的主语应是施加者，此处“她”是承受者，语义不符。"}, {"text": "发出", "is_correct": false, "explanation": "搭配：“发出”搭配的是声音、信号，不能与“打击”搭配。"}], "explanations": {"带来": "语义：“带来”的施加者应是别人，此处“她”是听到消息的人，语义不符。", "受到": "正确：“受到”表示承受打击，与“听到这个消息后”的语境相符。", "施加": "语义：“施加”的主语应是施加者，此处“她”是承受者，语义不符。", "发出": "搭配：“发出”搭配的是声音、信号，不能与“打击”搭配。"}, "sentence_index": 6, "correct_answer": "受到"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我在路上受到了老朋友。", "explanation": "这里应该用〈遇到〉。受到是承受别人给予的待遇，在路上见到老朋友要用遇到。"}, {"text": "他终于受到了那张车票。", "explanation": "这里应该用〈买到〉。受到指承受别人的表扬、批评等，车票要用买到。"}, {"text": "我在抽屉里受到了丢失的钥匙。", "explanation": "这里应该用〈找到〉。受到指承受别人的影响，找回丢失的东西要用找到。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a81cd2d3-d40a-44eb-a4d6-0c714a342f1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21398, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次比赛后，他受到着很多朋友的祝贺。", "corrected_sentence": "这次比赛后，他受到了很多朋友的祝贺。", "error_description": "错误：“着”表示持续的状态，而“这次比赛后”指已经完成的事件，“受到”后应用“了”。正确说法是“这次比赛后，他受到了很多朋友的祝贺”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a81cd2d3-d40a-44eb-a4d6-0c714a342f1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21398, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他从来没有受到了这样的鼓励。", "corrected_sentence": "他从来没有受到过这样的鼓励。", "error_description": "错误：“没有”否定经历时，“受到”后应用“过”，不能用“了”。正确说法是“从来没有受到过这样的鼓励”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a81cd2d3-d40a-44eb-a4d6-0c714a342f1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21400, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "索取", "is_correct": true, "explanation": "索取：与“付出”相对，指向别人讨要或获取，与把东西给别人意思相反。"}, {"text": "讨论", "is_correct": false, "explanation": "讨论：与“付出”既无反义关系，也无近义关系，词义不相关。"}, {"text": "欢迎", "is_correct": false, "explanation": "欢迎：与“付出”既无反义关系，也无近义关系，词义不相关。"}, {"text": "相信", "is_correct": false, "explanation": "相信：与“付出”既无反义关系，也无近义关系，词义不相关。"}], "correct_answer": "索取", "explanations": {"索取": "索取：与“付出”相对，指向别人讨要或获取，与把东西给别人意思相反。", "讨论": "讨论：与“付出”既无反义关系，也无近义关系，词义不相关。", "欢迎": "欢迎：与“付出”既无反义关系，也无近义关系，词义不相关。", "相信": "相信：与“付出”既无反义关系，也无近义关系，词义不相关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c40d09f-a1a3-461a-bcd0-237c5ea4f0ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21400, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "索取", "is_correct": true, "explanation": "索取：与“付出”相对，指向别人讨要或获取，与把东西给别人意思相反。"}, {"text": "观察", "is_correct": false, "explanation": "观察：与“付出”既无反义关系，也无近义关系，词义不相关。"}, {"text": "生长", "is_correct": false, "explanation": "生长：与“付出”既无反义关系，也无近义关系，词义不相关。"}, {"text": "旅行", "is_correct": false, "explanation": "旅行：与“付出”既无反义关系，也无近义关系，词义不相关。"}], "correct_answer": "索取", "explanations": {"索取": "索取：与“付出”相对，指向别人讨要或获取，与把东西给别人意思相反。", "观察": "观察：与“付出”既无反义关系，也无近义关系，词义不相关。", "生长": "生长：与“付出”既无反义关系，也无近义关系，词义不相关。", "旅行": "旅行：与“付出”既无反义关系，也无近义关系，词义不相关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c40d09f-a1a3-461a-bcd0-237c5ea4f0ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21400, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把自己有的东西给别人。", "primary_collocate": null, "pronunciation": "fù chū", "ipa": "fu˥˩ ʈʂʰu˥", "syllable_count": 2, "sentences": [{"text": "母亲为孩子付出了一切。", "target_word": "付出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他对朋友总是真心付出。", "target_word": "付出", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她为家人付出了自己所有的爱。", "target_word": "付出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "好老师愿意为学生付出自己的时间。", "target_word": "付出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爱一个人，就要为她付出真心。", "target_word": "付出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爷爷为这个家付出了一辈子。", "target_word": "付出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他只想付出，不想从别人那里得到什么。", "target_word": "付出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "志愿者为陌生人付出自己的力量。", "target_word": "付出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她对他付出了全部的感情。", "target_word": "付出", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "朋友有困难时，他总是先付出，不谈回报。", "target_word": "付出", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "付出了", "label": "体标"}, {"form": "付出过", "label": "体标"}], "register": "中性", "sense_fingerprint": "付出|把自己拥有的东西给予别人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '14b46c7c-cf37-4c6d-b606-f814fed56f14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21400, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "付出", "is_correct": true, "explanation": "付出（fù chū）：正确答案，指把自己拥有的东西给别人。"}, {"text": "付诸", "is_correct": false, "explanation": "zhū 与 chū 声母不同（zh/ch），意思是付诸（付诸实践），不是付出。"}, {"text": "浮出", "is_correct": false, "explanation": "fú（第二声）与 fù（第四声）声调不同，意思是浮出（露出水面或显现出来）。"}, {"text": "步出", "is_correct": false, "explanation": "bù 与 fù 声母不同（b/f），意思是步出（走出某处）。"}, {"text": "副处", "is_correct": false, "explanation": "chù（第四声）与 chū（第一声）声调不同，意思是副处（副职的级别）。"}], "explanations": {"付出": "付出（fù chū）：正确答案，指把自己拥有的东西给别人。", "付诸": "zhū 与 chū 声母不同（zh/ch），意思是付诸（付诸实践），不是付出。", "浮出": "fú（第二声）与 fù（第四声）声调不同，意思是浮出（露出水面或显现出来）。", "步出": "bù 与 fù 声母不同（b/f），意思是步出（走出某处）。", "副处": "chù（第四声）与 chū（第一声）声调不同，意思是副处（副职的级别）。"}, "sentence_index": null, "correct_answer": "付出"}, "level_3": {"options": [{"text": "付出", "is_correct": true, "explanation": "付出：把爱和全部给予孩子，符合“母亲为孩子付出了一切”的语境。"}, {"text": "索取", "is_correct": false, "explanation": "语义：“索取”是向别人要东西，与“为孩子”的给予方向相反。"}, {"text": "拿走", "is_correct": false, "explanation": "语义：“拿走”是把东西带走，与“为孩子”的意图矛盾。"}, {"text": "挑选", "is_correct": false, "explanation": "搭配：“挑选”不能带“一切”这样的宾语，搭配不成立。"}], "explanations": {"付出": "付出：把爱和全部给予孩子，符合“母亲为孩子付出了一切”的语境。", "索取": "语义：“索取”是向别人要东西，与“为孩子”的给予方向相反。", "拿走": "语义：“拿走”是把东西带走，与“为孩子”的意图矛盾。", "挑选": "搭配：“挑选”不能带“一切”这样的宾语，搭配不成立。"}, "sentence_index": 0, "correct_answer": "付出"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在这道题上付出了一个严重的错误。", "explanation": "这里应该用〈犯〉。付出 指把自己有的东西给别人，“错误”不能拿来给人，说“犯错误”才自然。"}, {"text": "他付出了这份责任。", "explanation": "这里应该用〈承担〉。付出 指把自己有的东西给别人，“责任”要用〈承担〉，不能说“付出责任”。"}, {"text": "他付出了一个贫困的学生。", "explanation": "这里应该用〈资助〉。付出 的宾语是东西，不能说“付出了一个学生”，资助 可以直接带受助的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c40d09f-a1a3-461a-bcd0-237c5ea4f0ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21400, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "付出", "is_correct": true, "explanation": "付出：把自己的东西给别人，符合“他只想付出，不想从别人那里得到什么”的语境。"}, {"text": "攀比", "is_correct": false, "explanation": "语义：“攀比”是与人比较高低，不是给予别人，与“不想从别人那里得到什么”不相符。"}, {"text": "挥霍", "is_correct": false, "explanation": "语义：“挥霍”是浪费钱财，与句中“只想给予、不想获取”的意思不符。"}, {"text": "嫉妒", "is_correct": false, "explanation": "语义：“嫉妒”是因别人而不满，与句中“只想给予”的意愿矛盾。"}], "explanations": {"付出": "付出：把自己的东西给别人，符合“他只想付出，不想从别人那里得到什么”的语境。", "攀比": "语义：“攀比”是与人比较高低，不是给予别人，与“不想从别人那里得到什么”不相符。", "挥霍": "语义：“挥霍”是浪费钱财，与句中“只想给予、不想获取”的意思不符。", "嫉妒": "语义：“嫉妒”是因别人而不满，与句中“只想给予”的意愿矛盾。"}, "sentence_index": 6, "correct_answer": "付出"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她向我付出了一个问题。", "explanation": "这里应该用〈提出〉。付出 指把自己有的东西给别人，“问题”是要提出来的，不能说“付出一个问题”。"}, {"text": "她把一本书付出到桌子上。", "explanation": "这里应该用〈放〉。“付出”是把自己的东西给别人，不能表示把东西放到某处。"}, {"text": "他从书中付出了很多知识。", "explanation": "这里应该用〈获取〉。付出 指把自己的东西给出去，不能用来说“从书中得到知识”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c40d09f-a1a3-461a-bcd0-237c5ea4f0ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21400, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她把自己的爱都付出了孩子。", "corrected_sentence": "她把自己的爱都付出给了孩子。", "error_description": "错误：“付出了孩子”，“付出”把东西交给人时要用“给”引出接受者，漏掉“给”。正确应为“付出给了孩子”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c40d09f-a1a3-461a-bcd0-237c5ea4f0ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21400, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她对这个家庭付出了过很多爱。", "corrected_sentence": "她对这个家庭付出过很多爱。", "error_description": "错误：“付出了过”同时用了“了”和“过”。表示曾经有过的付出只用“付出过”，“了过”不能连用。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c40d09f-a1a3-461a-bcd0-237c5ea4f0ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
