INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21402, 1, 'prompt1_core', '{"pos": "情态动词", "semantic_class": "function", "definition": "心里想去做一件事，就说愿意。", "primary_collocate": null, "pronunciation": "yuàn yì", "ipa": "yɛn˥˩ i˥˩", "syllable_count": 2, "sentences": [{"text": "朋友有困难，我很愿意帮他。", "target_word": "愿意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不愿意一个人去医院。", "target_word": "愿意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你愿意和我一起去旅行吗？", "target_word": "愿意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈让他早点睡，他不愿意。", "target_word": "愿意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她愿意花时间照顾生病的朋友。", "target_word": "愿意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师问我们，谁愿意先唱歌？", "target_word": "愿意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他愿意把自己的书借给我。", "target_word": "愿意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你愿意跟我们一起住吗？", "target_word": "愿意", "complexity_tier": "T3", "furigana": "nǐ yuàn yì gēn wǒ men yì qǐ zhù ma?", "sentence_source": "generated"}, {"text": "小明不愿意吃青菜，只想吃肉。", "target_word": "愿意", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都愿意听她讲故事。", "target_word": "愿意", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "不愿意", "label": "否定形式"}, {"form": "愿不愿意", "label": "正反问形式"}], "register": "中性", "sense_fingerprint": "心里想做某事，表示自己同意、乐意去做", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77d97711-45c9-40d1-a540-071631f184cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21402, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "愿意", "is_correct": true, "explanation": "正确：“愿意”表示心里乐意去做，与“很”搭配，符合“我乐意帮他”的意思。"}, {"text": "敢", "is_correct": false, "explanation": "语义：“敢”表示有胆量，句子说的是乐意帮忙，不是胆量。"}, {"text": "应该", "is_correct": false, "explanation": "语义：“应该”表示义务、应当，句子强调的是心甘情愿，而不是义务。"}, {"text": "讨厌", "is_correct": false, "explanation": "语义：“讨厌”表示厌恶，与句中乐意帮忙的态度相反。"}], "explanations": {"愿意": "正确：“愿意”表示心里乐意去做，与“很”搭配，符合“我乐意帮他”的意思。", "敢": "语义：“敢”表示有胆量，句子说的是乐意帮忙，不是胆量。", "应该": "语义：“应该”表示义务、应当，句子强调的是心甘情愿，而不是义务。", "讨厌": "语义：“讨厌”表示厌恶，与句中乐意帮忙的态度相反。"}, "sentence_index": 0, "correct_answer": "愿意"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他被父母押着去补习班，心里非常愿意。", "explanation": "这里应该用〈不愿意〉。被强迫去做的事，心里是不乐意的，应说“不愿意”；“愿意”表示心里乐意去做，与“被押着”矛盾。"}, {"text": "我愿意这个办法很好。", "explanation": "这里应该用〈觉得〉。对事情好坏的判断用“觉得”，“愿意”只表示说话人乐意去做某事，不用于评价办法的好坏。"}, {"text": "他一想到考试就很愿意。", "explanation": "这里应该用〈害怕〉。一想到考试而产生的心情用“害怕”，“愿意”表示心里乐意去做某事，不表示害怕。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc650faf-eef1-4b87-8649-678eec955448') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21402, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "愿意", "is_correct": true, "explanation": "正确：句子说他自愿把书借出，“愿意”表示乐意去做，与“借给我”的语境相合。"}, {"text": "必须", "is_correct": false, "explanation": "语义：“必须”表示强制的义务，与句中出于自愿的意思不符。"}, {"text": "拒绝", "is_correct": false, "explanation": "语义：“拒绝”表示不答应，与句中乐意借书的态度相反。"}, {"text": "懒得", "is_correct": false, "explanation": "语义：“懒得”表示不想费力去做，与句中乐意借书的态度相反。"}], "explanations": {"愿意": "正确：句子说他自愿把书借出，“愿意”表示乐意去做，与“借给我”的语境相合。", "必须": "语义：“必须”表示强制的义务，与句中出于自愿的意思不符。", "拒绝": "语义：“拒绝”表示不答应，与句中乐意借书的态度相反。", "懒得": "语义：“懒得”表示不想费力去做，与句中乐意借书的态度相反。"}, "sentence_index": 6, "correct_answer": "愿意"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我愿意明天下雨。", "explanation": "这里应该用〈希望〉。盼望某件事发生用“希望”，“愿意”只表示说话人自己乐意去做某事，不用于盼望下雨。"}, {"text": "愿意你一路平安。", "explanation": "这里应该用〈祝〉。送别时表示祝福用“祝”，“愿意”表示说话人自己乐意去做某事，不表示祝愿。"}, {"text": "他问我要不要去，我很愿意地摇了摇头。", "explanation": "这里应该用〈不愿意〉。摇头表示拒绝，与“愿意”的乐意相矛盾，应说“不愿意”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc650faf-eef1-4b87-8649-678eec955448') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21402, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我没愿意陪你去医院。", "corrected_sentence": "我不愿意陪你去医院。", "error_description": "否定词错误：能愿动词「愿意」的否定要用「不」，「没」不能否定「愿意」，应说「不愿意」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc650faf-eef1-4b87-8649-678eec955448') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21402, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我没愿意去那么远的地方。", "corrected_sentence": "我不愿意去那么远的地方。", "error_description": "否定词错误：表示不乐意要用“不”，写成“没”不通顺，应改为“不愿意”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc650faf-eef1-4b87-8649-678eec955448') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
