INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21405, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "做事情需要花的钱。", "primary_collocate": null, "pronunciation": "fèi yòng", "ipa": "feɪ˥˩ jʊŋ˥˩", "syllable_count": 2, "sentences": [{"text": "搬家的费用由公司来出。", "target_word": "费用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "办一场婚礼的费用不少。", "target_word": "费用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个工作需要多少费用？", "target_word": "费用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "开会的费用我们已经算好了。", "target_word": "费用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把这次比赛的费用都算清楚了。", "target_word": "费用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做这个手术的费用很高。", "target_word": "费用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师说，参加活动的费用由学校来出。", "target_word": "费用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "装修新房的费用比我想的多。", "target_word": "费用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "为了省费用，我们自己做饭。", "target_word": "费用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "修这条路的费用要一千万元。", "target_word": "费用", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一笔费用", "label": "量词"}, {"form": "医疗费用", "label": "复合"}, {"form": "費用", "label": "繁体"}], "register": "中性", "sense_fingerprint": "做某件事（搬家、办婚礼、做手术）需要花的钱", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '14b46c7c-cf37-4c6d-b606-f814fed56f14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21405, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "费用", "is_correct": true, "explanation": "费用：搬家需要花的钱，由公司来出，符合句意。"}, {"text": "行李", "is_correct": false, "explanation": "搭配：“行李”不是可以“出”的钱款，“行李由公司来出”搭配不成立。"}, {"text": "时间", "is_correct": false, "explanation": "语义：“时间”不是钱，不能由公司来出，句意不通。"}, {"text": "地址", "is_correct": false, "explanation": "语义：“地址”不能由公司来出，与搬家的花费无关。"}], "explanations": {"费用": "费用：搬家需要花的钱，由公司来出，符合句意。", "行李": "搭配：“行李”不是可以“出”的钱款，“行李由公司来出”搭配不成立。", "时间": "语义：“时间”不是钱，不能由公司来出，句意不通。", "地址": "语义：“地址”不能由公司来出，与搬家的花费无关。"}, "sentence_index": 0, "correct_answer": "费用"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这台电脑的费用是五千元。", "explanation": "这里应该用〈价格〉。费用 指做某件事需要花的钱，买商品的标价要用〈价格〉。"}, {"text": "我们算好了一张费用。", "explanation": "这里的量词应该用〈笔〉。〈张〉用于纸、桌子等扁平物体，不能计量“费用”。"}, {"text": "他领到了一个月的费用。", "explanation": "这里应该用〈工资〉。费用 指为做事而花的钱，不是付给员工的月薪。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c40d09f-a1a3-461a-bcd0-237c5ea4f0ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21405, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "费用", "is_correct": true, "explanation": "费用：参加活动需要花的钱，由学校来出，符合句意。"}, {"text": "天气", "is_correct": false, "explanation": "语义：“天气”不是钱款，不能由学校来出，句意不通。"}, {"text": "海拔", "is_correct": false, "explanation": "语义：“海拔”与参加活动的花费无关，不能由学校来出。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“颜色”不能由学校来出，“颜色由学校来出”搭配不成立。"}], "explanations": {"费用": "费用：参加活动需要花的钱，由学校来出，符合句意。", "天气": "语义：“天气”不是钱款，不能由学校来出，句意不通。", "海拔": "语义：“海拔”与参加活动的花费无关，不能由学校来出。", "颜色": "搭配：“颜色”不能由学校来出，“颜色由学校来出”搭配不成立。"}, "sentence_index": 6, "correct_answer": "费用"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在抽奖中赢得了一笔费用。", "explanation": "这里应该用〈奖金〉。费用 指做事情需要花出去的钱，抽奖赢来的钱是奖金，不是费用。"}, {"text": "修这条路的一扇费用要一千万元。", "explanation": "这里的量词应该用〈笔〉。〈扇〉用于门窗，不能计量“费用”。"}, {"text": "修这条路的一颗费用要一千万元。", "explanation": "这里的量词应该用〈笔〉。〈颗〉用于粒状小东西，不能计量“费用”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c40d09f-a1a3-461a-bcd0-237c5ea4f0ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21405, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只费用已经算好了。", "corrected_sentence": "这笔费用已经算好了。", "error_description": "错误：“这只费用”，“只”不能计量“费用”。正确应为“这笔费用”，“笔”用于款项。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c40d09f-a1a3-461a-bcd0-237c5ea4f0ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21405, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这枚费用不算贵。", "corrected_sentence": "这笔费用不算贵。", "error_description": "错误：“这枚费用”，“枚”用于硬币、徽章等小物，不能计量“费用”。正确应为“这笔费用”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c40d09f-a1a3-461a-bcd0-237c5ea4f0ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
