INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21410, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "两个人或事物之间有关系。", "primary_collocate": null, "pronunciation": "lián xì", "ipa": "ljɛn˧˥ ɕi˥˩", "syllable_count": 2, "sentences": [{"text": "他和这件事没有联系。", "target_word": "联系", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这两个问题有联系。", "target_word": "联系", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我和他只是工作上的联系。", "target_word": "联系", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这两个国家之间的联系很重要。", "target_word": "联系", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这张图画出了两个城市的联系。", "target_word": "联系", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这两门学科之间的联系比我想的少。", "target_word": "联系", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "水和生命有很深的联系。", "target_word": "联系", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这两个地区的联系是从一条古老的商路开始的。", "target_word": "联系", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你觉得这两个词有联系吗？", "target_word": "联系", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个故事和我家有一点联系。", "target_word": "联系", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一种联系", "label": "量词"}, {"form": "联系方式", "label": "复合"}, {"form": "聯繫", "label": "繁体"}], "register": "中性", "sense_fingerprint": "两个人或事物之间存在的关系", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '14b46c7c-cf37-4c6d-b606-f814fed56f14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21410, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "联系", "is_correct": true, "explanation": "正确：目标词是联系（lián xì）。"}, {"text": "练习", "is_correct": false, "explanation": "lián（第二声）与 liàn（第四声）声调不同，意思是练习。"}, {"text": "连续", "is_correct": false, "explanation": "xì 与 xù 韵母不同，意思是连续。"}, {"text": "联席", "is_correct": false, "explanation": "xì（第四声）与 xí（第二声）声调不同，意思是联席（会议）。"}], "explanations": {"联系": "正确：目标词是联系（lián xì）。", "练习": "lián（第二声）与 liàn（第四声）声调不同，意思是练习。", "连续": "xì 与 xù 韵母不同，意思是连续。", "联席": "xì（第四声）与 xí（第二声）声调不同，意思是联席（会议）。"}, "sentence_index": null, "correct_answer": "联系"}, "level_3": {"options": [{"text": "联系", "is_correct": true, "explanation": "正确。“没有联系”指他与这件事之间没有关系。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：身高指人或动物的高矮，不能说“与这件事没有身高”。"}, {"text": "乐器", "is_correct": false, "explanation": "语义：“没有乐器”与这件事不搭，不是关系的意思。"}, {"text": "动物", "is_correct": false, "explanation": "语义：“没有动物”与这件事不搭，不是关系的意思。"}], "explanations": {"联系": "正确。“没有联系”指他与这件事之间没有关系。", "身高": "体貌：身高指人或动物的高矮，不能说“与这件事没有身高”。", "乐器": "语义：“没有乐器”与这件事不搭，不是关系的意思。", "动物": "语义：“没有动物”与这件事不搭，不是关系的意思。"}, "sentence_index": 0, "correct_answer": "联系"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这两段铁轨需要联系在一起。", "explanation": "这里应该用〈连接〉。两段铁轨的物理相接要用“连接”，“联系”指人或事物间的关系。"}, {"text": "我和他之间有一块联系。", "explanation": "这里应该用量词〈种〉。“块”用于块状的东西，联系是抽象的。"}, {"text": "这张椅子是一种联系。", "explanation": "这里把〈联系〉误用成了〈物品〉的意思；“联系”是两者之间的关系，椅子不能是联系。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c40d09f-a1a3-461a-bcd0-237c5ea4f0ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21410, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "联系", "is_correct": true, "explanation": "正确。水与生命之间有很深的关系，这里用“联系”。"}, {"text": "体重", "is_correct": false, "explanation": "体貌：体重说人或物的重量，不能说“很深的体重”。"}, {"text": "蔬菜", "is_correct": false, "explanation": "语义：蔬菜不是水与生命之间的关系。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：身材指人的体形，不能用来说水与生命的关系。"}], "explanations": {"联系": "正确。水与生命之间有很深的关系，这里用“联系”。", "体重": "体貌：体重说人或物的重量，不能说“很深的体重”。", "蔬菜": "语义：蔬菜不是水与生命之间的关系。", "身材": "体貌：身材指人的体形，不能用来说水与生命的关系。"}, "sentence_index": 6, "correct_answer": "联系"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我和朋友之间有一把联系。", "explanation": "这里应该用量词〈种〉。“把”用于有柄的东西，联系是抽象的。"}, {"text": "这盏灯是一种联系。", "explanation": "这里把〈联系〉误用成了〈物件〉的意思；“联系”是两者之间的关系，灯不能是联系。"}, {"text": "这两条绳子需要联系起来。", "explanation": "这里应该用〈连接〉。两条绳子的物理相接要用“连接”，“联系”指关系或沟通。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c40d09f-a1a3-461a-bcd0-237c5ea4f0ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21410, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他和我之间有一条联系。", "corrected_sentence": "他和我之间有一种联系。", "error_description": "错误：“一条联系”，正确：“一种联系”。“条”用于细长的东西，抽象的关系要用“种”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c40d09f-a1a3-461a-bcd0-237c5ea4f0ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21410, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这本书和我的童年有一块联系。", "corrected_sentence": "这本书和我的童年有一种联系。", "error_description": "错误：“一块联系”，正确：“一种联系”。“块”用于块状的东西，抽象的关系要用“种”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c40d09f-a1a3-461a-bcd0-237c5ea4f0ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
