INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21418, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "一个国家或地区的生产、流通、消费等经济活动的整体情况。", "primary_collocate": null, "pronunciation": "jīng jì", "ipa": "tɕiŋ˥ tɕi˥˩", "syllable_count": 2, "sentences": [{"text": "这个国家的经济发展得很快。", "target_word": "经济", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我哥哥很关心经济。", "target_word": "经济", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "今年的经济比去年好。", "target_word": "经济", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "经济好了，大家的钱也多了。", "target_word": "经济", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个城市的经济靠旅游。", "target_word": "经济", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这场大雨影响了经济，很多店都关门了。", "target_word": "经济", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "经济不好的时候，找工作很难。", "target_word": "经济", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "现在世界经济有一些问题。", "target_word": "经济", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爸爸每天看报纸，关心国家的经济。", "target_word": "经济", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "新的路让小城的经济变得更好了。", "target_word": "经济", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "经济学", "label": "复合"}, {"form": "经济体", "label": "复合"}], "register": "中性", "sense_fingerprint": "名词：一个地方生产、赚钱、买卖的整体情况", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a7a5ac5-16ea-4b03-b6bf-b31c050a3381') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21418, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "竞技", "is_correct": false, "explanation": "jìng（第四声）与 jīng（第一声）声调不同，竞技指体育比赛中的较量。"}, {"text": "京剧", "is_correct": false, "explanation": "jù（ü）与 jì（i）韵母不同，京剧是一种传统戏曲。"}, {"text": "今季", "is_correct": false, "explanation": "jīn 与 jīng 韵尾不同（in 与 ing），今季指这个赛季。"}, {"text": "经济", "is_correct": true, "explanation": "正确答案，指国家或地区的整体生产、流通和消费情况。"}], "explanations": {"竞技": "jìng（第四声）与 jīng（第一声）声调不同，竞技指体育比赛中的较量。", "京剧": "jù（ü）与 jì（i）韵母不同，京剧是一种传统戏曲。", "今季": "jīn 与 jīng 韵尾不同（in 与 ing），今季指这个赛季。", "经济": "正确答案，指国家或地区的整体生产、流通和消费情况。"}, "sentence_index": null, "correct_answer": "经济"}, "level_3": {"options": [{"text": "经济", "is_correct": true, "explanation": "正确答案。国家的生产、流通和消费等整体情况可以发展。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：身高是人的身材特征，不能说“发展得很快”。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色不会发展，句子说的是国家的整体情况。"}, {"text": "作业", "is_correct": false, "explanation": "语义：作业是学生的功课，不能说国家的作业发展得很快。"}], "explanations": {"经济": "正确答案。国家的生产、流通和消费等整体情况可以发展。", "身高": "体貌：身高是人的身材特征，不能说“发展得很快”。", "颜色": "语义：颜色不会发展，句子说的是国家的整体情况。", "作业": "语义：作业是学生的功课，不能说国家的作业发展得很快。"}, "sentence_index": 0, "correct_answer": "经济"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每个月的经济很多。", "explanation": "这里应该用〈收入〉。经济指整体经济情况，不能用来说个人每月进账的多少。"}, {"text": "公司需要更多经济。", "explanation": "这里应该用〈资金〉。经济指整体经济情况，不能指公司投入的钱。"}, {"text": "这个家族拥有很多经济。", "explanation": "这里应该用〈财富〉。经济指整体经济情况，不是可以数量多少的财产。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '418d1f0c-1c48-41ce-8f88-2d8d3f6dd495') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21418, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "经济", "is_correct": true, "explanation": "正确答案。句子说的是国家或地区整体经济状况不好。"}, {"text": "房子", "is_correct": false, "explanation": "语义：房子的好坏与找工作难不难无关，句子说的是整体状况。"}, {"text": "学费", "is_correct": false, "explanation": "搭配：“不好”一般说状况或质量，不说学费不好。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子不能决定找工作难不难，这一说法没有意义。"}], "explanations": {"经济": "正确答案。句子说的是国家或地区整体经济状况不好。", "房子": "语义：房子的好坏与找工作难不难无关，句子说的是整体状况。", "学费": "搭配：“不好”一般说状况或质量，不说学费不好。", "桌子": "语义：桌子不能决定找工作难不难，这一说法没有意义。"}, "sentence_index": 6, "correct_answer": "经济"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次旅行的经济很高。", "explanation": "这里应该用〈费用〉。经济指整体经济情况，不能用来说某次开支的多少。"}, {"text": "这批货物的经济很多。", "explanation": "这里应该用〈数量〉。经济指整体经济情况，不能用来说货物的多少。"}, {"text": "这次考试的经济很好。", "explanation": "这里应该用〈成绩〉。经济指整体经济情况，不能用来说考试的好坏。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '418d1f0c-1c48-41ce-8f88-2d8d3f6dd495') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21418, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们要发展经济的。", "corrected_sentence": "我们要发展经济。", "error_description": "错误：句末多出“的”，“的”后面缺少中心语，句子不完整。正确：我们要发展经济。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '418d1f0c-1c48-41ce-8f88-2d8d3f6dd495') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21418, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这几年经济得很好。", "corrected_sentence": "这几年经济很好。", "error_description": "错误：“经济得很好”。正确：“经济很好”。“经济”后面不加“得”，程度副词“很”直接修饰形容词即可。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '418d1f0c-1c48-41ce-8f88-2d8d3f6dd495') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
