INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21420, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "商品从一个地方卖到另一个地方，或者从一个人手里交给另一个人。", "primary_collocate": null, "pronunciation": "shāng pǐn liú tōng", "ipa": "ʂɑŋ˥ pʰin˨˩ ljoʊ˧˥ tʰʊŋ˥", "syllable_count": 4, "sentences": [{"text": "铁路修好后，山区的商品流通快多了。", "target_word": "商品流通", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "春节前，市场上的商品流通特别活跃。", "target_word": "商品流通", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "商品流通不畅，农民的水果卖不出去。", "target_word": "商品流通", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这条河是两省商品流通的主要通道。", "target_word": "商品流通", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "古时候，丝绸之路促进了东西方的商品流通。", "target_word": "商品流通", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雪封路，城里的商品流通暂时停了。", "target_word": "商品流通", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "有了快递，农村和城市之间的商品流通方便了。", "target_word": "商品流通", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "批发市场对商品流通很重要。", "target_word": "商品流通", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小店老板说，节日里商品流通最快。", "target_word": "商品流通", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "有了新公路，两个小镇的商品流通快了。", "target_word": "商品流通", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "商品", "label": "复合"}, {"form": "流通", "label": "复合"}], "register": "中性", "sense_fingerprint": "商品在地区之间或人与人之间的买卖流动", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '108d68a3-9e9d-4db4-87ac-576670149e7e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21420, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "商品流通", "is_correct": true, "explanation": "商品流通指商品的流转，与“铁路修好后，山区的……快多了”相合。"}, {"text": "历史文化", "is_correct": false, "explanation": "语义：历史文化不会因铁路修好而“快多了”。"}, {"text": "眼镜", "is_correct": false, "explanation": "搭配：“快多了”一般不修饰“眼镜”。"}, {"text": "戏剧", "is_correct": false, "explanation": "语义：戏剧与铁路修好后的变化无关。"}], "explanations": {"商品流通": "商品流通指商品的流转，与“铁路修好后，山区的……快多了”相合。", "历史文化": "语义：历史文化不会因铁路修好而“快多了”。", "眼镜": "搭配：“快多了”一般不修饰“眼镜”。", "戏剧": "语义：戏剧与铁路修好后的变化无关。"}, "sentence_index": 0, "correct_answer": "商品流通"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在市场上商品流通水果。", "explanation": "这里应该用〈卖〉。商品流通是名词，表示流转过程，不能当动词带宾语。"}, {"text": "工人们商品流通了二十箱货。", "explanation": "这里应该用〈搬运〉。商品流通不是表示搬运动作的动词，不能用来说搬货。"}, {"text": "这只商品流通很重要。", "explanation": "这里应该用〈种〉。“只”多用于动物或小件物品，商品流通是抽象过程，应说“这种商品流通”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cc373b86-8a83-465b-a127-2513a3100454') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21420, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "商品流通", "is_correct": true, "explanation": "商品流通指商品的流转，与“有了快递，农村和城市之间的……方便了”相合。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不会因快递而“方便”。"}, {"text": "农药", "is_correct": false, "explanation": "搭配：“方便”不修饰“农药”。"}, {"text": "方言", "is_correct": false, "explanation": "语义：方言与快递带来的便利无关。"}], "explanations": {"商品流通": "商品流通指商品的流转，与“有了快递，农村和城市之间的……方便了”相合。", "天气": "语义：天气不会因快递而“方便”。", "农药": "搭配：“方便”不修饰“农药”。", "方言": "语义：方言与快递带来的便利无关。"}, "sentence_index": 6, "correct_answer": "商品流通"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "河水在地下商品流通。", "explanation": "这里应该用〈流动〉。商品流通专指商品的流转，不能用于水的流动。"}, {"text": "公司商品流通了三名员工。", "explanation": "这里应该用〈调动〉。商品流通只指商品的流转，不能用于人员的调配。"}, {"text": "这支商品流通很发达。", "explanation": "这里应该用〈种〉。“支”多用于队伍、细长物件，商品流通是抽象过程，应说“这种商品流通”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cc373b86-8a83-465b-a127-2513a3100454') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21420, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "春节期间，这座城市的商品流通了很活跃。", "corrected_sentence": "春节期间，这座城市的商品流通很活跃。", "error_description": "“商品流通”后不能直接加“了”接形容词谓语；应说“商品流通很活跃”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cc373b86-8a83-465b-a127-2513a3100454') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21420, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "两省之间的商品流通很频繁着。", "corrected_sentence": "两省之间的商品流通很频繁。", "error_description": "“很频繁”是形容词谓语，后面不能加“着”；应说“两省之间的商品流通很频繁”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cc373b86-8a83-465b-a127-2513a3100454') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
