INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21422, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "客观事物的情况在另一事物上表现出来，就像镜子照出样子。", "primary_collocate": null, "pronunciation": "fǎn yìng", "ipa": "fan˨˩˦ iŋ˥˩", "syllable_count": 2, "sentences": [{"text": "这张照片反映了我们家的生活。", "target_word": "反映", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "考试成绩反映了他学习很认真。", "target_word": "反映", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书反映了那个时代的样子。", "target_word": "反映", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的脸色反映了他的心情。", "target_word": "反映", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "菜价上涨反映了天气不好。", "target_word": "反映", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小河像镜子一样，反映着蓝天。", "target_word": "反映", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些数字反映了城市越来越大。", "target_word": "反映", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的画反映了她对家乡的爱。", "target_word": "反映", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一个人说的话，常常反映他的想法。", "target_word": "反映", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个电影反映了农村的变化。", "target_word": "反映", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "反映了", "label": "体标"}, {"form": "反映着", "label": "体标"}, {"form": "反映过", "label": "体标"}], "register": "中性", "sense_fingerprint": "客观事物的情况在另一事物上表现出来，如镜子照出", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e949e43-2da5-404e-9e85-f72be655bc2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21422, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "反映", "is_correct": true, "explanation": "符合语境：照片能显示家里的生活情况，“反映”指客观事物在另一事物上表现出来。"}, {"text": "打扫", "is_correct": false, "explanation": "语义：照片不能打扫生活，句子意思不通。"}, {"text": "撕毁", "is_correct": false, "explanation": "搭配：“撕毁”后接的是纸张、合同之类的东西，不能说撕毁生活。"}, {"text": "擦拭", "is_correct": false, "explanation": "语义：照片不能擦拭生活，擦拭的对象应是具体的物体。"}], "explanations": {"反映": "符合语境：照片能显示家里的生活情况，“反映”指客观事物在另一事物上表现出来。", "打扫": "语义：照片不能打扫生活，句子意思不通。", "撕毁": "搭配：“撕毁”后接的是纸张、合同之类的东西，不能说撕毁生活。", "擦拭": "语义：照片不能擦拭生活，擦拭的对象应是具体的物体。"}, "sentence_index": 0, "correct_answer": "反映"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的反映很快，老师的问题刚说完，他就举手了。", "explanation": "这里应该用〈反应〉。“反映”指把客观情况显示出来，对刺激作出的快速回应要用“反应”。"}, {"text": "他在比赛中反映得很好。", "explanation": "这里应该用〈表现〉。“反映”指客观情况显露出来，不用来说人在比赛中的表现。"}, {"text": "他当场反映了我的推理，驳得我无话可说。", "explanation": "这里应该用〈反驳〉。“反映”指客观情况显露出来，驳斥别人的观点要用“反驳”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fdab4312-7e5e-47ce-9bc8-36c7c2d6f927') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21422, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "反映", "is_correct": true, "explanation": "符合语境：数字能显示城市的变化，“反映”表示通过数字显现城市的发展。"}, {"text": "挖出", "is_correct": false, "explanation": "语义：“挖出”指从地下取出东西，数字不能挖出城市的变化。"}, {"text": "推出", "is_correct": false, "explanation": "语义：“推出”指推向市场或公开提出，数字不能推出城市的变化。"}, {"text": "拿出", "is_correct": false, "explanation": "搭配：“拿出”的宾语应是具体的物件，不能拿出抽象的城市变化。"}], "explanations": {"反映": "符合语境：数字能显示城市的变化，“反映”表示通过数字显现城市的发展。", "挖出": "语义：“挖出”指从地下取出东西，数字不能挖出城市的变化。", "推出": "语义：“推出”指推向市场或公开提出，数字不能推出城市的变化。", "拿出": "搭配：“拿出”的宾语应是具体的物件，不能拿出抽象的城市变化。"}, "sentence_index": 6, "correct_answer": "反映"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在杂志上反映了一篇文章。", "explanation": "这里应该用〈发表〉。“反映”指客观情况显现出来，把文章公开刊登要用“发表”。"}, {"text": "政府反映了新的法律。", "explanation": "这里应该用〈颁布〉。“反映”指客观情况显现出来，法律的正式公布要用“颁布”。"}, {"text": "学校反映了三名优秀学生。", "explanation": "这里应该用〈表彰〉。“反映”指客观情况显现出来，对优秀学生给予荣誉要用“表彰”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fdab4312-7e5e-47ce-9bc8-36c7c2d6f927') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21422, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这份报告反映起学生的学习压力。", "corrected_sentence": "这份报告反映出学生的学习压力。", "error_description": "错误形式是“反映起学生的学习压力”，正确形式是“反映出学生的学习压力”。“反映”后的趋向补语应是“出”，表示情况显露出来；“起”不能与“反映”搭配。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fdab4312-7e5e-47ce-9bc8-36c7c2d6f927') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21422, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这份调查很反映城市的交通问题。", "corrected_sentence": "这份调查反映城市的交通问题。", "error_description": "错误形式是“很反映”，正确形式是直接说“反映”。“很”只能修饰形容词，“反映”是动词，不能用“很”修饰。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fdab4312-7e5e-47ce-9bc8-36c7c2d6f927') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
