INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21428, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "可以喝的东西，比如水、牛奶、果汁。", "primary_collocate": null, "pronunciation": "yǐn pǐn", "ipa": "in˨˩˦ pʰin˨˩˦", "syllable_count": 2, "sentences": [{"text": "水、牛奶和果汁都是饮品。", "target_word": "饮品", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们带了一些饮品去公园。", "target_word": "饮品", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "比赛后，老师给大家准备了饮品。", "target_word": "饮品", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请问，店里有什么饮品？", "target_word": "饮品", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "晚会上有蛋糕，也有各种饮品。", "target_word": "饮品", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "热的饮品对身体好。", "target_word": "饮品", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他每天只喝水，不喝别的饮品。", "target_word": "饮品", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那台机器可以卖饮品。", "target_word": "饮品", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "你去买饮品时，帮我带一杯吧。", "target_word": "饮品", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个冰箱里放满了饮品。", "target_word": "饮品", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一种饮品", "label": "量词"}, {"form": "饮品店", "label": "复合"}, {"form": "飲品", "label": "繁体"}], "register": "中性", "sense_fingerprint": "日常能喝的东西，如水、牛奶、果汁", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '14b46c7c-cf37-4c6d-b606-f814fed56f14') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21428, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "饮品", "is_correct": true, "explanation": "正确。水、牛奶和果汁都是可以喝的饮品。"}, {"text": "乐器", "is_correct": false, "explanation": "语义：水、牛奶和果汁不是乐器。"}, {"text": "矿石", "is_correct": false, "explanation": "语义：水、牛奶和果汁不是矿石。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：身材指人的体形，不能用来指饮用的液体。"}], "explanations": {"饮品": "正确。水、牛奶和果汁都是可以喝的饮品。", "乐器": "语义：水、牛奶和果汁不是乐器。", "矿石": "语义：水、牛奶和果汁不是矿石。", "身材": "体貌：身材指人的体形，不能用来指饮用的液体。"}, "sentence_index": 0, "correct_answer": "饮品"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们晚饭吃了不少饮品。", "explanation": "这里应该用〈食品〉。“饮品”指可以喝的东西，吃的东西要用“食品”。"}, {"text": "我们在店里买了一块饮品。", "explanation": "这里应该用量词〈杯〉或〈瓶〉。“块”用于块状的东西，饮品是液体。"}, {"text": "那把椅子是一种饮品。", "explanation": "这里把〈饮品〉误用成了〈物品〉的意思；“饮品”只指可以喝的液体，椅子不能是饮品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c40d09f-a1a3-461a-bcd0-237c5ea4f0ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21428, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "饮品", "is_correct": true, "explanation": "正确。他每天只喝的水之外，别的可以喝的东西是饮品。"}, {"text": "动物", "is_correct": false, "explanation": "语义：喝的对象是饮品，不是动物。"}, {"text": "食物", "is_correct": false, "explanation": "搭配：“喝”一般不带“食物”，说“喝”时要用饮品。"}, {"text": "树木", "is_correct": false, "explanation": "语义：树木不是可以喝的东西。"}], "explanations": {"饮品": "正确。他每天只喝的水之外，别的可以喝的东西是饮品。", "动物": "语义：喝的对象是饮品，不是动物。", "食物": "搭配：“喝”一般不带“食物”，说“喝”时要用饮品。", "树木": "语义：树木不是可以喝的东西。"}, "sentence_index": 6, "correct_answer": "饮品"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我买了一本饮品。", "explanation": "这里应该用量词〈杯〉或〈瓶〉。“本”用于书籍等，饮品不用“本”。"}, {"text": "这块蛋糕的饮品很多。", "explanation": "这里应该用〈奶油〉。“饮品”指可以喝的液体，蛋糕上的奶油不能说成饮品。"}, {"text": "小明每天吃三顿饮品。", "explanation": "这里应该用〈食物〉。吃的东西要用“食物”，“饮品”是可以喝的液体。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c40d09f-a1a3-461a-bcd0-237c5ea4f0ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21428, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我买了一只饮品。", "corrected_sentence": "我买了一杯饮品。", "error_description": "错误：“一只饮品”，正确：“一杯饮品”。“只”用于动物等，饮品要用“杯”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c40d09f-a1a3-461a-bcd0-237c5ea4f0ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21428, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们每次聚会都会准备各条饮品。", "corrected_sentence": "我们每次聚会都会准备各种饮品。", "error_description": "错误：“各条饮品”，正确：“各种饮品”。“条”用于细长的东西，饮品要用“种”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c40d09f-a1a3-461a-bcd0-237c5ea4f0ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
