INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21432, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "城市，就是有很多房子和很多人的地方。", "primary_collocate": null, "pronunciation": "dū shì", "ipa": "tu˥ ʂʐ̩˥˩", "syllable_count": 2, "sentences": [{"text": "我喜欢都市里的夜晚。", "target_word": "都市", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座都市有一千多万人。", "target_word": "都市", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从小山村搬到了都市。", "target_word": "都市", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "都市里的车非常多。", "target_word": "都市", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多年轻人想去都市工作。", "target_word": "都市", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "都市的生活节奏很快。", "target_word": "都市", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在一座现代化的都市长大。", "target_word": "都市", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "晚上的都市到处都是灯。", "target_word": "都市", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "都市里的空气不太好。", "target_word": "都市", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是一部写都市生活的电影。", "target_word": "都市", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "座", "label": "量词"}], "register": "中性", "sense_fingerprint": "人口多、楼房多、很繁华的大城市", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4ee3da4-4c99-4c2d-aaed-c51fb6a3dd04') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21432, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "都市", "is_correct": true, "explanation": "都市：指人口多、楼房多的大城市，与“都市里的夜晚”的句意相符。"}, {"text": "同学", "is_correct": false, "explanation": "语义：“同学”指人，不是可以“里”的场所，“同学里的夜晚”句意说不通。"}, {"text": "钢琴", "is_correct": false, "explanation": "语义：“钢琴”是乐器，不是可以容纳夜晚的地方，句意说不通。"}, {"text": "考试", "is_correct": false, "explanation": "搭配：“里”多接地点或场所，“考试”是活动，不能说“考试里的夜晚”。"}], "explanations": {"都市": "都市：指人口多、楼房多的大城市，与“都市里的夜晚”的句意相符。", "同学": "语义：“同学”指人，不是可以“里”的场所，“同学里的夜晚”句意说不通。", "钢琴": "语义：“钢琴”是乐器，不是可以容纳夜晚的地方，句意说不通。", "考试": "搭配：“里”多接地点或场所，“考试”是活动，不能说“考试里的夜晚”。"}, "sentence_index": 0, "correct_answer": "都市"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我家住在一个都市里，周围都是田地。", "explanation": "这里应该用〈村庄〉。“都市”指人口密集、楼房林立的大城市，不能用来形容周围都是田地的地方。"}, {"text": "这个都市只有两条街，大家都互相认识。", "explanation": "这里应该用〈小镇〉。“都市”是大城市，人口多，不能用来形容只有两条街、居民彼此相识的地方。"}, {"text": "都市的夜晚几乎看不到灯，只能听见虫子的叫声。", "explanation": "这里应该用〈乡下〉。“都市”指灯火通明、人口密集的大城市，夜里到处是灯，不能用来形容几乎看不到灯、只能听见虫鸣的地方。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f93d1fd-c9ce-4a85-b08a-17b9da95ee23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21432, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "都市", "is_correct": true, "explanation": "都市：指人口多、楼房多的大城市，与“在一座现代化的都市长大”的句意相符。"}, {"text": "山", "is_correct": false, "explanation": "搭配：“现代化”多修饰城市、工厂等，不能修饰“山”。"}, {"text": "桥", "is_correct": false, "explanation": "语义：“桥”不是人可以在里面长大的地方，“现代化的桥”之中“长大”句意不通。"}, {"text": "寺庙", "is_correct": false, "explanation": "语义：“寺庙”是宗教场所，与“现代化”的修饰意义相冲突，“在寺庙里长大”的句意也与句子不符。"}], "explanations": {"都市": "都市：指人口多、楼房多的大城市，与“在一座现代化的都市长大”的句意相符。", "山": "搭配：“现代化”多修饰城市、工厂等，不能修饰“山”。", "桥": "语义：“桥”不是人可以在里面长大的地方，“现代化的桥”之中“长大”句意不通。", "寺庙": "语义：“寺庙”是宗教场所，与“现代化”的修饰意义相冲突，“在寺庙里长大”的句意也与句子不符。"}, "sentence_index": 6, "correct_answer": "都市"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个都市到处是庄稼和果树。", "explanation": "这里应该用〈农村〉。“都市”指高楼林立的大城市，不能用来形容到处是庄稼和果树的地方。"}, {"text": "这个都市位于深山里，出门要走三天的山路。", "explanation": "这里应该用〈山村〉。“都市”是大城市，不能用来形容位于深山、出门要走三天山路的地方。"}, {"text": "这个都市的人口只有几千，大家都在田里干活。", "explanation": "这里应该用〈乡镇〉。“都市”人口多、楼房多，不能用来形容只有几千人、大家都在田里干活的地方。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f93d1fd-c9ce-4a85-b08a-17b9da95ee23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21432, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这条都市的交通很方便。", "corrected_sentence": "这座都市的交通很方便。", "error_description": "量词错误：“都市”是大型城市，应用量词“座”，不能用“条”，应为“这座都市”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f93d1fd-c9ce-4a85-b08a-17b9da95ee23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21432, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这辆车在都市上开得很慢。", "corrected_sentence": "这辆车在都市里开得很慢。", "error_description": "方位词错误：表示范围应说“都市里”，“都市上”不能这样用，应为“在都市里”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f93d1fd-c9ce-4a85-b08a-17b9da95ee23') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21434, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '418d1f0c-1c48-41ce-8f88-2d8d3f6dd495') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
