INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21434, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "链条是一节一节连起来的东西，像自行车的链子。", "primary_collocate": null, "pronunciation": "liàn tiáo", "ipa": "ljɛn˥˩ tʰjɑʊ˧˥", "syllable_count": 2, "sentences": [{"text": "自行车的链条掉了，我不能骑车。", "target_word": "链条", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他给自行车的链条加了一点油。", "target_word": "链条", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条链条是铁做的，一节一节很结实。", "target_word": "链条", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人用一根粗链条把大门锁住了。", "target_word": "链条", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "链条断了，自行车一点儿也不能走。", "target_word": "链条", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那只狗用链条拴着，不能到处跑。", "target_word": "链条", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "铁做的链条一节一节连在一起。", "target_word": "链条", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你的自行车链条太脏了，要洗一洗。", "target_word": "链条", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这根链条很长，也很重，一个人拿不动。", "target_word": "链条", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "自行车上的链条很重要，坏了就走不了。", "target_word": "链条", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一根链条", "label": "量词"}, {"form": "一条链条", "label": "量词"}, {"form": "鏈條", "label": "繁体"}], "register": "中性", "sense_fingerprint": "一节一节连起来的金属链子，如自行车链条", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a7a5ac5-16ea-4b03-b6bf-b31c050a3381') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21434, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "链条", "is_correct": true, "explanation": "正确答案。链条是一节节连起来的金属链子，是自行车上会掉落的部件。"}, {"text": "眉毛", "is_correct": false, "explanation": "体貌：眉毛是人的体貌特征，不属于自行车。"}, {"text": "名字", "is_correct": false, "explanation": "语义：名字是称呼，不是能掉下来的部件。"}, {"text": "味道", "is_correct": false, "explanation": "语义：味道不是实体，不会掉下来。"}], "explanations": {"链条": "正确答案。链条是一节节连起来的金属链子，是自行车上会掉落的部件。", "眉毛": "体貌：眉毛是人的体貌特征，不属于自行车。", "名字": "语义：名字是称呼，不是能掉下来的部件。", "味道": "语义：味道不是实体，不会掉下来。"}, "sentence_index": 0, "correct_answer": "链条"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈用链条晾衣服。", "explanation": "这里应该用〈绳子〉。链条是一节节金属环连起来的，晾衣服要用绳子。"}, {"text": "她用链条织了一条围巾。", "explanation": "这里应该用〈毛线〉。链条是金属环连成的，不能用来编织。"}, {"text": "火车在链条上飞驰。", "explanation": "这里应该用〈铁轨〉。链条是一节节连起来的金属链子，火车要在铁轨上行驶。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '418d1f0c-1c48-41ce-8f88-2d8d3f6dd495') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21434, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "链条", "is_correct": true, "explanation": "正确答案。链条是一节节连在一起的金属链子。"}, {"text": "句子", "is_correct": false, "explanation": "语义：句子不是金属制品，不能“一节一节连在一起”。"}, {"text": "钥匙", "is_correct": false, "explanation": "语义：钥匙不会一节节连在一起，句子说的是链子。"}, {"text": "笔记", "is_correct": false, "explanation": "搭配：“一节一节”搭配可分段的条状物，笔记不适用。"}], "explanations": {"链条": "正确答案。链条是一节节连在一起的金属链子。", "句子": "语义：句子不是金属制品，不能“一节一节连在一起”。", "钥匙": "语义：钥匙不会一节节连在一起，句子说的是链子。", "笔记": "搭配：“一节一节”搭配可分段的条状物，笔记不适用。"}, "sentence_index": 6, "correct_answer": "链条"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "司机转动链条，车子就拐弯了。", "explanation": "这里应该用〈方向盘〉。链条是传动部件，不能用来转向。"}, {"text": "这件衣服的链条坏了。", "explanation": "这里应该用〈拉链〉。衣服上可以拉开合上的是拉链，链条是金属链子。"}, {"text": "用链条拧螺丝。", "explanation": "这里应该用〈扳手〉。链条不是拧螺丝的工具。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '418d1f0c-1c48-41ce-8f88-2d8d3f6dd495') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21434, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我的自行车上有一只新链条。", "corrected_sentence": "我的自行车上有一根新链条。", "error_description": "错误：“一只新链条”。正确：“一根新链条”。链条是长条形的东西，量词要用“根”或“条”，“只”不用于链条。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '418d1f0c-1c48-41ce-8f88-2d8d3f6dd495') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21434, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他用一只链条把车子锁上了。", "corrected_sentence": "他用一根链条把车子锁上了。", "error_description": "错误：“一只链条”。正确：“一根链条”。链条是长条形的东西，量词要用“根”或“条”，“只”不用于链条。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '418d1f0c-1c48-41ce-8f88-2d8d3f6dd495') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21436, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "静止", "is_correct": true, "explanation": "反义：“静止”指不动，与“流动”（水或空气移动）相对，水池里的水不流动即是静止。"}, {"text": "唱歌", "is_correct": false, "explanation": "无关：“唱歌”是发声的动作，与“流动”不构成反义。"}, {"text": "睡觉", "is_correct": false, "explanation": "无关：“睡觉”是休息的行为，与“流动”不构成反义。"}, {"text": "思考", "is_correct": false, "explanation": "无关：“思考”指用脑，与“流动”不构成反义。"}], "correct_answer": "静止", "explanations": {"静止": "反义：“静止”指不动，与“流动”（水或空气移动）相对，水池里的水不流动即是静止。", "唱歌": "无关：“唱歌”是发声的动作，与“流动”不构成反义。", "睡觉": "无关：“睡觉”是休息的行为，与“流动”不构成反义。", "思考": "无关：“思考”指用脑，与“流动”不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cc373b86-8a83-465b-a127-2513a3100454') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21436, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "静止", "is_correct": true, "explanation": "反义：“静止”指不动，与“流动”（水移动）相对，大河里的水不流动即是静止。"}, {"text": "跳舞", "is_correct": false, "explanation": "无关：“跳舞”是身体的律动，与“流动”不构成反义。"}, {"text": "写字", "is_correct": false, "explanation": "无关：“写字”是书写的动作，与“流动”不构成反义。"}, {"text": "吃饭", "is_correct": false, "explanation": "无关：“吃饭”是进食的行为，与“流动”不构成反义。"}], "correct_answer": "静止", "explanations": {"静止": "反义：“静止”指不动，与“流动”（水移动）相对，大河里的水不流动即是静止。", "跳舞": "无关：“跳舞”是身体的律动，与“流动”不构成反义。", "写字": "无关：“写字”是书写的动作，与“流动”不构成反义。", "吃饭": "无关：“吃饭”是进食的行为，与“流动”不构成反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cc373b86-8a83-465b-a127-2513a3100454') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21436, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "水或空气可以移动，就像河里的水在流。", "primary_collocate": null, "pronunciation": "liú dòng", "ipa": "liou̯˧˥ tʊŋ˥˩", "syllable_count": 2, "sentences": [{"text": "小河里的水一直在流动。", "target_word": "流动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "风吹过来，空气开始流动了。", "target_word": "流动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水龙头打开后，水就流动起来了。", "target_word": "流动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水池里的水不流动，会变脏。", "target_word": "流动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山上的泉水向下流动，最后进了湖里。", "target_word": "流动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房间里没有风，空气几乎不流动。", "target_word": "流动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨后，路边的水沿着小沟流动。", "target_word": "流动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天开着窗，凉风在屋里流动着。", "target_word": "流动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河水向东流动，穿过了整个城市。", "target_word": "流动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大河里的水，流动得很快，不要下去游泳。", "target_word": "流动", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "流动着", "label": "体标"}, {"form": "流动了", "label": "体标"}, {"form": "流动过", "label": "体标"}, {"form": "流動", "label": "繁体"}], "register": "中性", "sense_fingerprint": "流动|动词|水或空气像河水一样移动", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '108d68a3-9e9d-4db4-87ac-576670149e7e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21436, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "喝", "is_correct": false, "explanation": "配价：“喝”的施事须是人或动物，水不能作“喝”的主语。"}, {"text": "上课", "is_correct": false, "explanation": "语义：河水不会上课，这样的说法与句意不符。"}, {"text": "考试", "is_correct": false, "explanation": "语义：水没有考试这样的行为，句子说不通。"}, {"text": "流动", "is_correct": true, "explanation": "正确：小河里的水一直在移动，即“流动”。"}], "explanations": {"喝": "配价：“喝”的施事须是人或动物，水不能作“喝”的主语。", "上课": "语义：河水不会上课，这样的说法与句意不符。", "考试": "语义：水没有考试这样的行为，句子说不通。", "流动": "正确：小河里的水一直在移动，即“流动”。"}, "sentence_index": 0, "correct_answer": "流动"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "小狗在院子里流动。", "explanation": "这里应该用〈跑〉。动物在地面上奔跑用“跑”，不用“流动”。"}, {"text": "河边的石头在水里流动，很好看。", "explanation": "这里应该用〈滚动〉。石头是固体，在水中翻转移动用“滚动”，“流动”指水或空气等流体的移动。"}, {"text": "小猫从桌上流动下来。", "explanation": "这里应该用〈跳〉。猫从桌上跳下来，不用“流动”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cc373b86-8a83-465b-a127-2513a3100454') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21436, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "唱歌", "is_correct": false, "explanation": "语义：水不会唱歌，句意不通。"}, {"text": "流动", "is_correct": true, "explanation": "正确：雨后路边的水沿着小沟移动，即“流动”。"}, {"text": "跳舞", "is_correct": false, "explanation": "语义：水不会跳舞，这样的说法与句意不符。"}, {"text": "散步", "is_correct": false, "explanation": "配价：“散步”的动作者须是人或动物，水不能散步。"}], "explanations": {"唱歌": "语义：水不会唱歌，句意不通。", "流动": "正确：雨后路边的水沿着小沟移动，即“流动”。", "跳舞": "语义：水不会跳舞，这样的说法与句意不符。", "散步": "配价：“散步”的动作者须是人或动物，水不能散步。"}, "sentence_index": 6, "correct_answer": "流动"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "陀螺在地上流动，转得很快。", "explanation": "这里应该用〈旋转〉。陀螺绕轴转动用“旋转”，不用“流动”。"}, {"text": "杯子从桌上流动下来，摔碎了。", "explanation": "这里应该用〈掉〉。杯子从桌上掉下来是固体的下落，不能说“流动”，“流动”指水或空气等物质的连续移动。"}, {"text": "箱子在地上流动，推了很久。", "explanation": "这里应该用〈滑动〉。箱子在地面上移动用“滑动”，“流动”指水或空气等流体的移动。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cc373b86-8a83-465b-a127-2513a3100454') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21436, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "雨停以后，路边的水被流动了。", "corrected_sentence": "雨停以后，路边的水开始流动了。", "error_description": "“流动”是不及物动词，不能用“被”字句，应说“开始流动”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cc373b86-8a83-465b-a127-2513a3100454') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21436, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "小溪的水不停的流动。", "corrected_sentence": "小溪的水不停地流动。", "error_description": "助词错误：修饰动词的状语后应用“地”，不应用“的”；“不停的流动”的“的”用错了位置，正确说法是“不停地流动”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cc373b86-8a83-465b-a127-2513a3100454') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
