INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21438, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "用来打字和看信息的机器", "primary_collocate": null, "pronunciation": "zhōng duān", "ipa": "ʈʂʊŋ˥ twan˥", "syllable_count": 2, "sentences": [{"text": "他在终端上打了一封信。", "target_word": "终端", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台终端的屏幕很大。", "target_word": "终端", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "图书馆有五台终端，可以查书。", "target_word": "终端", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我用终端看今天的新闻。", "target_word": "终端", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "终端旁边有一个键盘。", "target_word": "终端", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让学生在终端上练习打字。", "target_word": "终端", "complexity_tier": "T3", "furigana": "lǎo shī ràng xué shēng zài zhōng duān shàng liàn xí dǎ zì", "sentence_source": "generated"}, {"text": "那台终端太旧了，打字很慢。", "target_word": "终端", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把终端关好再走。", "target_word": "终端", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "车站的终端能查火车时间。", "target_word": "终端", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她每天在终端前工作八个小时。", "target_word": "终端", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "台", "label": "量词"}, {"form": "终端机", "label": "复合"}], "register": "中性", "sense_fingerprint": "用来打字和看信息的机器", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f775cb0c-f64a-45de-b26d-fcb784c8d131') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21438, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "天空", "is_correct": false, "explanation": "语义：不能在天空上打信，“终端”是可以操作的机器。"}, {"text": "终端", "is_correct": true, "explanation": "终端指供人打字、看信息的机器，“在终端上打信”表示在这台机器上操作。"}, {"text": "公园", "is_correct": false, "explanation": "搭配：“上”不接“公园”这类处所名词，要说“在公园里”。"}, {"text": "河流", "is_correct": false, "explanation": "语义：河流不是可以打字的机器或平面，与“打了一封信”不相容。"}], "explanations": {"天空": "语义：不能在天空上打信，“终端”是可以操作的机器。", "终端": "终端指供人打字、看信息的机器，“在终端上打信”表示在这台机器上操作。", "公园": "搭配：“上”不接“公园”这类处所名词，要说“在公园里”。", "河流": "语义：河流不是可以打字的机器或平面，与“打了一封信”不相容。"}, "sentence_index": 0, "correct_answer": "终端"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这部小说的终端很精彩。", "explanation": "这里应该用〈结尾〉。“终端”指线路或流程的末端，小说的结尾要用〈结尾〉，不用“终端”。"}, {"text": "我用一封终端看今天的新闻。", "explanation": "这里应该用〈台〉。“封”用于信件，终端是机器，应说“一台终端”。"}, {"text": "我用一把终端看今天的新闻。", "explanation": "这里应该用〈台〉。“把”用于有柄的物件，终端是机器，应说“一台终端”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e4a91d6-71e2-4710-8870-96bbf7f7d5cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21438, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱不能用来打字，“那台冰箱太旧了，打字很慢”句意不通。"}, {"text": "电视", "is_correct": false, "explanation": "搭配：“打字很慢”要求的是输入文字的设备，不说电视打字很慢。"}, {"text": "终端", "is_correct": true, "explanation": "终端指供人打字、看信息的机器，“那台终端太旧了”说明设备老旧，打字变慢。"}, {"text": "洗衣机", "is_correct": false, "explanation": "语义：洗衣机与打字无关，句中的“打字很慢”无法由它来完成。"}], "explanations": {"冰箱": "语义：冰箱不能用来打字，“那台冰箱太旧了，打字很慢”句意不通。", "电视": "搭配：“打字很慢”要求的是输入文字的设备，不说电视打字很慢。", "终端": "终端指供人打字、看信息的机器，“那台终端太旧了”说明设备老旧，打字变慢。", "洗衣机": "语义：洗衣机与打字无关，句中的“打字很慢”无法由它来完成。"}, "sentence_index": 6, "correct_answer": "终端"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这台终端负责为整栋楼的水管加压。", "explanation": "这里应该用〈水泵〉。终端是直接给人打字、看信息的机器，不负责给水管加压。"}, {"text": "这个终端负责覆盖整个小区的信号。", "explanation": "这里应该用〈基站〉。终端不负责覆盖信号，它只是人直接使用的机器。"}, {"text": "这台终端负责托管公司的网站。", "explanation": "这里应该用〈服务器〉。终端只供人打字和看信息，不负责托管网站。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e4a91d6-71e2-4710-8870-96bbf7f7d5cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21438, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "前台有一条终端，客人可以登记。", "corrected_sentence": "前台有一台终端，客人可以登记。", "error_description": "量词错误：“终端”作机器用“台”，“条”用于线状长物，这里应说“一台终端”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e4a91d6-71e2-4710-8870-96bbf7f7d5cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21438, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "在图书馆的一条终端上可以查借书记录。", "corrected_sentence": "在图书馆的一台终端上可以查借书记录。", "error_description": "量词错误：“终端”是机器，应用“台”，“条”用于线状长物，这里应说“一台终端”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e4a91d6-71e2-4710-8870-96bbf7f7d5cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
