INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21450, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "从一个地方通到另一个地方。", "primary_collocate": null, "pronunciation": "guàn chuān", "ipa": "kwan˥˩ tʂʰwan˥", "syllable_count": 2, "sentences": [{"text": "一条大河贯穿这座城市。", "target_word": "贯穿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条铁路贯穿南北。", "target_word": "贯穿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "长江贯穿中国中部。", "target_word": "贯穿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新修的地铁贯穿了整个城区。", "target_word": "贯穿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一条公路贯穿山谷，把两个村子连起来。", "target_word": "贯穿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条大街贯穿东西，两边都是商店。", "target_word": "贯穿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "隧道贯穿了这座大山。", "target_word": "贯穿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "运河贯穿南北，是重要的水路。", "target_word": "贯穿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一条小路贯穿整个村子。", "target_word": "贯穿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条高速公路贯穿全省。", "target_word": "贯穿", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "贯穿了", "label": "完成体"}, {"form": "贯穿着", "label": "持续体"}, {"form": "贯穿过", "label": "经历体"}, {"form": "貫穿", "label": "繁体"}], "register": "中性", "sense_fingerprint": "贯穿：河流、道路等从一个地方穿过并通到另一个地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4ae535a-9ea1-4936-80af-cc9fd7df8a24') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21450, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "贯穿", "is_correct": true, "explanation": "贯穿指河流、道路等从一地通到另一地。此处说一条大河穿过这座城市，语义和搭配都吻合。"}, {"text": "参观", "is_correct": false, "explanation": "搭配：“参观”的主体需要是有意识到各处看看的人，大河不能参观城市。"}, {"text": "讨论", "is_correct": false, "explanation": "搭配：“讨论”的主体须是人，河流不能讨论城市，句意不通。"}, {"text": "嘲笑", "is_correct": false, "explanation": "语义：“嘲笑”表示取笑、讥讽，与大河和城市的地理关系毫无关系。"}], "explanations": {"贯穿": "贯穿指河流、道路等从一地通到另一地。此处说一条大河穿过这座城市，语义和搭配都吻合。", "参观": "搭配：“参观”的主体需要是有意识到各处看看的人，大河不能参观城市。", "讨论": "搭配：“讨论”的主体须是人，河流不能讨论城市，句意不通。", "嘲笑": "语义：“嘲笑”表示取笑、讥讽，与大河和城市的地理关系毫无关系。"}, "sentence_index": 0, "correct_answer": "贯穿"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在操场上贯穿了三圈。", "explanation": "这里应该用〈跑〉。贯穿指道路、河流等从一地通到另一地，不能用来计算跑步的圈数；跑步应说跑了三圈。"}, {"text": "我们贯穿了这片沙漠。", "explanation": "这里应该用〈穿越〉。穿越指人或车辆从某地穿行而过，主语可以是人；“贯穿”的主语通常是路线或河流，表示通到另一地，不用来指人穿行。"}, {"text": "政府计划贯穿一场比赛。", "explanation": "这里应该用〈举办〉。贯穿指道路、河流等从一地通到另一地，不能用来说比赛；组织比赛应说举办。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0bbee471-ed91-4ad7-9c7d-e91e67c30138') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21450, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "贯穿", "is_correct": true, "explanation": "贯穿指通过、穿通。此处说隧道穿透了这座大山，语义和搭配都吻合。"}, {"text": "违反", "is_correct": false, "explanation": "语义：“违反”指违背规定或法则，隧道与大山之间不存在违反关系，句意荒谬。"}, {"text": "拜访", "is_correct": false, "explanation": "搭配：“拜访”的主体须是人，隧道不能拜访大山。"}, {"text": "逃离", "is_correct": false, "explanation": "语义：“逃离”表示躲开某个地方或处境，隧道不会逃离大山，句意荒谬。"}], "explanations": {"贯穿": "贯穿指通过、穿通。此处说隧道穿透了这座大山，语义和搭配都吻合。", "违反": "语义：“违反”指违背规定或法则，隧道与大山之间不存在违反关系，句意荒谬。", "拜访": "搭配：“拜访”的主体须是人，隧道不能拜访大山。", "逃离": "语义：“逃离”表示躲开某个地方或处境，隧道不会逃离大山，句意荒谬。"}, "sentence_index": 6, "correct_answer": "贯穿"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "飞机贯穿了雪山，抵达了目的地。", "explanation": "这里应该用〈飞越〉。飞越指从空中越过，飞机是从山顶上方飞过，不能说飞机贯穿雪山。"}, {"text": "我们在这台电脑上贯穿了一个游戏。", "explanation": "这里应该用〈玩〉。贯穿指道路、河流等从一地通到另一地，不能用于游戏；在电脑上玩游戏应说玩。"}, {"text": "政府在这里贯穿了一个车站。", "explanation": "这里应该用〈设立〉。设立指建立、设置机构或设施，“贯穿”表示道路等从一地通到另一地，不能用来说在此设立车站。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0bbee471-ed91-4ad7-9c7d-e91e67c30138') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21450, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这条河被贯穿了整个县。", "corrected_sentence": "这条河贯穿了整个县。", "error_description": "“被”误用：“贯穿”是及物动词，“这条河”是施事，不能用“被”把它变成受事，应去掉“被”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0bbee471-ed91-4ad7-9c7d-e91e67c30138') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21450, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这条新路贯穿着了整个县城。", "corrected_sentence": "这条新路贯穿了整个县城。", "error_description": "“贯穿”后同时用了“着”和“了”，两个体标重复，只能保留“了”，应为「贯穿了整个县城」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0bbee471-ed91-4ad7-9c7d-e91e67c30138') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
