INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21460, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "拿出东西让人需要。", "primary_collocate": null, "pronunciation": "gōng jǐ", "ipa": "kʊŋ˥ tɕi˨˩˦", "syllable_count": 2, "sentences": [{"text": "这家工厂供给全城的电。", "target_word": "供给", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农民供给城里人新鲜的菜。", "target_word": "供给", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府供给灾区食物和水。", "target_word": "供给", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山上的泉水供给全村人用水。", "target_word": "供给", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司供给员工免费午饭。", "target_word": "供给", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条河供给了整个城市的水。", "target_word": "供给", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸每月供给我生活费。", "target_word": "供给", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个农场一直供给学校牛奶。", "target_word": "供给", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座水库每天供给周边三个县的农田用水。", "target_word": "供给", "complexity_tier": "T3", "furigana": "zhè zuò shuǐkù měitiān gōngjǐ zhōubiān sān gè xiàn de nóngtián yòngshuǐ", "sentence_source": "generated"}, {"text": "妈妈供给着弟弟上学的钱。", "target_word": "供给", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "供给了", "label": "体标"}, {"form": "供给着", "label": "体标"}, {"form": "供給", "label": "繁体"}], "register": "书面", "sense_fingerprint": "拿出物资、钱财等，满足别人的需要", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be5ee50c-f9af-43f9-b71d-60fc13a41298') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21460, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "供给", "is_correct": true, "explanation": "正确答案。供给 gōng jǐ，意思是拿出物资供人使用。"}, {"text": "攻击", "is_correct": false, "explanation": "gōngjī（第一声）与 gōng jǐ（第三声）第二音节声调不同，意思是攻击。"}, {"text": "恭喜", "is_correct": false, "explanation": "xǐ 与 jǐ 声母不同（x 与 j），声调相同，意思是祝贺。"}, {"text": "功绩", "is_correct": false, "explanation": "jì（第四声）与 jǐ（第三声）声调不同，意思是功绩。"}, {"text": "共计", "is_correct": false, "explanation": "gòng jì 两个音节的声调都与 gōng jǐ 不同，意思是总计。"}], "explanations": {"供给": "正确答案。供给 gōng jǐ，意思是拿出物资供人使用。", "攻击": "gōngjī（第一声）与 gōng jǐ（第三声）第二音节声调不同，意思是攻击。", "恭喜": "xǐ 与 jǐ 声母不同（x 与 j），声调相同，意思是祝贺。", "功绩": "jì（第四声）与 jǐ（第三声）声调不同，意思是功绩。", "共计": "gòng jì 两个音节的声调都与 gōng jǐ 不同，意思是总计。"}, "sentence_index": null, "correct_answer": "供给"}, "level_3": {"options": [{"text": "供给", "is_correct": true, "explanation": "“供给”指拿出电力供全城使用，与“这家工厂”“全城的电”相符。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”的宾语应是食物，不能说“吃全城的电”。"}, {"text": "聊天", "is_correct": false, "explanation": "配价：“聊天”是不及物动词，不能带“全城的电”作宾语。"}, {"text": "欣赏", "is_correct": false, "explanation": "语义：“欣赏”的对象是可以赏玩的事物，电不能被欣赏。"}], "explanations": {"供给": "“供给”指拿出电力供全城使用，与“这家工厂”“全城的电”相符。", "吃": "搭配：“吃”的宾语应是食物，不能说“吃全城的电”。", "聊天": "配价：“聊天”是不及物动词，不能带“全城的电”作宾语。", "欣赏": "语义：“欣赏”的对象是可以赏玩的事物，电不能被欣赏。"}, "sentence_index": 0, "correct_answer": "供给"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "老师每周向学生供给一个难题。", "explanation": "这里应该用〈布置〉。供给指拿出物资、钱财给人用，难题要说布置。"}, {"text": "这次旅行供给了我很多快乐。", "explanation": "这里应该用〈带给〉。供给指把物资、钱财拿出来给人用，快乐是感受，不能被供给。"}, {"text": "志愿者给灾区供给了很多温暖。", "explanation": "这里应该用〈送〉。供给面向物资、能源，温暖是情感，应说“给灾区送温暖”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26accaa6-266c-48d1-a7a2-07e94e88f0e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21460, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "供给", "is_correct": true, "explanation": "“供给”指定期拿出生活费给人用，与“爸爸每月”“生活费”相符。"}, {"text": "批评", "is_correct": false, "explanation": "搭配：“批评”的宾语应是人或行为，不能说“批评生活费”。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：“洗”的对象应是可以洗涤的东西，生活费不能被洗。"}, {"text": "赚", "is_correct": false, "explanation": "语义：“赚”是自己挣得钱，句中是给我钱，不能说“赚我生活费”。"}], "explanations": {"供给": "“供给”指定期拿出生活费给人用，与“爸爸每月”“生活费”相符。", "批评": "搭配：“批评”的宾语应是人或行为，不能说“批评生活费”。", "洗": "搭配：“洗”的对象应是可以洗涤的东西，生活费不能被洗。", "赚": "语义：“赚”是自己挣得钱，句中是给我钱，不能说“赚我生活费”。"}, "sentence_index": 6, "correct_answer": "供给"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "学校供给了他很多鼓励。", "explanation": "这里应该用〈给予〉。供给用于物资、钱财，鼓励是抽象的情感，应说“给予鼓励”。"}, {"text": "法律供给公民言论自由。", "explanation": "这里应该用〈赋予〉。供给指拿出实物或钱财，权利、自由要说“赋予”。"}, {"text": "这门课供给了我很多兴趣。", "explanation": "这里应该用〈激发〉。兴趣要说“激发”，供给只用于物资、钱财等实物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26accaa6-266c-48d1-a7a2-07e94e88f0e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21460, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "政府供给给居民清洁的饮用水。", "corrected_sentence": "政府供给居民清洁的饮用水。", "error_description": "错误在于“供给”后多加了“给”。“供给”本身已含给予的意思，后面直接接服务对象和物品，不能再加“给”。正确说法是“政府供给居民清洁的饮用水”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26accaa6-266c-48d1-a7a2-07e94e88f0e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21460, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "水站每天向居民的供给桶装水。", "corrected_sentence": "水站每天向居民供给桶装水。", "error_description": "错误在于“供给”前多加了结构助词“的”。“的”会把“供给”变成名词化的修饰成分，后面不能再接宾语“桶装水”，应说“水站每天向居民供给桶装水”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26accaa6-266c-48d1-a7a2-07e94e88f0e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
