INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21466, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "东西最开始是从哪里来的地方。", "primary_collocate": null, "pronunciation": "yuán chǎn dì", "ipa": "ɥɛn˧˥ ʈʂʰan˨˩˦ ti˥˩", "syllable_count": 3, "sentences": [{"text": "你知道苹果的原产地在哪儿吗？", "target_word": "原产地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种花的原产地是南美洲。", "target_word": "原产地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "包装上写着牛奶的原产地。", "target_word": "原产地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "土豆的原产地不是欧洲。", "target_word": "原产地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想去茶叶的原产地看一看。", "target_word": "原产地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个箱子里的橙子，原产地不是美国。", "target_word": "原产地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买东西以前，我会先看原产地。", "target_word": "原产地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同一种米，原产地不同，价格也不同。", "target_word": "原产地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师问我们辣椒的原产地是哪里。", "target_word": "原产地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们到了这种水果的原产地，吃到了最新鲜的。", "target_word": "原产地", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "原产地国家", "label": "复合"}, {"form": "原產地", "label": "繁体"}], "register": "中性", "sense_fingerprint": "东西最开始来自的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55c56dd0-98b1-4f95-a338-eb61429721d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21466, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "原产地", "is_correct": true, "explanation": "正确。问苹果从哪里来，要用“原产地”，指东西最开始来自的地方。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色没有所在地，问“在哪儿”时不能用“颜色”。"}, {"text": "名字", "is_correct": false, "explanation": "语义：“名字”是称呼，不指来源地，与“在哪儿”搭配不当。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：“身高”指人或生物的高矮，苹果不能说身高。"}], "explanations": {"原产地": "正确。问苹果从哪里来，要用“原产地”，指东西最开始来自的地方。", "颜色": "语义：颜色没有所在地，问“在哪儿”时不能用“颜色”。", "名字": "语义：“名字”是称呼，不指来源地，与“在哪儿”搭配不当。", "身高": "体貌：“身高”指人或生物的高矮，苹果不能说身高。"}, "sentence_index": 0, "correct_answer": "原产地"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈的原产地是南京。", "explanation": "这里应该用〈出生地〉。原产地只用于东西的来处，人要说出生地。"}, {"text": "这条江的原产地在云南。", "explanation": "这里应该用〈发源地〉。原产地指东西从哪里来，江河的起点要说发源地。"}, {"text": "这个消息的原产地是一家小报。", "explanation": "这里应该用〈来源〉。原产地指东西从哪里来的地方，消息、信息的来路要说来源。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc5b49a6-d858-4dff-bebe-843f6c757d1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21466, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "原产地", "is_correct": true, "explanation": "正确。买东西前先看东西从哪里来，要用“原产地”。"}, {"text": "体重", "is_correct": false, "explanation": "体貌：“体重”指人或动物的身体重量，不用于买的东西。"}, {"text": "生日", "is_correct": false, "explanation": "语义：东西没有生日，“生日”与“买东西”不相干。"}, {"text": "性别", "is_correct": false, "explanation": "语义：东西没有性别，句中的“看”不指向性别。"}], "explanations": {"原产地": "正确。买东西前先看东西从哪里来，要用“原产地”。", "体重": "体貌：“体重”指人或动物的身体重量，不用于买的东西。", "生日": "语义：东西没有生日，“生日”与“买东西”不相干。", "性别": "语义：东西没有性别，句中的“看”不指向性别。"}, "sentence_index": 6, "correct_answer": "原产地"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "中华文明的原产地是黄河流域。", "explanation": "这里应该用〈发祥地〉。原产地指东西从哪里来，文明、事业的起源地要说发祥地。"}, {"text": "这句名言的原产地是《论语》。", "explanation": "这里应该用〈出处〉。原产地指东西的来源地，话语、文字的出处要说出处。"}, {"text": "他的原产地在城东。", "explanation": "这里应该用〈住处〉。原产地只指东西从哪里来，人住的地方要说住处。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc5b49a6-d858-4dff-bebe-843f6c757d1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21466, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "红茶的原产地中国。", "corrected_sentence": "红茶的原产地在中国。", "error_description": "错误：“原产地”作主语后漏掉了“在”，句子缺少谓语。正确：“红茶的原产地在中国”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc5b49a6-d858-4dff-bebe-843f6c757d1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21466, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我想知道这种咖啡的原产地于。", "corrected_sentence": "我想知道这种咖啡的原产地。", "error_description": "错误：“原产地”后面多加了“于”，把名词误用成了动词“原产于”的形式。正确：“原产地”是名词，后面不加“于”，直接作“知道”的宾语，即“这种咖啡的原产地”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc5b49a6-d858-4dff-bebe-843f6c757d1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
