INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21478, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "山麓就是山的最下面，靠近地面的地方。", "primary_collocate": null, "pronunciation": "shān lù", "ipa": "ʂan˥ lu˥˩", "syllable_count": 2, "sentences": [{"text": "山麓有一片树林。", "target_word": "山麓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们在山麓休息了一会儿。", "target_word": "山麓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山麓很平，山顶很陡。", "target_word": "山麓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山麓住着几户人家。", "target_word": "山麓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "车开到山麓就不能再往前走了。", "target_word": "山麓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山麓的小路两边都是花。", "target_word": "山麓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们在山麓玩儿，没有上山。", "target_word": "山麓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山麓离城里只有五公里。", "target_word": "山麓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在山麓种了一些茶树。", "target_word": "山麓", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨后，山麓的路很滑。", "target_word": "山麓", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "山麓地区", "label": "复合"}], "register": "中性", "sense_fingerprint": "山最下面靠近地面的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '55c56dd0-98b1-4f95-a338-eb61429721d5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21478, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "山麓", "is_correct": true, "explanation": "正确。山麓指山脚，即山的底部与平地相接的部分。"}, {"text": "山雾", "is_correct": false, "explanation": "声母不同：「雾」与「麓」的声母不同，意思是山里的雾气。"}, {"text": "山兔", "is_correct": false, "explanation": "声母不同：「兔」与「麓」只差声母，同为第四声，意思是山里的野兔。"}, {"text": "山腹", "is_correct": false, "explanation": "声母不同：「腹」与「麓」只差声母，同为第四声，意思是山的中部。"}], "explanations": {"山麓": "正确。山麓指山脚，即山的底部与平地相接的部分。", "山雾": "声母不同：「雾」与「麓」的声母不同，意思是山里的雾气。", "山兔": "声母不同：「兔」与「麓」只差声母，同为第四声，意思是山里的野兔。", "山腹": "声母不同：「腹」与「麓」只差声母，同为第四声，意思是山的中部。"}, "sentence_index": null, "correct_answer": "山麓"}, "level_3": {"options": [{"text": "山麓", "is_correct": true, "explanation": "正确。“山麓有一片树林”描述山脚有树林，与句意相符。"}, {"text": "海洋", "is_correct": false, "explanation": "语义：海洋上不说“有一片树林”，与句子描述的地理环境不符。"}, {"text": "太阳", "is_correct": false, "explanation": "语义：太阳上不会有树林，与常识相矛盾。"}, {"text": "手指", "is_correct": false, "explanation": "体貌：“手指”是人身上的部位，不能说有树林。"}], "explanations": {"山麓": "正确。“山麓有一片树林”描述山脚有树林，与句意相符。", "海洋": "语义：海洋上不说“有一片树林”，与句子描述的地理环境不符。", "太阳": "语义：太阳上不会有树林，与常识相矛盾。", "手指": "体貌：“手指”是人身上的部位，不能说有树林。"}, "sentence_index": 0, "correct_answer": "山麓"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这座山的山麓在半山腰。", "explanation": "这里应该用〈半山腰〉。山麓指山脚，半山腰是山的中段，不能用山麓来指。"}, {"text": "山麓插入了云层。", "explanation": "这里应该用〈山峰〉。插入云层的是山峰，山麓在山底。"}, {"text": "山麓是一道狭长的山脊。", "explanation": "这里应该用〈山脊〉。山麓指山脚，狭长隆起的山脊不是山脚，不能说山麓是山脊。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc5b49a6-d858-4dff-bebe-843f6c757d1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21478, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "山麓", "is_correct": true, "explanation": "正确。山麓指山脚，即山的底部与平地相接的部分。"}, {"text": "山庐", "is_correct": false, "explanation": "声调混淆：「庐」与「麓」只差声调（lú / lù），意思是山中的小屋。"}, {"text": "仙露", "is_correct": false, "explanation": "声母不同：「仙」与「山」只差声母（x / sh），韵母与声调相同，意思是仙人所饮的露水。"}, {"text": "山木", "is_correct": false, "explanation": "声母不同：「木」与「麓」只差声母，同为第四声，意思是山上的树木。"}], "explanations": {"山麓": "正确。山麓指山脚，即山的底部与平地相接的部分。", "山庐": "声调混淆：「庐」与「麓」只差声调（lú / lù），意思是山中的小屋。", "仙露": "声母不同：「仙」与「山」只差声母（x / sh），韵母与声调相同，意思是仙人所饮的露水。", "山木": "声母不同：「木」与「麓」只差声母，同为第四声，意思是山上的树木。"}, "sentence_index": null, "correct_answer": "山麓"}, "level_3": {"options": [{"text": "山麓", "is_correct": true, "explanation": "正确。“在山麓玩儿，没有上山”与句意相符。"}, {"text": "山顶", "is_correct": false, "explanation": "语义：在山顶玩儿就等于上了山，与“没有上山”矛盾。"}, {"text": "海底", "is_correct": false, "explanation": "语义：孩子不能在海底玩儿，与句子的场景不符。"}, {"text": "书桌", "is_correct": false, "explanation": "搭配：“玩儿”与“书桌”不搭配，“在书桌玩儿”不是常用的说法。"}], "explanations": {"山麓": "正确。“在山麓玩儿，没有上山”与句意相符。", "山顶": "语义：在山顶玩儿就等于上了山，与“没有上山”矛盾。", "海底": "语义：孩子不能在海底玩儿，与句子的场景不符。", "书桌": "搭配：“玩儿”与“书桌”不搭配，“在书桌玩儿”不是常用的说法。"}, "sentence_index": 6, "correct_answer": "山麓"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这座山的山麓很尖。", "explanation": "这里应该用〈山尖〉。山麓是山的底部，不能用“尖”来形容。"}, {"text": "这座山的山麓比云还高。", "explanation": "这里应该用〈山巅〉。山麓在山底，比云还高要说山巅，不能用山麓。"}, {"text": "我们在路边看见了一座山麓，海拔三千米。", "explanation": "这里应该用〈山〉。山麓指山脚，说整座山的海拔要用山，不能说山麓海拔三千米。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc5b49a6-d858-4dff-bebe-843f6c757d1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21478, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "羊群山麓吃草。", "corrected_sentence": "羊群在山麓吃草。", "error_description": "错误：“山麓”作处所时漏掉了介词“在”。正确：“羊群在山麓吃草”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc5b49a6-d858-4dff-bebe-843f6c757d1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21478, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那只山麓都是茶树。", "corrected_sentence": "那片山麓都是茶树。", "error_description": "错误：量词“只”用于动物或成对物品中的一个，不能修饰“山麓”这一地方。正确：“那片山麓都是茶树”，“片”用于成片的地方。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc5b49a6-d858-4dff-bebe-843f6c757d1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
