INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21484, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "火山是一座会喷出火和烟的山。", "primary_collocate": null, "pronunciation": "huǒ shān", "ipa": "xuɔ˨˩˦ ʂan˥˥", "syllable_count": 2, "sentences": [{"text": "那座火山会喷火，也会冒烟。", "target_word": "火山", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "火山的山顶有个大洞，里面会冒烟。", "target_word": "火山", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在电视上看到过火山喷火。", "target_word": "火山", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们画了一座会喷火的火山。", "target_word": "火山", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个岛上有一座火山，山顶常常冒烟。", "target_word": "火山", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "火山喷出来的烟又黑又热。", "target_word": "火山", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想去看看会冒烟的火山。", "target_word": "火山", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "火山一喷火，附近的人就跑了。", "target_word": "火山", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书上有一张火山的图片，山顶正在冒烟。", "target_word": "火山", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用纸做了一座火山，山顶还会冒烟。", "target_word": "火山", "complexity_tier": "T3", "furigana": "tā yòng zhǐ zuò le yí zuò huǒshān， shāndǐng hái huì màoyān。", "sentence_source": "generated"}], "morphological_forms": [{"form": "座", "label": "量词"}, {"form": "火山灰", "label": "复合"}], "register": "中性", "sense_fingerprint": "火山：会喷火、冒烟的山（日常简单义）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '99e3e928-3fb0-4690-a235-40ae1f64ddce') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21484, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "火山", "is_correct": true, "explanation": "正确：火山会喷火、冒烟，与句中「会喷火，也会冒烟」的描述一致。"}, {"text": "桥", "is_correct": false, "explanation": "语义：桥不会喷火、冒烟，与句中的描述相矛盾。"}, {"text": "大楼", "is_correct": false, "explanation": "语义：大楼是人造建筑，不会主动喷火、冒烟，与句中的描述相矛盾。"}, {"text": "寺庙", "is_correct": false, "explanation": "体貌：寺庙是建筑，外形不是会喷火冒烟的山体。"}], "explanations": {"火山": "正确：火山会喷火、冒烟，与句中「会喷火，也会冒烟」的描述一致。", "桥": "语义：桥不会喷火、冒烟，与句中的描述相矛盾。", "大楼": "语义：大楼是人造建筑，不会主动喷火、冒烟，与句中的描述相矛盾。", "寺庙": "体貌：寺庙是建筑，外形不是会喷火冒烟的山体。"}, "sentence_index": 0, "correct_answer": "火山"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "孩子们画了一条会喷火的火山。", "explanation": "这里应该用〈座〉。「条」用于细长的东西，火山是山体，要用「座」。"}, {"text": "孩子们画了一本会喷火的火山。", "explanation": "这里应该用〈座〉。「本」用于书籍，火山不能用「本」计量。"}, {"text": "孩子们画了一辆会喷火的火山。", "explanation": "这里应该用〈座〉。「辆」用于车辆，火山要用「座」来计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '424c24d8-0068-4da5-9c55-1eed25e62be7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21484, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "火山", "is_correct": true, "explanation": "正确：火山会冒烟，「会冒烟的」修饰的正是火山。"}, {"text": "雪山", "is_correct": false, "explanation": "语义：雪山是覆盖白雪的山，不会冒烟，与「会冒烟的」冲突。"}, {"text": "花园", "is_correct": false, "explanation": "语义：花园是种花草的园地，不会冒烟，句子说不通。"}, {"text": "游泳池", "is_correct": false, "explanation": "体貌：游泳池是注满水的人工池，外形与山不同，也不会冒烟。"}], "explanations": {"火山": "正确：火山会冒烟，「会冒烟的」修饰的正是火山。", "雪山": "语义：雪山是覆盖白雪的山，不会冒烟，与「会冒烟的」冲突。", "花园": "语义：花园是种花草的园地，不会冒烟，句子说不通。", "游泳池": "体貌：游泳池是注满水的人工池，外形与山不同，也不会冒烟。"}, "sentence_index": 6, "correct_answer": "火山"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他用纸做了一只火山，山顶还会冒烟。", "explanation": "这里应该用〈座〉。「只」用于动物，火山要用「座」计量。"}, {"text": "他用纸做了一棵火山，山顶还会冒烟。", "explanation": "这里应该用〈座〉。「棵」用于植物，火山不能用「棵」计量。"}, {"text": "他用纸做了一台火山，山顶还会冒烟。", "explanation": "这里应该用〈座〉。「台」用于机器，火山是山体，应说「座」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '424c24d8-0068-4da5-9c55-1eed25e62be7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21484, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们在岛上看到了一只冒烟的火山。", "corrected_sentence": "我们在岛上看到了一座冒烟的火山。", "error_description": "量词错误：火山应用量词「座」，「只」用于动物，不用于火山。错误形式：一只冒烟的火山；正确形式：一座冒烟的火山。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '424c24d8-0068-4da5-9c55-1eed25e62be7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21484, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这只火山喷发得很厉害，周围的人都跑了。", "corrected_sentence": "这座火山喷发得很厉害，周围的人都跑了。", "error_description": "量词错误：「只」用于动物，火山应用量词「座」。错误形式：这只火山；正确形式：这座火山。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '424c24d8-0068-4da5-9c55-1eed25e62be7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (21486, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "缺乏", "is_correct": true, "explanation": "缺乏与具有构成反义关系：具有某种性质，与缺乏这种性质相对。"}, {"text": "放弃", "is_correct": false, "explanation": "放弃是丢掉、不再坚持，与“具有”没有反义关系。"}, {"text": "推迟", "is_correct": false, "explanation": "推迟是把时间往后拖，与“具有”没有反义关系。"}, {"text": "完成", "is_correct": false, "explanation": "完成是做完某件事，与“具有”没有反义关系。"}], "correct_answer": "缺乏", "explanations": {"缺乏": "缺乏与具有构成反义关系：具有某种性质，与缺乏这种性质相对。", "放弃": "放弃是丢掉、不再坚持，与“具有”没有反义关系。", "推迟": "推迟是把时间往后拖，与“具有”没有反义关系。", "完成": "完成是做完某件事，与“具有”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3eaa67ea-050f-4869-abb9-e94c19b28802') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
